SOURCES = {'plugin': 'import shutil\nfrom pathlib import Path\n\nfrom app.core.config import settings\nfrom app.core.plugin import PluginManager\nfrom app.db.systemconfig_oper import SystemConfigOper\nfrom app.plugins import _PluginBase\nfrom typing import Any, List, Dict, Tuple\nfrom app.log import logger\nfrom app.scheduler import Scheduler\nfrom app.schemas.types import SystemConfigKey\n\n\nclass PluginUnInstall(_PluginBase):\n    # 插件名称\n    plugin_name = "插件彻底卸载"\n    # 插件描述\n    plugin_desc = "删除数据库中已安装插件记录、清理插件文件。"\n    # 插件图标\n    plugin_icon = "https://raw.githubusercontent.com/thsrite/MoviePilot-Plugins/main/icons/uninstall.png"\n    # 插件版本\n    plugin_version = "2.2"\n    # 插件作者\n    plugin_author = "thsrite"\n    # 作者主页\n    author_url = "https://github.com/thsrite"\n    # 插件配置项ID前缀\n    plugin_config_prefix = "pluginuninstall_"\n    # 加载顺序\n    plugin_order = 98\n    # 可使用的用户级别\n    auth_level = 1\n\n    # 私有属性\n    _plugin_ids = []\n    _clear_config = False\n    _clear_data = False\n\n    def init_plugin(self, config: dict = None):\n        if config:\n            self._plugin_ids = config.get("plugin_ids") or []\n            self._clear_config = config.get("clear_config")\n            self._clear_data = config.get("clear_data")\n            if not self._plugin_ids:\n                return\n\n            # 已安装插件\n            install_plugins = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n\n            new_install_plugins = []\n            for install_plugin in install_plugins:\n                if install_plugin in self._plugin_ids:\n                    # 移除插件服务\n                    Scheduler().remove_plugin_job(install_plugin)\n                    # 移除插件\n                    PluginManager().remove_plugin(install_plugin)\n                    # 删除插件文件\n                    plugin_dir = Path(settings.ROOT_PATH) / "app" / "plugins" / install_plugin.lower()\n                    if plugin_dir.exists():\n                        shutil.rmtree(plugin_dir, ignore_errors=True)\n                    if self._clear_config:\n                        # 删除配置\n                        PluginManager().delete_plugin_config(install_plugin)\n                    if self._clear_data:\n                        # 删除插件所有数据\n                        PluginManager().delete_plugin_data(install_plugin)\n                    logger.info(f"插件 {install_plugin} 已卸载")\n                else:\n                    new_install_plugins.append(install_plugin)\n\n            # 保存已安装插件\n            SystemConfigOper().set(SystemConfigKey.UserInstalledPlugins, new_install_plugins)\n\n            self.update_config({\n                "plugin_ids": [],\n                "clear_config": self._clear_config,\n                "clear_data": self._clear_data\n            })\n\n    def get_state(self) -> bool:\n        return False\n\n    @staticmethod\n    def get_command() -> List[Dict[str, Any]]:\n        pass\n\n    def get_api(self) -> List[Dict[str, Any]]:\n        pass\n\n    def get_form(self) -> Tuple[List[dict], Dict[str, Any]]:\n        """\n        拼装插件配置页面，需要返回两块数据：1、页面配置；2、数据结构\n        """\n        # 直接调用修复后的 get_local_plugins 获取选项\n        pluginOptions = self.get_local_plugins()\n        return [\n            {\n                \'component\': \'VForm\',\n                \'content\': [\n                    {\n                        \'component\': \'VRow\',\n                        \'content\': [\n                            {\n                                \'component\': \'VCol\',\n                                \'props\': {\n                                    \'cols\': 12,\n                                    \'md\': 3\n                                },\n                                \'content\': [\n                                    {\n                                        \'component\': \'VSwitch\',\n                                        \'props\': {\n                                            \'model\': \'clear_config\',\n                                            \'label\': \'清除配置(配置信息)\',\n                                        }\n                                    }\n                                ]\n                            },\n                            {\n                                \'component\': \'VCol\',\n                                \'props\': {\n                                    \'cols\': 12,\n                                    \'md\': 3\n                                },\n                                \'content\': [\n                                    {\n                                        \'component\': \'VSwitch\',\n                                        \'props\': {\n                                            \'model\': \'clear_data\',\n                                            \'label\': \'清除数据(运行数据)\',\n                                        }\n                                    }\n                                ]\n                            },\n                            {\n                                \'component\': \'VCol\',\n                                \'props\': {\n                                    \'cols\': 12,\n                                    \'md\': 6\n                                },\n                                \'content\': [\n                                    {\n                                        \'component\': \'VSelect\',\n                                        \'props\': {\n                                            \'multiple\': True,\n                                            \'chips\': True,\n                                            \'model\': \'plugin_ids\',\n                                            \'label\': \'卸载插件\',\n                                            \'items\': pluginOptions\n                                        }\n                                    }\n                                ]\n                            },\n                        ]\n                    },\n                    {\n                        \'component\': \'VRow\',\n                        \'content\': [\n                            {\n                                \'component\': \'VCol\',\n                                \'props\': {\n                                    \'cols\': 12,\n                                },\n                                \'content\': [\n                                    {\n                                        \'component\': \'VAlert\',\n                                        \'props\': {\n                                            \'type\': \'info\',\n                                            \'variant\': \'tonal\',\n                                            \'text\': \'删除数据库中已安装插件记录、清理插件文件。\'\n                                        }\n                                    }\n                                ]\n                            }\n                        ]\n                    },\n                ]\n            }\n        ], {\n            "plugin_ids": [],\n            "clear_config": False,\n            "clear_data": False\n        }\n\n    @staticmethod\n    def get_local_plugins():\n        """\n        获取本地插件\n        (修改为只获取已安装插件，避免 compare_version 和市场查询)\n        """\n        plugin_manager = PluginManager()\n        # 获取本地所有插件实例\n        local_plugin_instances = plugin_manager.get_local_plugins() or []\n\n        # 过滤出已安装的插件\n        installed_plugins = [p for p in local_plugin_instances if getattr(p, \'installed\', False)]\n\n        # 根据插件顺序排序 (可选)\n        sorted_plugins = sorted(installed_plugins, key=lambda p: getattr(p, \'plugin_order\', 1000))\n\n        # 构建 VSelect 需要的选项列表\n        plugin_options = []\n        for plugin in sorted_plugins:\n             # 确保 getattr 有默认值\n             plugin_name = getattr(plugin, \'plugin_name\', getattr(plugin, \'id\', \'未知插件\'))\n             plugin_version = getattr(plugin, \'plugin_version\', \'N/A\')\n             plugin_id = getattr(plugin, \'id\', None)\n             if plugin_id:\n                 plugin_options.append({\n                     "title": f"{plugin_name} v{plugin_version}",\n                     "value": plugin_id\n                 })\n\n        return plugin_options\n\n    def get_page(self) -> List[dict]:\n        pass\n\n    def stop_service(self):\n        """\n        退出插件\n        """\n        pass', 'manager': 'import ast\nimport asyncio\nimport concurrent\nimport concurrent.futures\nimport importlib.util\nimport inspect\nimport os\nimport posixpath\nimport shutil\nimport sys\nimport threading\nimport time\nimport traceback\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional, Type, Union, Callable, Tuple\n\nfrom fastapi import HTTPException\nfrom starlette import status\nfrom watchfiles import watch\n\nfrom app import schemas\nfrom app.core.cache import fresh, async_fresh\nfrom app.core.config import settings\nfrom app.core.event import eventmanager\nfrom app.db.plugindata_oper import PluginDataOper\nfrom app.db.systemconfig_oper import SystemConfigOper\nfrom app.helper.server import MoviePilotServerHelper\nfrom app.helper.plugin import PluginHelper\nfrom app.helper.sites import SitesHelper  # noqa\nfrom app.log import logger\nfrom app.schemas.types import EventType, SystemConfigKey\nfrom app.utils.crypto import RSAUtils\nfrom app.utils.mixins import ConfigReloadMixin\nfrom app.utils.object import ObjectUtils\nfrom app.utils.singleton import Singleton\nfrom app.utils.string import StringUtils\nfrom app.utils.system import SystemUtils\n\n\nclass PluginManager(ConfigReloadMixin, metaclass=Singleton):\n    """插件管理器"""\n    CONFIG_WATCH = {"DEV", "PLUGIN_AUTO_RELOAD", "PLUGIN_LOCAL_REPO_PATHS"}\n\n    def __init__(self):\n        # 插件列表\n        self._plugins: dict = {}\n        # 运行态插件列表\n        self._running_plugins: dict = {}\n        # 配置Key\n        self._config_key: str = "plugin.%s"\n        # 监控线程\n        self._monitor_thread: Optional[threading.Thread] = None\n        # 监控停止事件\n        self._stop_monitor_event = threading.Event()\n        # 本地插件同步写入运行目录后的短时忽略窗口\n        self._recent_local_sync: Dict[str, float] = {}\n        # 插件智能体工具注册表缓存，插件启停或配置生效时主动失效。\n        self._plugin_agent_tools_cache: Dict[str, List[Dict[str, Any]]] = {}\n        self._plugin_agent_tools_cache_lock = threading.Lock()\n        self._plugin_agent_tools_revision: int = 0\n        # 开发者模式监测插件修改\n        if settings.DEV or settings.PLUGIN_AUTO_RELOAD:\n            self.__start_monitor()\n\n    def init_config(self):\n        # 停止已有插件\n        self.stop()\n        # 启动插件\n        self.start()\n\n    def start(self, pid: Optional[str] = None):\n        """\n        启动加载插件\n        :param pid: 插件ID，为空加载所有插件\n        """\n\n        def check_module(module: Any):\n            """\n            检查模块\n            """\n            if not hasattr(module, \'init_plugin\') or not hasattr(module, "plugin_name"):\n                return False\n            return True\n\n        # 已安装插件\n        installed_plugins = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        # 扫描插件目录，只加载符合条件的插件\n        plugins = self._load_selective_plugins(pid, installed_plugins, check_module)\n        # 排序\n        plugins.sort(key=lambda x: x.plugin_order if hasattr(x, "plugin_order") else 0)\n        for plugin in plugins:\n            plugin_id = plugin.__name__\n            if pid and plugin_id != pid:\n                continue\n            try:\n                # 判断插件是否满足认证要求，如不满足则不进行实例化\n                if not self.__set_and_check_auth_level(plugin=plugin):\n                    # 如果是插件热更新实例，这里则进行替换\n                    if plugin_id in self._plugins:\n                        self._plugins[plugin_id] = plugin\n                    continue\n                # 存储Class\n                self._plugins[plugin_id] = plugin\n                # 生成实例\n                plugin_obj = plugin()\n                # 生效插件配置\n                plugin_obj.init_plugin(self.get_plugin_config(plugin_id))\n                # 存储运行实例\n                self._running_plugins[plugin_id] = plugin_obj\n                logger.info(f"加载插件：{plugin_id} 版本：{plugin_obj.plugin_version}")\n                # 启用的插件才设置事件注册状态可用\n                if plugin_obj.get_state():\n                    eventmanager.enable_event_handler(plugin)\n                else:\n                    eventmanager.disable_event_handler(plugin)\n            except Exception as err:\n                logger.error(f"加载插件 {plugin_id} 出错：{str(err)} - {traceback.format_exc()}")\n        self.clear_plugin_agent_tools_cache()\n\n    def init_plugin(self, plugin_id: str, conf: dict):\n        """\n        初始化插件\n        :param plugin_id: 插件ID\n        :param conf: 插件配置\n        """\n        plugin = self._running_plugins.get(plugin_id)\n        if not plugin:\n            return\n        # 初始化插件\n        plugin.init_plugin(conf)\n        # 检查插件状态并启用/禁用事件处理器\n        if plugin.get_state():\n            # 启用插件类的事件处理器\n            eventmanager.enable_event_handler(type(plugin))\n        else:\n            # 禁用插件类的事件处理器\n            eventmanager.disable_event_handler(type(plugin))\n        self.clear_plugin_agent_tools_cache()\n\n    def clear_plugin_agent_tools_cache(self) -> None:\n        """\n        清空插件智能体工具注册表缓存。\n        """\n        with self._plugin_agent_tools_cache_lock:\n            self._plugin_agent_tools_cache.clear()\n            self._plugin_agent_tools_revision += 1\n\n    def get_plugin_agent_tools_revision(self) -> int:\n        """\n        获取插件智能体工具注册表版本号。\n        """\n        with self._plugin_agent_tools_cache_lock:\n            return self._plugin_agent_tools_revision\n\n    def stop(self, pid: Optional[str] = None):\n        """\n        停止插件服务\n        :param pid: 插件ID，为空停止所有插件\n        """\n        # 停止插件\n        if pid:\n            logger.info(f"正在停止插件 {pid}...")\n            plugin_obj = self._running_plugins.get(pid)\n            if not plugin_obj:\n                # 指定插件可能在上次加载时已导入模块但初始化失败，此时不会进入运行态列表。\n                # 仍需继续清理类缓存和 sys.modules，避免后续热重载反复复用旧模块。\n                logger.debug(f"插件 {pid} 不存在或未加载")\n                plugins = {}\n            else:\n                plugins = {pid: plugin_obj}\n        else:\n            logger.info("正在停止所有插件...")\n            plugins = self._running_plugins\n        for plugin_id, plugin in plugins.items():\n            eventmanager.disable_event_handler(type(plugin))\n            self.__stop_plugin(plugin)\n        # 清空对象\n        if pid:\n            # 清空指定插件\n            self._plugins.pop(pid, None)\n            self._running_plugins.pop(pid, None)\n            # 清除插件模块缓存，包括所有子模块\n            self._clear_plugin_modules(pid)\n        else:\n            # 清空\n            self._plugins = {}\n            self._running_plugins = {}\n            # 清除所有插件模块缓存\n            self._clear_plugin_modules()\n        self.clear_plugin_agent_tools_cache()\n        logger.info("插件停止完成")\n\n    @staticmethod\n    def _load_selective_plugins(pid: Optional[str], installed_plugins: List[str],\n                                check_module_func: Callable) -> List[Any]:\n        """\n        选择性加载插件，只import符合条件的插件\n        :param pid: 指定插件ID，为空则加载所有已安装插件\n        :param installed_plugins: 已安装插件列表\n        :param check_module_func: 模块检查函数\n        :return: 插件类列表\n        """\n        import importlib\n\n        plugins = []\n        plugins_dir = settings.ROOT_PATH / "app" / "plugins"\n\n        if not plugins_dir.exists():\n            logger.warning(f"插件目录不存在：{plugins_dir}")\n            return plugins\n\n        # 确定需要加载的插件目录名称列表\n        if pid:\n            # 加载指定插件\n            target_plugins = [pid.lower()]\n        else:\n            # 加载已安装插件\n            target_plugins = [plugin_id.lower() for plugin_id in installed_plugins]\n\n        if not target_plugins:\n            logger.debug("没有需要加载的插件")\n            return plugins\n\n        # 扫描plugins目录\n        _loaded_modules = set()\n        for plugin_dir in plugins_dir.iterdir():\n            if not plugin_dir.is_dir() or plugin_dir.name.startswith(\'_\'):\n                continue\n\n            # 检查是否是需要加载的插件\n            if plugin_dir.name not in target_plugins:\n                logger.debug(f"跳过插件目录：{plugin_dir.name}（不在加载列表中）")\n                continue\n\n            # 检查__init__.py是否存在\n            init_file = plugin_dir / "__init__.py"\n            if not init_file.exists():\n                logger.debug(f"跳过插件目录：{plugin_dir.name}（缺少__init__.py）")\n                continue\n\n            try:\n                # 构建模块名\n                module_name = f"app.plugins.{plugin_dir.name}"\n                logger.debug(f"正在导入插件模块：{module_name}")\n\n                # 导入模块\n                module = importlib.import_module(module_name)\n\n                # 检查模块中的类\n                for name, obj in module.__dict__.items():\n                    if name.startswith(\'_\') or not isinstance(obj, type):\n                        continue\n                    if name in _loaded_modules:\n                        continue\n                    if check_module_func(obj):\n                        _loaded_modules.add(name)\n                        plugins.append(obj)\n                        logger.debug(f"找到符合条件的插件类：{name}")\n                        break\n\n            except Exception as err:\n                logger.error(f"加载插件 {plugin_dir.name} 失败：{str(err)} - {traceback.format_exc()}")\n\n        return plugins\n\n    @property\n    def running_plugins(self) -> Dict[str, Any]:\n        """\n        获取运行态插件列表\n        :return: 运行态插件列表\n        """\n        return self._running_plugins\n\n    @property\n    def plugins(self) -> Dict[str, Any]:\n        """\n        获取插件列表\n        :return: 插件列表\n        """\n        return self._plugins\n\n    def on_config_changed(self):\n        self.reload_monitor()\n\n    def get_reload_name(self) -> str:\n        return "插件文件修改监测"\n\n    def reload_monitor(self):\n        """\n        重新加载插件文件修改监测\n        """\n        if settings.DEV or settings.PLUGIN_AUTO_RELOAD:\n            # 先关闭已有监测，再重新启动\n            self.stop_monitor()\n            self.__start_monitor()\n        else:\n            self.stop_monitor()\n\n    def __start_monitor(self):\n        """\n        启用监测插件文件修改监测\n        """\n        if self._monitor_thread and self._monitor_thread.is_alive():\n            logger.info("插件文件修改监测已经在运行中...")\n            return\n\n        logger.info("开始监测插件文件修改...")\n\n        # 在启动新线程之前，确保停止事件是清除状态\n        self._stop_monitor_event.clear()\n\n        # 创建并启动监控线程\n        self._monitor_thread = threading.Thread(\n            target=self._run_file_watcher,\n            daemon=True\n        )\n        self._monitor_thread.start()\n\n    def stop_monitor(self):\n        """\n        停止监测插件文件修改监测\n        """\n        if self._monitor_thread and self._monitor_thread.is_alive():\n            logger.info("正在停止插件文件修改监测...")\n            self._stop_monitor_event.set()\n            self._monitor_thread.join(timeout=5)\n            if self._monitor_thread.is_alive():\n                logger.warning("插件文件修改监测线程在5秒内未能正常停止。")\n            self._monitor_thread = None\n            logger.info("插件文件修改监测停止完成")\n        else:\n            logger.info("未启用插件文件修改监测，无需停止")\n\n    def _run_file_watcher(self):\n        """\n        运行 watchfiles 监视器的主循环。\n        """\n        # 监视插件目录\n        plugin_paths = [str(settings.ROOT_PATH / "app" / "plugins")]\n        for local_repo_path in PluginHelper.get_local_repo_paths():\n            if local_repo_path.exists() and local_repo_path.is_dir():\n                plugin_paths.append(str(local_repo_path))\n        logger.info(">>> 监控线程已启动，准备进入watch循环...")\n        # 使用 watchfiles 监视目录变化，并响应变化事件\n        # Todo: yield_on_timeout = True 时，每秒检查停止事件，会返回空集合；后续可以考虑用来做心跳之类的功能？\n        for changes in watch(*plugin_paths, stop_event=self._stop_monitor_event, rust_timeout=1000,\n                             yield_on_timeout=True):\n            # 如果收到停止事件，退出循环\n            if not changes:\n                continue\n\n            # 处理变化事件\n            plugins_to_reload = set()\n            local_plugins_to_sync = {}\n            for _change_type, path_str in changes:\n                event_path = Path(path_str)\n\n                # 跳过 pycache 目录中的文件\n                if "__pycache__" in event_path.parts:\n                    continue\n\n                if event_path.name == "requirements.txt":\n                    candidate = self._get_local_plugin_candidate_from_path(event_path)\n                    if candidate:\n                        if candidate.get("compatible") is False:\n                            logger.info(\n                                f"检测到本地插件 {candidate.get(\'id\')} 依赖文件变化，"\n                                f"但跳过处理：{candidate.get(\'skip_reason\')}"\n                            )\n                            continue\n                        logger.warn(f"检测到本地插件 {candidate.get(\'id\')} 依赖文件变化，请重新安装本地插件以安装依赖")\n                    continue\n\n                federated_change = self._get_federated_plugin_change(event_path)\n                if federated_change:\n                    pid, candidate, remote_entry_ready = federated_change\n                    # 运行目录由构建方直接写入；外部本地仓库只在入口完整时同步运行副本。\n                    if candidate and remote_entry_ready:\n                        if candidate.get("compatible") is False:\n                            logger.info(\n                                f"检测到本地插件 {pid} 联邦构建产物变化，"\n                                f"但跳过同步：{candidate.get(\'skip_reason\')}"\n                            )\n                        elif pid not in local_plugins_to_sync:\n                            local_plugins_to_sync[pid] = (candidate, event_path, False)\n                    continue\n\n                # 跳过非 .py 文件\n                if not event_path.name.endswith(".py"):\n                    continue\n\n                # 解析插件ID\n                runtime_pid = self._get_plugin_id_from_path(event_path)\n                local_candidate = self._get_local_plugin_candidate_from_path(event_path) if not runtime_pid else None\n                if runtime_pid:\n                    last_sync_time = self._recent_local_sync.get(runtime_pid)\n                    if last_sync_time and time.time() - last_sync_time < 2:\n                        continue\n                    # 运行目录变化只重载，不能反向触发本地同步。\n                    plugins_to_reload.add(runtime_pid)\n                elif local_candidate:\n                    if local_candidate.get("compatible") is False:\n                        package_version = local_candidate.get("package_version")\n                        source_root = f"plugins.{package_version}" if package_version else "plugins"\n                        logger.info(\n                            f"检测到本地插件 {local_candidate.get(\'id\')} 文件变化，来源：{source_root}，"\n                            f"文件：{event_path}，但跳过同步：{local_candidate.get(\'skip_reason\')}"\n                        )\n                        continue\n                    local_plugins_to_sync[local_candidate.get("id")] = (local_candidate, event_path, True)\n\n            for pid, (candidate, event_path, should_reload) in local_plugins_to_sync.items():\n                package_version = candidate.get("package_version")\n                source_root = f"plugins.{package_version}" if package_version else "plugins"\n                change_name = "Python 文件" if should_reload else "联邦构建产物"\n                logger.info(f"检测到本地插件 {pid} {change_name}变化，来源：{source_root}，文件：{event_path}")\n                if self._sync_local_plugin_if_installed(pid, candidate) and should_reload:\n                    plugins_to_reload.add(pid)\n\n            # 触发重载\n            if plugins_to_reload:\n                logger.info(f"检测到插件文件变化，准备重载: {list(plugins_to_reload)}")\n                for pid in plugins_to_reload:\n                    try:\n                        self.reload_plugin(pid)\n                    except Exception as e:\n                        logger.error(f"插件 {pid} 热重载失败: {e}", exc_info=True)\n\n    def _get_federated_plugin_change(\n        self,\n        event_path: Path,\n    ) -> Optional[Tuple[str, Optional[dict], bool]]:\n        """\n        识别运行态 Vue 插件声明目录内的构建产物变化。\n\n        :return: 插件 ID、本地仓库候选和联邦入口是否完整；非联邦目录变化返回 None。\n        """\n        try:\n            event_path = event_path.resolve()\n            candidate = self._get_local_plugin_candidate_from_path(event_path)\n            if candidate:\n                pid = candidate.get("id")\n                plugin_dir = Path(candidate.get("path")).resolve()\n            else:\n                runtime_root = (settings.ROOT_PATH / "app" / "plugins").resolve()\n                if not event_path.is_relative_to(runtime_root):\n                    return None\n                relative_parts = event_path.relative_to(runtime_root).parts\n                if not relative_parts:\n                    return None\n                plugin_dir = runtime_root / relative_parts[0]\n                pid = next(\n                    (\n                        plugin_id\n                        for plugin_id in self._running_plugins\n                        if plugin_id.lower() == relative_parts[0].lower()\n                    ),\n                    None,\n                )\n\n            if not pid:\n                return None\n            plugin = self._running_plugins.get(pid)\n            if not plugin:\n                return None\n\n            render_mode, dist_path = plugin.get_render_mode()\n            if render_mode != "vue" or not isinstance(dist_path, str) or not dist_path:\n                return None\n\n            relative_dist_path = Path(dist_path)\n            if relative_dist_path.is_absolute() or ".." in relative_dist_path.parts or "\\\\" in dist_path:\n                return None\n\n            plugin_dir = plugin_dir.resolve()\n            dist_dir = (plugin_dir / relative_dist_path).resolve()\n            if (\n                dist_dir == plugin_dir\n                or not dist_dir.is_relative_to(plugin_dir)\n                or not event_path.is_relative_to(dist_dir)\n            ):\n                return None\n\n            remote_entry = dist_dir / "remoteEntry.js"\n            remote_entry_ready = (\n                remote_entry.is_file()\n                and remote_entry.resolve().is_relative_to(plugin_dir)\n            )\n            return pid, candidate, remote_entry_ready\n        except Exception as e:\n            logger.error(f"识别插件联邦构建产物变化时出错: {e}")\n            return None\n\n    @staticmethod\n    def _get_plugin_id_from_path(event_path: Path) -> Optional[str]:\n        """\n        根据文件路径解析出插件的ID。\n        :param event_path: 被修改文件的 Path 对象。\n        :return: 插件ID字符串，如果不是有效插件文件则返回 None。\n        """\n        try:\n            event_path = event_path.resolve()\n            plugins_root = settings.ROOT_PATH / "app" / "plugins"\n            # 确保修改的文件在 plugins 目录下\n            if not event_path.is_relative_to(plugins_root):\n                return None\n\n            try:\n                plugin_dir_name = event_path.relative_to(plugins_root).parts[0]\n                plugin_dir = plugins_root / plugin_dir_name\n            except (ValueError, IndexError):\n                return None\n\n            init_file = plugin_dir / "__init__.py"\n            if not init_file.exists():\n                return None\n\n            # 读取 __init__.py 文件，查找插件主类名\n            with open(init_file, "r", encoding="utf-8", errors="replace") as f:\n                source_code = f.read()\n\n            tree = ast.parse(source_code)\n\n            # 遍历AST，查找继承自 _PluginBase 的类\n            for node in ast.walk(tree):\n                # 检查节点是否为类定义\n                if isinstance(node, ast.ClassDef):\n                    # 遍历该类的所有基类\n                    for base in node.bases:\n                        # 检查基类是否是我们寻找的 _PluginBase\n                        # ast.Name 用于处理简单的基类名\n                        if isinstance(base, ast.Name) and base.id == \'_PluginBase\':\n                            # 返回这个类的名字\n                            return node.name\n\n            return None\n        except Exception as e:\n            logger.error(f"从路径解析插件ID时出错: {e}")\n            return None\n\n    @staticmethod\n    def _get_local_plugin_candidate_from_path(event_path: Path) -> Optional[dict]:\n        """\n        根据本地插件仓库路径解析具体插件候选，保留 plugins/plugins.v2 来源差异\n        """\n        try:\n            event_path = event_path.resolve()\n            for local_repo_path in PluginHelper.get_local_repo_paths():\n                if not local_repo_path.exists() or not local_repo_path.is_dir():\n                    continue\n                if not event_path.is_relative_to(local_repo_path):\n                    continue\n                try:\n                    relative_parts = event_path.relative_to(local_repo_path).parts\n                except (ValueError, IndexError):\n                    continue\n                if len(relative_parts) < 2:\n                    continue\n                if relative_parts[0] == "plugins":\n                    package_version = ""\n                elif relative_parts[0].startswith("plugins."):\n                    package_version = relative_parts[0].split(".", 1)[1]\n                else:\n                    continue\n                plugin_dir_name = relative_parts[1]\n                candidate = PluginHelper().get_local_plugin_candidate(\n                    pid=plugin_dir_name,\n                    package_version=package_version,\n                    repo_path=local_repo_path,\n                    strict_compat=False,\n                    strict_system_version=not settings.DEV\n                )\n                if candidate:\n                    return candidate\n            return None\n        except Exception as e:\n            logger.error(f"从本地插件仓库路径解析插件候选时出错: {e}")\n            return None\n\n    @staticmethod\n    def _sync_local_plugin_if_installed(pid: str, candidate: Optional[dict] = None) -> bool:\n        """\n        已安装本地插件源码变化时，同步到运行目录\n        """\n        installed_plugins = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        if pid not in installed_plugins:\n            logger.info(f"本地插件 {pid} 尚未安装，跳过自动同步和热重载")\n            return False\n\n        candidate = candidate or PluginHelper().get_local_plugin_candidate(pid)\n        if not candidate:\n            return False\n        if candidate.get("compatible") is False:\n            logger.info(f"本地插件 {pid} 不满足同步条件，跳过自动同步：{candidate.get(\'skip_reason\')}")\n            return False\n\n        source_dir = Path(candidate.get("path"))\n        dest_dir = settings.ROOT_PATH / "app" / "plugins" / pid.lower()\n        try:\n            if source_dir.resolve() == dest_dir.resolve():\n                return True\n            if dest_dir.exists():\n                shutil.rmtree(dest_dir, ignore_errors=True)\n            shutil.copytree(\n                source_dir,\n                dest_dir,\n                dirs_exist_ok=True,\n                ignore=shutil.ignore_patterns("__pycache__", "*.pyc", ".DS_Store", "node_modules")\n            )\n            PluginManager()._recent_local_sync[pid] = time.time()\n            logger.info(f"已同步本地插件 {pid}：{source_dir} -> {dest_dir}")\n            return True\n        except Exception as e:\n            logger.error(f"同步本地插件 {pid} 失败：{e}")\n            return False\n\n    @staticmethod\n    def __stop_plugin(plugin: Any):\n        """\n        停止插件\n        :param plugin: 插件实例\n        """\n        try:\n            # 关闭数据库\n            if hasattr(plugin, "close"):\n                plugin.close()\n            # 关闭插件\n            if hasattr(plugin, "stop_service"):\n                plugin.stop_service()\n        except Exception as e:\n            logger.warn(f"停止插件 {plugin.get_name()} 时发生错误: {str(e)}")\n\n    def remove_plugin(self, plugin_id: str):\n        """\n        从内存中移除一个插件\n        :param plugin_id: 插件ID\n        """\n        self.stop(plugin_id)\n\n    def reload_plugin(self, plugin_id: str):\n        """\n        将一个插件重新加载到内存\n        :param plugin_id: 插件ID\n        """\n        # 先移除插件实例\n        self.stop(plugin_id)\n        # 重新加载\n        self.start(plugin_id)\n        # 广播事件\n        eventmanager.send_event(EventType.PluginReload, data={"plugin_id": plugin_id})\n\n    @staticmethod\n    def _clear_plugin_modules(plugin_id: Optional[str] = None):\n        """\n        清除插件及其所有子模块的缓存\n        :param plugin_id: 插件ID\n        """\n\n        # 构建插件模块前缀\n        if plugin_id:\n            plugin_module_prefix = f"app.plugins.{plugin_id.lower()}"\n        else:\n            plugin_module_prefix = "app.plugins"\n\n        # 收集需要删除的模块名（创建模块名列表的副本以避免迭代时修改字典）\n        modules_to_remove = []\n        for module_name in list(sys.modules.keys()):\n            if module_name == plugin_module_prefix or module_name.startswith(plugin_module_prefix + "."):\n                modules_to_remove.append(module_name)\n\n        # 删除模块\n        for module_name in modules_to_remove:\n            try:\n                del sys.modules[module_name]\n                logger.debug(f"已清除插件模块缓存：{module_name}")\n            except KeyError:\n                # 模块可能已经被删除\n                pass\n\n        importlib.invalidate_caches()\n        logger.debug("已清除查找器的缓存")\n\n        if plugin_id:\n            if modules_to_remove:\n                logger.info(f"插件 {plugin_id} 共清除 {len(modules_to_remove)} 个模块缓存：{modules_to_remove}")\n            else:\n                logger.debug(f"插件 {plugin_id} 没有找到需要清除的模块缓存")\n\n    def sync(self) -> List[str]:\n        """\n        安装本地不存在或需要更新的插件\n        """\n\n        def install_plugin(plugin):\n            start_time = time.time()\n            state, msg = PluginHelper().install(pid=plugin.id, repo_url=plugin.repo_url, force_install=True)\n            elapsed_time = time.time() - start_time\n            if state:\n                MoviePilotServerHelper.install_plugin_reg(plugin_id=plugin.id, repo_url=plugin.repo_url)\n                logger.info(\n                    f"插件 {plugin.plugin_name} 安装成功，版本：{plugin.plugin_version}，耗时：{elapsed_time:.2f} 秒")\n                sync_plugins.append(plugin.id)\n            else:\n                logger.error(\n                    f"插件 {plugin.plugin_name} v{plugin.plugin_version} 安装失败：{msg}，耗时：{elapsed_time:.2f} 秒")\n                failed_plugins.append(plugin.id)\n\n        if SystemUtils.is_frozen():\n            return []\n\n        # 获取已安装插件列表\n        install_plugins = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        # 获取远程和本地仓库来源插件列表\n        online_plugins = self.get_online_plugins()\n        local_repo_plugins = self.get_local_repo_plugins()\n        candidate_plugins = self.process_plugins_list(online_plugins + local_repo_plugins, []) \\\n            if online_plugins or local_repo_plugins else []\n        # 确定需要安装的插件\n        plugins_to_install = [\n            plugin for plugin in candidate_plugins\n            if plugin.id in install_plugins\n            and plugin.system_version_compatible is not False\n            and not self.is_plugin_exists(plugin.id, plugin.plugin_version)\n        ]\n\n        if not plugins_to_install:\n            return []\n        logger.info("开始安装第三方插件...")\n        sync_plugins = []\n        failed_plugins = []\n\n        # 使用 ThreadPoolExecutor 进行并发安装\n        total_start_time = time.time()\n        with ThreadPoolExecutor(max_workers=5) as executor:\n            futures = {\n                executor.submit(install_plugin, plugin): plugin\n                for plugin in plugins_to_install\n            }\n            for future in as_completed(futures):\n                plugin = futures[future]\n                try:\n                    future.result()\n                except Exception as exc:\n                    logger.error(f"插件 {plugin.plugin_name} 安装过程中出现异常: {exc}")\n\n        total_elapsed_time = time.time() - total_start_time\n        logger.info(\n            f"第三方插件安装完成，成功：{len(sync_plugins)} 个，"\n            f"失败：{len(failed_plugins)} 个，总耗时：{total_elapsed_time:.2f} 秒"\n        )\n        return sync_plugins\n\n    @staticmethod\n    def install_plugin_missing_dependencies() -> List[str]:\n        """\n        安装插件中缺失或不兼容的依赖项\n        """\n        pluginhelper = PluginHelper()\n        # 第一步：获取需要安装的依赖项列表\n        missing_dependencies = pluginhelper.find_missing_dependencies()\n        if not missing_dependencies:\n            return missing_dependencies\n        logger.debug(f"检测到缺失的依赖项: {missing_dependencies}")\n        logger.info(f"开始安装缺失的依赖项，共 {len(missing_dependencies)} 个...")\n        # 第二步：安装依赖项并返回结果\n        total_start_time = time.time()\n        success, message = pluginhelper.install_dependencies(missing_dependencies)\n        total_elapsed_time = time.time() - total_start_time\n        if success:\n            logger.info(f"已完成 {len(missing_dependencies)} 个依赖项安装，总耗时：{total_elapsed_time:.2f} 秒")\n        else:\n            logger.warning(f"存在缺失依赖项安装失败，请尝试手动安装，总耗时：{total_elapsed_time:.2f} 秒")\n        return missing_dependencies\n\n    def get_plugin_config(self, pid: str) -> dict:\n        """\n        获取插件配置\n        :param pid: 插件ID\n        """\n        if not self._plugins.get(pid):\n            return {}\n        conf = SystemConfigOper().get(self._config_key % pid)\n        if conf:\n            # 去掉空Key\n            return {k: v for k, v in conf.items() if k}\n        return {}\n\n    def save_plugin_config(self, pid: str, conf: dict, force: bool = False) -> bool:\n        """\n        保存插件配置\n        :param pid: 插件ID\n        :param conf: 配置\n        :param force: 强制保存\n        """\n        if not force and not self._plugins.get(pid):\n            return False\n        SystemConfigOper().set(self._config_key % pid, conf)\n        return True\n\n    async def async_save_plugin_config(\n        self, pid: str, conf: dict, force: bool = False\n    ) -> bool:\n        """\n        异步保存插件配置。\n        :param pid: 插件ID\n        :param conf: 配置\n        :param force: 强制保存\n        """\n        if not force and not self._plugins.get(pid):\n            return False\n        await SystemConfigOper().async_set(self._config_key % pid, conf)\n        return True\n\n    def delete_plugin_config(self, pid: str, force: bool = False) -> bool:\n        """\n        删除插件配置\n        :param pid: 插件ID\n        :param force: 插件停止后仍允许按插件 ID 删除持久化配置\n        """\n        if not force and not self._plugins.get(pid):\n            return False\n        return SystemConfigOper().delete(self._config_key % pid)\n\n    def delete_plugin_data(self, pid: str, force: bool = False) -> bool:\n        """\n        删除插件数据\n        :param pid: 插件ID\n        :param force: 插件停止后仍允许按插件 ID 删除持久化数据\n        """\n        if not force and not self._plugins.get(pid):\n            return False\n        PluginDataOper().del_data(pid)\n        return True\n\n    def get_plugin_state(self, pid: str) -> bool:\n        """\n        获取插件状态\n        :param pid: 插件ID\n        """\n        plugin = self._running_plugins.get(pid)\n        return plugin.get_state() if plugin else False\n\n    def get_plugin_commands(self, pid: Optional[str] = None) -> List[Dict[str, Any]]:\n        """\n        获取插件命令\n        [{\n            "cmd": "/xx",\n            "event": EventType.xx,\n            "desc": "xxxx",\n            "data": {},\n            "pid": "",\n        }]\n        """\n        ret_commands = []\n        # 创建字典快照避免并发修改\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if pid and pid != plugin_id:\n                continue\n            if hasattr(plugin, "get_command") and ObjectUtils.check_method(plugin.get_command):\n                try:\n                    if not plugin.get_state():\n                        continue\n                    commands = plugin.get_command() or []\n                    for command in commands:\n                        command["pid"] = plugin_id\n                    ret_commands.extend(commands)\n                except Exception as e:\n                    logger.error(f"获取插件命令出错：{str(e)}")\n        return ret_commands\n\n    def get_plugin_apis(self, pid: Optional[str] = None) -> List[Dict[str, Any]]:\n        """\n        获取插件API\n        [{\n            "path": "/xx",\n            "endpoint": self.xxx,\n            "methods": ["GET", "POST"],\n            "summary": "API名称",\n            "description": "API说明",\n            "allow_anonymous": false\n        }]\n        """\n        ret_apis = []\n        if pid:\n            plugins = {pid: self._running_plugins.get(pid)}\n        else:\n            plugins = self._running_plugins\n        for plugin_id, plugin in plugins.items():\n            if pid and pid != plugin_id:\n                continue\n            if hasattr(plugin, "get_api") and ObjectUtils.check_method(plugin.get_api):\n                try:\n                    apis = plugin.get_api() or []\n                    for api in apis:\n                        api["path"] = f"/{plugin_id}{api[\'path\']}"\n                        if not api.get("auth"):\n                            api["auth"] = "apikey"\n                    ret_apis.extend(apis)\n                except Exception as e:\n                    logger.error(f"获取插件 {plugin_id} API出错：{str(e)}")\n        return ret_apis\n\n    def get_plugin_services(self, pid: Optional[str] = None) -> List[Dict[str, Any]]:\n        """\n        获取插件服务\n        [{\n            "id": "服务ID",\n            "name": "服务名称",\n            "trigger": "触发器：cron、interval、date、CronTrigger.from_crontab()",\n            "func": self.xxx,\n            "kwargs": {} # 定时器参数,\n            "func_kwargs": {} # 方法参数\n        }]\n        """\n        ret_services = []\n        # 创建字典快照避免并发修改\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if pid and pid != plugin_id:\n                continue\n            if hasattr(plugin, "get_service") and ObjectUtils.check_method(plugin.get_service):\n                try:\n                    if not plugin.get_state():\n                        continue\n                    services = plugin.get_service() or []\n                    ret_services.extend(services)\n                except Exception as e:\n                    logger.error(f"获取插件 {plugin_id} 服务出错：{str(e)}")\n        return ret_services\n\n    def get_plugin_modules(self, pid: Optional[str] = None) -> Dict[tuple, Dict[str, Any]]:\n        """\n        获取插件模块\n        {\n            plugin_id: {\n                method: function\n            }\n        }\n        """\n        ret_modules = {}\n        # 创建字典快照避免并发修改\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if pid and pid != plugin_id:\n                continue\n            if hasattr(plugin, "get_module") and ObjectUtils.check_method(plugin.get_module):\n                try:\n                    if not plugin.get_state():\n                        continue\n                    plugin_module = plugin.get_module() or []\n                    ret_modules[(plugin_id, plugin.get_name())] = plugin_module\n                except Exception as e:\n                    logger.error(f"获取插件 {plugin_id} 模块出错：{str(e)}")\n        return ret_modules\n\n    def get_plugin_actions(self, pid: Optional[str] = None) -> List[Dict[str, Any]]:\n        """\n        获取插件动作\n        [{\n            "id": "动作ID",\n            "name": "动作名称",\n            "func": self.xxx,\n            "kwargs": {} # 需要附加传递的参数\n        }]\n        """\n        ret_actions = []\n        # 创建字典快照避免并发修改\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if pid and pid != plugin_id:\n                continue\n            if hasattr(plugin, "get_actions") and ObjectUtils.check_method(plugin.get_actions):\n                try:\n                    if not plugin.get_state():\n                        continue\n                    actions = plugin.get_actions()\n                    if actions:\n                        ret_actions.append({\n                            "plugin_id": plugin_id,\n                            "plugin_name": plugin.plugin_name,\n                            "actions": actions\n                        })\n                except Exception as e:\n                    logger.error(f"获取插件 {plugin_id} 动作出错：{str(e)}")\n        return ret_actions\n\n    @staticmethod\n    def _copy_plugin_agent_tools(\n        tools_info: List[Dict[str, Any]]\n    ) -> List[Dict[str, Any]]:\n        """\n        复制插件智能体工具注册信息，避免调用方修改缓存内容。\n        """\n        return [\n            {\n                **plugin_info,\n                "tools": list(plugin_info.get("tools", [])),\n            }\n            for plugin_info in tools_info\n        ]\n\n    def get_plugin_agent_tools(self, pid: Optional[str] = None) -> List[Dict[str, Any]]:\n        """\n        获取插件智能体工具\n        [{\n            "plugin_id": "插件ID",\n            "plugin_name": "插件名称",\n            "tools": [ToolClass1, ToolClass2, ...]\n        }]\n        """\n        cache_key = pid or "__all__"\n        while True:\n            with self._plugin_agent_tools_cache_lock:\n                cache_revision = self._plugin_agent_tools_revision\n                cached_tools = self._plugin_agent_tools_cache.get(cache_key)\n            if cached_tools is not None:\n                return self._copy_plugin_agent_tools(cached_tools)\n\n            ret_tools = []\n            # 创建字典快照避免并发修改\n            running_plugins_snapshot = dict(self._running_plugins)\n            for plugin_id, plugin in running_plugins_snapshot.items():\n                if pid and pid != plugin_id:\n                    continue\n                if hasattr(plugin, "get_agent_tools") and ObjectUtils.check_method(\n                    plugin.get_agent_tools\n                ):\n                    try:\n                        if not plugin.get_state():\n                            continue\n                        tools = plugin.get_agent_tools()\n                        if tools:\n                            ret_tools.append({\n                                "plugin_id": plugin_id,\n                                "plugin_name": plugin.plugin_name,\n                                "tools": tools\n                            })\n                    except Exception as e:\n                        logger.error(f"获取插件 {plugin_id} 智能体工具出错：{str(e)}")\n            with self._plugin_agent_tools_cache_lock:\n                if cache_revision != self._plugin_agent_tools_revision:\n                    # 插件状态在注册表构建期间发生变化，重新读取以避免写回过期快照。\n                    continue\n                self._plugin_agent_tools_cache[cache_key] = self._copy_plugin_agent_tools(\n                    ret_tools\n                )\n                return ret_tools\n\n    @staticmethod\n    def get_plugin_remote_entry(plugin_id: str, dist_path: str) -> str:\n        """\n        获取插件的远程入口地址\n        :param plugin_id: 插件 ID\n        :param dist_path: 插件的分发路径\n        :return: 远程入口地址\n        """\n        dist_path = dist_path.strip("/")\n        path = posixpath.join(\n            "plugin",\n            "file",\n            plugin_id.lower(),\n            dist_path,\n            "remoteEntry.js",\n        )\n        if not path.startswith("/"):\n            path = "/" + path\n        return path\n\n    def get_plugin_remotes(self, pid: Optional[str] = None) -> List[Dict[str, Any]]:\n        """\n        获取插件联邦组件列表\n        """\n        remotes = []\n        # 创建字典快照避免并发修改\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if pid and pid != plugin_id:\n                continue\n            if hasattr(plugin, "get_render_mode"):\n                render_mode, dist_path = plugin.get_render_mode()\n                if render_mode != "vue":\n                    continue\n                remotes.append({\n                    "id": plugin_id,\n                    "url": self.get_plugin_remote_entry(plugin_id, dist_path),\n                    "name": plugin.plugin_name,\n                })\n        return remotes\n\n    def get_plugin_auth_providers(self) -> List[Dict[str, Any]]:\n        """\n        聚合插件声明的登录认证提供方。\n\n        :return: 插件认证入口列表\n        """\n        providers: List[Dict[str, Any]] = []\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if not plugin.get_state():\n                continue\n            if not hasattr(plugin, "get_auth_providers") or not ObjectUtils.check_method(plugin.get_auth_providers):\n                continue\n            try:\n                plugin_providers = plugin.get_auth_providers() or []\n            except Exception as e:\n                logger.error(f"获取插件 {plugin_id} 登录认证提供方出错：{str(e)}")\n                continue\n            render_mode = None\n            dist_path = None\n            if hasattr(plugin, "get_render_mode"):\n                render_mode, dist_path = plugin.get_render_mode()\n            for raw_provider in plugin_providers:\n                if not raw_provider or not isinstance(raw_provider, dict):\n                    continue\n                provider = raw_provider.copy()\n                provider["type"] = "plugin"\n                provider["plugin_id"] = plugin_id\n                provider.setdefault("id", f"plugin:{plugin_id}")\n                provider.setdefault("name", plugin.plugin_name)\n                provider.setdefault("enabled", True)\n                if render_mode == "vue" and dist_path:\n                    provider.setdefault("component", "AuthPage")\n                    provider["remote"] = {\n                        "id": plugin_id,\n                        "url": self.get_plugin_remote_entry(plugin_id, dist_path),\n                        "name": plugin.plugin_name,\n                    }\n                providers.append(provider)\n        return providers\n\n    def get_plugin_sidebar_nav(self) -> List[Dict[str, Any]]:\n        """\n        聚合所有已启用 Vue 插件的侧栏导航项（get_sidebar_nav）。\n        """\n        valid_sections = {"start", "discovery", "subscribe", "organize", "system"}\n        valid_permissions = {"subscribe", "discovery", "search", "manage", "admin"}\n        items: List[Dict[str, Any]] = []\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if not plugin.get_state():\n                continue\n            if not hasattr(plugin, "get_sidebar_nav") or not ObjectUtils.check_method(plugin.get_sidebar_nav):\n                continue\n            if not hasattr(plugin, "get_render_mode"):\n                continue\n            render_mode, _ = plugin.get_render_mode()\n            if render_mode != "vue":\n                continue\n            try:\n                nav_list = plugin.get_sidebar_nav()\n                if not nav_list:\n                    continue\n                for raw in nav_list:\n                    if not raw or not isinstance(raw, dict):\n                        continue\n                    nav_key = str(raw.get("nav_key") or raw.get("key") or "main").strip()\n                    if not nav_key or any(c in nav_key for c in ["/", "?", "#", " "]):\n                        logger.warning(f"插件[{plugin_id}]侧栏项 nav_key 无效，已跳过: {nav_key!r}")\n                        continue\n                    title = raw.get("title") or plugin.plugin_name\n                    icon = raw.get("icon") or "mdi-puzzle"\n                    section = str(raw.get("section") or "system").lower()\n                    if section not in valid_sections:\n                        section = "system"\n                    perm = raw.get("permission")\n                    if perm is not None and str(perm) not in valid_permissions:\n                        perm = None\n                    else:\n                        perm = str(perm) if perm is not None else None\n                    order = raw.get("order", 0)\n                    try:\n                        order = int(order)\n                    except (TypeError, ValueError):\n                        order = 0\n                    items.append({\n                        "plugin_id": plugin_id,\n                        "nav_key": nav_key,\n                        "title": title,\n                        "icon": icon,\n                        "section": section,\n                        "permission": perm,\n                        "order": order,\n                    })\n            except Exception as e:\n                logger.error(f"获取插件[{plugin_id}]侧栏导航出错：{str(e)}")\n        items.sort(key=lambda x: (x["section"], x["order"], x["plugin_id"], x["nav_key"]))\n        return items\n\n    def get_plugin_dashboard_meta(self) -> List[Dict[str, str]]:\n        """\n        获取所有插件仪表盘元信息\n        """\n        dashboard_meta = []\n        # 创建字典快照避免并发修改\n        running_plugins_snapshot = dict(self._running_plugins)\n        for plugin_id, plugin in running_plugins_snapshot.items():\n            if not hasattr(plugin, "get_dashboard") or not ObjectUtils.check_method(plugin.get_dashboard):\n                continue\n            try:\n                if not plugin.get_state():\n                    continue\n                # 如果是多仪表盘实现\n                if hasattr(plugin, "get_dashboard_meta") and ObjectUtils.check_method(plugin.get_dashboard_meta):\n                    meta = plugin.get_dashboard_meta()\n                    if meta:\n                        dashboard_meta.extend([{\n                            "id": plugin_id,\n                            "name": m.get("name"),\n                            "key": m.get("key"),\n                        } for m in meta if m])\n                else:\n                    dashboard_meta.append({\n                        "id": plugin_id,\n                        "name": plugin.plugin_name,\n                        "key": "",\n                    })\n            except Exception as e:\n                logger.error(f"获取插件[{plugin_id}]仪表盘元数据出错：{str(e)}")\n        return dashboard_meta\n\n    def get_plugin_dashboard(self, pid: str, key: str, user_agent: str = None) -> Optional[schemas.PluginDashboard]:\n        """\n        获取插件仪表盘\n        """\n\n        def __get_params_count(func: Callable):\n            """\n            获取函数的参数信息\n            """\n            signature = inspect.signature(func)\n            return len(signature.parameters)\n\n        # 获取插件实例\n        plugin_instance = self.running_plugins.get(pid)\n        if not plugin_instance:\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f"插件 {pid} 不存在或未加载")\n\n        # 渲染模式\n        render_mode, _ = plugin_instance.get_render_mode()\n        # 获取插件仪表板\n        try:\n            # 检查方法的参数个数\n            params_count = __get_params_count(plugin_instance.get_dashboard)\n            if params_count > 1:\n                dashboard: Tuple = plugin_instance.get_dashboard(key=key, user_agent=user_agent)\n            elif params_count > 0:\n                dashboard: Tuple = plugin_instance.get_dashboard(user_agent=user_agent)\n            else:\n                dashboard: Tuple = plugin_instance.get_dashboard()\n        except Exception as e:\n            logger.error(f"插件 {pid} 调用方法 get_dashboard 出错: {str(e)}")\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\n                                detail=f"插件 {pid} 调用方法 get_dashboard 出错: {str(e)}")\n        if dashboard is None:\n            return None\n        if not isinstance(dashboard, (tuple, list)) or len(dashboard) != 3:\n            logger.error(f"插件 {pid} 返回的仪表盘数据格式错误")\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\n                                detail=f"插件 {pid} 返回的仪表盘数据格式错误")\n        cols, attrs, elements = dashboard\n        return schemas.PluginDashboard(\n            id=pid,\n            name=plugin_instance.plugin_name,\n            key=key,\n            render_mode=render_mode,\n            cols=cols or {},\n            attrs=attrs or {},\n            elements=elements\n        )\n\n    def get_plugin_attr(self, pid: str, attr: str) -> Any:\n        """\n        获取插件属性\n        :param pid: 插件ID\n        :param attr: 属性名\n        """\n        plugin = self._running_plugins.get(pid)\n        if not plugin:\n            return None\n        if not hasattr(plugin, attr):\n            return None\n        return getattr(plugin, attr)\n\n    def run_plugin_method(self, pid: str, method: str, *args, **kwargs) -> Any:\n        """\n        运行插件方法\n        :param pid: 插件ID\n        :param method: 方法名\n        :param args: 参数\n        :param kwargs: 关键字参数\n        """\n        plugin = self._running_plugins.get(pid)\n        if not plugin:\n            return None\n        if not hasattr(plugin, method):\n            return None\n        return getattr(plugin, method)(*args, **kwargs)\n\n    async def async_run_plugin_method(self, pid: str, method: str, *args, **kwargs) -> Any:\n        """\n        异步运行插件方法\n        :param pid: 插件ID\n        :param method: 方法名\n        :param args: 参数\n        :param kwargs: 关键字参数\n        """\n        plugin = self._running_plugins.get(pid)\n        if not plugin:\n            return None\n        if not hasattr(plugin, method):\n            return None\n        method_func = getattr(plugin, method)\n        if asyncio.iscoroutinefunction(method_func):\n            return await method_func(*args, **kwargs)\n        else:\n            return method_func(*args, **kwargs)\n\n    def get_plugin_ids(self) -> List[str]:\n        """\n        获取所有插件ID\n        """\n        return list(self._plugins.keys())\n\n    def get_running_plugin_ids(self) -> List[str]:\n        """\n        获取所有运行态插件ID\n        """\n        return list(self._running_plugins.keys())\n\n    def get_online_plugins(self, force: bool = False) -> List[schemas.Plugin]:\n        """\n        获取所有在线插件信息\n        """\n        if not settings.PLUGIN_MARKET:\n            return []\n\n        # 用于存储高于 v1 版本的插件（如 v2, v3 等）\n        higher_version_plugins = []\n        # 用于存储 v1 版本插件\n        base_version_plugins = []\n\n        # 使用多线程获取线上插件\n        with concurrent.futures.ThreadPoolExecutor() as executor:\n            futures_to_version = {}\n            for m in settings.PLUGIN_MARKET.split(","):\n                if not m:\n                    continue\n                # 提交任务获取 v1 版本插件，存储 future 到 version 的映射\n                base_future = executor.submit(self.get_plugins_from_market, m, None, force)\n                futures_to_version[base_future] = "base_version"\n\n                # 提交任务获取高版本插件（如 v2、v3），存储 future 到 version 的映射\n                if settings.VERSION_FLAG:\n                    higher_version_future = executor.submit(self.get_plugins_from_market, m,\n                                                            settings.VERSION_FLAG, force)\n                    futures_to_version[higher_version_future] = "higher_version"\n\n            # 按照完成顺序处理结果\n            for future in concurrent.futures.as_completed(futures_to_version):\n                plugins = future.result()\n                version = futures_to_version[future]\n\n                if plugins:\n                    if version == "higher_version":\n                        higher_version_plugins.extend(plugins)  # 收集高版本插件\n                    else:\n                        base_version_plugins.extend(plugins)  # 收集 v1 版本插件\n\n        result = self.process_plugins_list(higher_version_plugins, base_version_plugins)\n        logger.info(f"获取到 {len(result)} 个线上插件")\n        return result\n\n    def get_local_plugins(self) -> List[schemas.Plugin]:\n        """\n        获取所有本地已下载的插件信息\n        """\n        # 返回值\n        plugins = []\n        # 已安装插件\n        installed_apps = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        for pid, plugin_class in self._plugins.items():\n            # 运行状插件\n            plugin_obj = self._running_plugins.get(pid)\n            # 基本属性\n            plugin = schemas.Plugin()\n            # ID\n            plugin.id = pid\n            # 安装状态\n            if pid in installed_apps:\n                plugin.installed = True\n            else:\n                plugin.installed = False\n            # 运行状态\n            if plugin_obj and hasattr(plugin_obj, "get_state"):\n                try:\n                    state = plugin_obj.get_state()\n                except Exception as e:\n                    logger.error(f"获取插件 {pid} 状态出错：{str(e)}")\n                    state = False\n                plugin.state = state\n            else:\n                plugin.state = False\n            # 是否有详情页面\n            if hasattr(plugin_class, "get_page"):\n                if ObjectUtils.check_method(plugin_class.get_page):\n                    plugin.has_page = True\n                else:\n                    plugin.has_page = False\n            # 公钥\n            if hasattr(plugin_class, "plugin_public_key"):\n                plugin.plugin_public_key = plugin_class.plugin_public_key\n            # 权限\n            if not self.__set_and_check_auth_level(plugin=plugin, source=plugin_class):\n                continue\n            # 名称\n            if hasattr(plugin_class, "plugin_name"):\n                plugin.plugin_name = plugin_class.plugin_name\n            # 描述\n            if hasattr(plugin_class, "plugin_desc"):\n                plugin.plugin_desc = plugin_class.plugin_desc\n            # 版本\n            if hasattr(plugin_class, "plugin_version"):\n                plugin.plugin_version = plugin_class.plugin_version\n            # 图标\n            if hasattr(plugin_class, "plugin_icon"):\n                plugin.plugin_icon = plugin_class.plugin_icon\n            # 作者\n            if hasattr(plugin_class, "plugin_author"):\n                plugin.plugin_author = plugin_class.plugin_author\n            # 作者链接\n            if hasattr(plugin_class, "author_url"):\n                plugin.author_url = plugin_class.author_url\n            # 加载顺序\n            if hasattr(plugin_class, "plugin_order"):\n                plugin.plugin_order = plugin_class.plugin_order\n            # 是否需要更新\n            plugin.has_update = False\n            # 本地标志\n            plugin.is_local = True\n            # 汇总\n            plugins.append(plugin)\n        # 根据加载排序重新排序\n        plugins.sort(key=lambda x: x.plugin_order if hasattr(x, "plugin_order") else 0)\n        return plugins\n\n    def get_local_plugin_version(self, pid: str) -> Optional[str]:\n        """\n        获取指定已安装插件的本地版本，不触发全部插件的状态、页面和权限计算。\n\n        插件类由运行期动态加载，旧插件可能未声明版本属性，因此缺失时返回 None。\n        """\n        installed_apps = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        if pid not in installed_apps:\n            return None\n        plugin_class = self._plugins.get(pid)\n        if not plugin_class:\n            return None\n        return getattr(plugin_class, "plugin_version", None)\n\n    def get_local_repo_plugins(self) -> List[schemas.Plugin]:\n        """\n        获取本地插件仓库目录中的插件信息\n        """\n        plugins = []\n        installed_apps = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        local_candidates = PluginHelper().get_local_plugin_candidates()\n        if not local_candidates:\n            return []\n        for pid, plugin_info in local_candidates.items():\n            package_version = plugin_info.get("package_version")\n            plugin = self._process_plugin_info(\n                pid=pid,\n                plugin_info=plugin_info,\n                market=PluginHelper.make_local_repo_url(\n                    pid,\n                    plugin_info.get("repo_path"),\n                    package_version\n                ),\n                installed_apps=installed_apps,\n                add_time=0,\n                package_version=package_version\n            )\n            if not plugin:\n                continue\n            plugin.is_local = True\n            plugins.append(plugin)\n\n        plugins.sort(key=lambda x: x.plugin_order if hasattr(x, "plugin_order") else 0)\n        logger.info(f"获取到 {len(plugins)} 个本地插件")\n        return plugins\n\n    @staticmethod\n    def is_plugin_exists(pid: str, version: str = None) -> bool:\n        """\n        判断插件是否存在，并满足版本要求(有传入version时)\n        :param pid: 插件ID\n        :param version: 插件版本\n        """\n        if not pid:\n            return False\n        try:\n            # 构建包名\n            package_name = f"app.plugins.{pid.lower()}"\n            # 检查包是否存在\n            spec = importlib.util.find_spec(package_name)\n            package_exists = spec is not None and spec.origin is not None\n            logger.debug(f"{pid} exists: {package_exists}")\n            if not package_exists:\n                return False\n\n            local_version = PluginManager().get_plugin_attr(pid=pid, attr="plugin_version")\n            if not local_version:\n                return False\n\n            if version and not StringUtils.compare_version(local_version, ">=", version):\n                logger.warn(f"Plugin {pid} version: {local_version} (older than version: {version})")\n                return False\n\n            return True\n        except Exception as e:\n            logger.debug(f"获取插件是否在本地包中存在失败，{e}")\n            return False\n\n    def get_plugins_from_market(self, market: str,\n                                package_version: Optional[str] = None,\n                                force: bool = False) -> Optional[List[schemas.Plugin]]:\n        """\n        从指定的市场获取插件信息\n        :param market: 市场的 URL 或标识\n        :param package_version: 首选插件版本 (如 "v2", "v3")，如果不指定则获取 v1 版本\n        :param force: 是否强制刷新（忽略缓存）\n        :return: 返回插件的列表，若获取失败返回 []\n        """\n        if not market:\n            return []\n        # 已安装插件\n        installed_apps = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        # 获取在线插件\n        with fresh(force):\n            online_plugins = PluginHelper().get_plugins(market, package_version)\n        if online_plugins is None:\n            logger.warning(\n                f"获取{package_version if package_version else \'\'}插件库失败：{market}，请检查 GitHub 网络连接")\n            return []\n        ret_plugins = []\n        add_time = len(online_plugins)\n        for pid, plugin_info in online_plugins.items():\n            plugin = self._process_plugin_info(pid, plugin_info, market, installed_apps, add_time, package_version)\n            if plugin:\n                ret_plugins.append(plugin)\n            add_time -= 1\n\n        return ret_plugins\n\n    @staticmethod\n    def process_plugins_list(higher_version_plugins: List[schemas.Plugin],\n                             base_version_plugins: List[schemas.Plugin]) -> List[schemas.Plugin]:\n        """\n        处理插件列表：合并、去重、排序、保留最高版本\n        :param higher_version_plugins: 高版本插件列表\n        :param base_version_plugins: 基础版本插件列表\n        :return: 处理后的插件列表\n        """\n        # 优先处理高版本插件\n        all_plugins = []\n        all_plugins.extend(higher_version_plugins)\n        # 将未出现在高版本插件列表中的 v1 插件加入 all_plugins\n        higher_plugin_ids = {f"{p.id}{p.plugin_version}" for p in higher_version_plugins}\n        all_plugins.extend([p for p in base_version_plugins if f"{p.id}{p.plugin_version}" not in higher_plugin_ids])\n        markets = [item for item in settings.PLUGIN_MARKET.split(",") if item]\n\n        def repo_order(plugin: schemas.Plugin) -> int:\n            if PluginHelper.is_local_repo_url(plugin.repo_url):\n                return len(markets) + 1\n            if plugin.repo_url in markets:\n                return markets.index(plugin.repo_url)\n            return len(markets)\n\n        # 去重：同 ID + 版本优先保留市场来源，其次按来源顺序稳定保留。\n        dedup_plugins = {}\n        for plugin in sorted(all_plugins, key=repo_order):\n            key = f"{plugin.id}{plugin.plugin_version}"\n            exists = dedup_plugins.get(key)\n            if not exists:\n                dedup_plugins[key] = plugin\n                continue\n            if PluginHelper.is_local_repo_url(exists.repo_url) and not PluginHelper.is_local_repo_url(plugin.repo_url):\n                dedup_plugins[key] = plugin\n\n        # 相同 ID 的插件保留版本号最大的版本；同版本市场来源优先。\n        result_by_id = {}\n        for plugin in sorted(dedup_plugins.values(), key=repo_order):\n            exists = result_by_id.get(plugin.id)\n            if not exists:\n                result_by_id[plugin.id] = plugin\n                continue\n            if StringUtils.compare_version(plugin.plugin_version, ">", exists.plugin_version):\n                result_by_id[plugin.id] = plugin\n            elif plugin.plugin_version == exists.plugin_version \\\n                    and PluginHelper.is_local_repo_url(exists.repo_url) \\\n                    and not PluginHelper.is_local_repo_url(plugin.repo_url):\n                result_by_id[plugin.id] = plugin\n\n        return list(result_by_id.values())\n\n    def _process_plugin_info(self, pid: str, plugin_info: dict, market: str,\n                             installed_apps: List[str], add_time: int,\n                             package_version: Optional[str] = None) -> Optional[schemas.Plugin]:\n        """\n        处理单个插件信息，创建 schemas.Plugin 对象\n        :param pid: 插件ID\n        :param plugin_info: 插件信息字典\n        :param market: 市场URL\n        :param installed_apps: 已安装插件列表\n        :param add_time: 添加顺序\n        :param package_version: 包版本\n        :return: 创建的插件对象，如果验证失败返回None\n        """\n        if not isinstance(plugin_info, dict):\n            return None\n\n        plugin_info = PluginHelper.annotate_plugin_system_version(plugin_info.copy())\n        # 如 package_version 为空，则需要判断插件是否兼容当前版本\n        if not package_version:\n            if plugin_info.get(settings.VERSION_FLAG) is not True:\n                # 插件当前版本不兼容\n                return None\n\n        # 运行状插件\n        plugin_obj = self._running_plugins.get(pid)\n        # 非运行态插件\n        plugin_static = self._plugins.get(pid)\n        # 基本属性\n        plugin = schemas.Plugin()\n        # ID\n        plugin.id = pid\n        # 安装状态\n        if pid in installed_apps and plugin_static:\n            plugin.installed = True\n        else:\n            plugin.installed = False\n        # 是否有新版本\n        plugin.has_update = False\n        if plugin_static:\n            installed_version = getattr(plugin_static, "plugin_version")\n            if StringUtils.compare_version(installed_version, "<", plugin_info.get("version")):\n                # 需要更新\n                plugin.has_update = True\n        # 主系统版本兼容性\n        if plugin_info.get("system_version"):\n            plugin.system_version = plugin_info.get("system_version")\n        if plugin_info.get("system_version_compatible") is False:\n            plugin.system_version_compatible = False\n            plugin.system_version_message = plugin_info.get("system_version_message")\n        # 运行状态\n        if plugin_obj and hasattr(plugin_obj, "get_state"):\n            try:\n                state = plugin_obj.get_state()\n            except Exception as e:\n                logger.error(f"获取插件 {pid} 状态出错：{str(e)}")\n                state = False\n            plugin.state = state\n        else:\n            plugin.state = False\n        # 是否有详情页面\n        plugin.has_page = False\n        if plugin_obj and hasattr(plugin_obj, "get_page"):\n            if ObjectUtils.check_method(plugin_obj.get_page):\n                plugin.has_page = True\n        # 公钥\n        if plugin_info.get("key"):\n            plugin.plugin_public_key = plugin_info.get("key")\n        # 权限\n        if not self.__set_and_check_auth_level(plugin=plugin, source=plugin_info):\n            return None\n        # 名称\n        if plugin_info.get("name"):\n            plugin.plugin_name = plugin_info.get("name")\n        # 描述\n        if plugin_info.get("description"):\n            plugin.plugin_desc = plugin_info.get("description")\n        # 版本\n        if plugin_info.get("version"):\n            plugin.plugin_version = plugin_info.get("version")\n        # 图标\n        if plugin_info.get("icon"):\n            plugin.plugin_icon = plugin_info.get("icon")\n        # 标签\n        plugin.plugin_label = self._normalize_plugin_label(plugin_info.get("labels"))\n        # 作者\n        if plugin_info.get("author"):\n            plugin.plugin_author = plugin_info.get("author")\n        # 更新历史\n        if plugin_info.get("history"):\n            plugin.history = plugin_info.get("history")\n        # Release 能力位来自插件市场索引，用于前端展示和后端安装入口双重校验。\n        plugin.release = bool(plugin_info.get("release"))\n        # 仓库链接\n        plugin.repo_url = market\n        # 本地标志\n        plugin.is_local = False\n        # 添加顺序\n        plugin.add_time = add_time\n\n        return plugin\n\n    @staticmethod\n    def _normalize_plugin_label(labels: Any) -> Optional[str]:\n        """\n        规整插件市场标签字段，兼容旧字符串和新列表格式。\n\n        :param labels: 插件市场 package 中的 labels 字段\n        :return: 用空格拼接后的标签字符串，无法识别或为空时返回 None\n        """\n        if isinstance(labels, str):\n            label = labels.strip()\n            return label or None\n        if isinstance(labels, list):\n            normalized_labels = [str(item).strip() for item in labels if str(item).strip()]\n            return " ".join(normalized_labels) or None\n        return None\n\n    async def async_get_online_plugins(\n            self,\n            force: bool = False,\n            progress_callback: Optional[Callable[..., None]] = None,\n    ) -> List[schemas.Plugin]:\n        """\n        异步获取所有在线插件信息\n        :param force: 是否强制刷新（忽略缓存）\n        :param progress_callback: 定时服务进度更新回调\n        """\n        if not settings.PLUGIN_MARKET:\n            if progress_callback:\n                progress_callback(value=100, text="未配置插件市场，跳过刷新")\n            return []\n\n        async def fetch_market(\n                market: str,\n                package_version: Optional[str],\n                result_version: str,\n                task_index: int,\n        ) -> Tuple[int, str, List[schemas.Plugin]]:\n            """\n            获取单个市场版本的插件列表并保留结果分组。\n            """\n            plugins = await self.async_get_plugins_from_market(\n                market,\n                package_version,\n                force,\n            )\n            return task_index, result_version, plugins or []\n\n        higher_version_plugins = []\n        base_version_plugins = []\n        tasks = []\n\n        for market in settings.PLUGIN_MARKET.split(","):\n            if not market:\n                continue\n            tasks.append(\n                asyncio.create_task(\n                    fetch_market(market, None, "base_version", len(tasks))\n                )\n            )\n            if settings.VERSION_FLAG:\n                tasks.append(\n                    asyncio.create_task(\n                        fetch_market(\n                            market,\n                            settings.VERSION_FLAG,\n                            "higher_version",\n                            len(tasks),\n                        )\n                    )\n                )\n\n        if tasks:\n            total_tasks = len(tasks)\n            finished_tasks = 0\n            task_results = {}\n            if progress_callback:\n                progress_callback(\n                    value=0,\n                    text=f"开始刷新插件市场，共 {total_tasks} 个请求 ...",\n                    data={"total": total_tasks, "finished": 0},\n                )\n            for completed_task in asyncio.as_completed(tasks):\n                try:\n                    task_index, version, plugins = await completed_task\n                    task_results[task_index] = (version, plugins)\n                except Exception as err:\n                    logger.error(f"获取插件市场数据失败：{str(err)}")\n                finished_tasks += 1\n                if progress_callback:\n                    progress_callback(\n                        value=finished_tasks / total_tasks * 100,\n                        text=(\n                            f"插件市场请求"\n                            f"（{finished_tasks}/{total_tasks}）处理完成"\n                        ),\n                        data={"total": total_tasks, "finished": finished_tasks},\n                    )\n            for task_index in sorted(task_results):\n                version, plugins = task_results[task_index]\n                if plugins:\n                    if version == "higher_version":\n                        higher_version_plugins.extend(plugins)\n                    else:\n                        base_version_plugins.extend(plugins)\n\n        result = self.process_plugins_list(higher_version_plugins, base_version_plugins)\n        logger.info(f"获取到 {len(result)} 个线上插件")\n        if progress_callback:\n            progress_callback(value=100, text="插件市场缓存刷新完成")\n        return result\n\n    async def async_get_plugins_from_market(self, market: str,\n                                            package_version: Optional[str] = None,\n                                            force: bool = False) -> Optional[List[schemas.Plugin]]:\n        """\n        异步从指定的市场获取插件信息\n        :param market: 市场的 URL 或标识\n        :param package_version: 首选插件版本 (如 "v2", "v3")，如果不指定则获取 v1 版本\n        :param force: 是否强制刷新（忽略缓存）\n        :return: 返回插件的列表，若获取失败返回 []\n        """\n        if not market:\n            return []\n        # 已安装插件\n        installed_apps = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []\n        # 获取在线插件\n        async with async_fresh(force):\n            online_plugins = await PluginHelper().async_get_plugins(market, package_version)\n        if online_plugins is None:\n            logger.warning(\n                f"获取{package_version if package_version else \'\'}插件库失败：{market}，请检查 GitHub 网络连接")\n            return []\n        ret_plugins = []\n        add_time = len(online_plugins)\n        for pid, plugin_info in online_plugins.items():\n            plugin = self._process_plugin_info(pid, plugin_info, market, installed_apps, add_time, package_version)\n            if plugin:\n                ret_plugins.append(plugin)\n            add_time -= 1\n\n        return ret_plugins\n\n    @staticmethod\n    def __set_and_check_auth_level(plugin: Union[schemas.Plugin, Type[Any]],\n                                   source: Optional[Union[dict, Type[Any]]] = None) -> bool:\n        """\n        设置并检查插件的认证级别\n        :param plugin: 插件对象或包含 auth_level 属性的对象\n        :param source: 可选的字典对象或类对象，可能包含 "level" 或 "auth_level" 键\n        :return: 如果插件的认证级别有效且当前环境的认证级别满足要求，返回 True，否则返回 False\n        """\n        # 检查并赋值 source 中的 level 或 auth_level\n        if source:\n            if isinstance(source, dict) and "level" in source:\n                plugin.auth_level = source.get("level")\n            elif hasattr(source, "auth_level"):\n                plugin.auth_level = source.auth_level\n        # 如果 source 为空且 plugin 本身没有 auth_level，直接返回 True\n        elif not hasattr(plugin, "auth_level"):\n            return True\n\n        # auth_level 级别说明\n        # 1 - 所有用户可见\n        # 2 - 站点认证用户可见\n        # 3 - 站点&密钥认证可见\n        # 99 - 站点&特殊密钥认证可见\n        # 如果当前站点认证级别大于 1 且插件级别为 99，并存在插件公钥，说明为特殊密钥认证，通过密钥匹配进行认证\n        siteshelper = SitesHelper()\n        if siteshelper.auth_level > 1 and plugin.auth_level == 99 and hasattr(plugin, "plugin_public_key"):\n            plugin_id = plugin.id if isinstance(plugin, schemas.Plugin) else plugin.__name__\n            public_key = plugin.plugin_public_key\n            if public_key:\n                private_key = PluginManager.__get_plugin_private_key(plugin_id)\n                verify = RSAUtils.verify_rsa_keys(public_key=public_key, private_key=private_key)\n                return verify\n        # 如果当前站点认证级别小于插件级别，则返回 False\n        if siteshelper.auth_level < plugin.auth_level:\n            return False\n        return True\n\n    @staticmethod\n    def __get_plugin_private_key(plugin_id: str) -> Optional[str]:\n        """\n        根据插件标识获取对应的私钥\n        :param plugin_id: 插件标识\n        :return: 对应的插件私钥，如果未找到则返回 None\n        """\n        try:\n            # 将插件标识转换为大写并构建环境变量名称\n            env_var_name = f"PLUGIN_{plugin_id.upper()}_PRIVATE_KEY"\n            private_key = os.environ.get(env_var_name)\n            return private_key\n        except Exception as e:\n            logger.debug(f"获取插件 {plugin_id} 的私钥时发生错误：{e}")\n            return None\n\n    def clone_plugin(self, plugin_id: str, suffix: str, name: str, description: str,\n                     version: str = None, icon: str = None) -> Tuple[bool, str]:\n        """\n        创建插件分身\n        :param plugin_id: 原插件ID\n        :param suffix: 分身后缀\n        :param name: 分身名称\n        :param description: 分身描述\n        :param version: 自定义版本号\n        :param icon: 自定义图标URL\n        :return: (是否成功, 错误信息)\n        """\n        try:\n            # 验证参数\n            if not plugin_id or not suffix:\n                return False, "插件ID和分身后缀不能为空"\n\n            # 检查原插件是否存在\n            if plugin_id not in self._plugins:\n                return False, f"原插件 {plugin_id} 不存在"\n\n            # 生成分身插件ID\n            clone_id = f"{plugin_id}{suffix.lower()}"\n\n            # 检查分身插件是否已存在\n            if self.is_plugin_exists(clone_id):\n                return False, f"分身插件 {clone_id} 已存在"\n\n            # 获取原插件目录\n            original_plugin_dir = Path(settings.ROOT_PATH) / "app" / "plugins" / plugin_id.lower()\n            if not original_plugin_dir.exists():\n                return False, f"原插件目录 {original_plugin_dir} 不存在"\n\n            # 创建分身插件目录\n            clone_plugin_dir = Path(settings.ROOT_PATH) / "app" / "plugins" / clone_id.lower()\n\n            # 复制插件目录\n            import shutil\n            shutil.copytree(original_plugin_dir, clone_plugin_dir)\n            logger.info(f"已复制插件目录：{original_plugin_dir} -> {clone_plugin_dir}")\n\n            # 修改插件文件内容\n            success, msg = self._modify_plugin_files(\n                plugin_dir=clone_plugin_dir,\n                original_id=plugin_id,\n                suffix=suffix.lower(),\n                name=name,\n                description=description,\n                version=version,\n                icon=icon\n            )\n\n            if not success:\n                # 如果修改失败，清理已创建的目录\n                if clone_plugin_dir.exists():\n                    shutil.rmtree(clone_plugin_dir)\n                return False, msg\n\n            # 将分身插件添加到已安装列表\n            systemconfig = SystemConfigOper()\n            installed_plugins = systemconfig.get(SystemConfigKey.UserInstalledPlugins) or []\n            if clone_id not in installed_plugins:\n                installed_plugins.append(clone_id)\n                systemconfig.set(SystemConfigKey.UserInstalledPlugins, installed_plugins)\n\n            # 为分身插件创建初始配置（从原插件复制配置）\n            logger.info(f"正在为分身插件 {clone_id} 创建初始配置...")\n            original_config = self.get_plugin_config(plugin_id)\n            if original_config:\n                # 复制原插件配置作为分身插件的初始配置\n                clone_config = original_config.copy()\n                # 可以在这里修改一些默认值，比如禁用分身插件\n                # 默认禁用分身插件，让用户手动配置\n                clone_config[\'enable\'] = False\n                clone_config[\'enabled\'] = False\n                self.save_plugin_config(clone_id, clone_config, force=True)\n                logger.info(f"已为分身插件 {clone_id} 设置初始配置")\n            else:\n                logger.info(f"原插件 {plugin_id} 没有配置，分身插件 {clone_id} 将使用默认配置")\n\n            # 注册分身插件的API和服务\n            logger.info(f"正在注册分身插件 {clone_id} ...")\n            PluginManager().reload_plugin(clone_id)\n            # 确保分身插件正确初始化配置\n            if clone_id in self._running_plugins:\n                clone_instance = self._running_plugins[clone_id]\n                clone_config = self.get_plugin_config(clone_id)\n                if clone_config:\n                    logger.info(f"正在为分身插件 {clone_id} 重新初始化配置...")\n                    clone_instance.init_plugin(clone_config)\n                    logger.info(f"分身插件 {clone_id} 配置重新初始化完成")\n\n            logger.info(f"插件分身 {clone_id} 创建成功")\n            return True, clone_id\n\n        except Exception as e:\n            logger.error(f"创建插件分身失败：{str(e)}")\n            return False, f"创建插件分身失败：{str(e)}"\n\n    def _modify_plugin_files(self, plugin_dir: Path, original_id: str, suffix: str,\n                             name: str, description: str, version: str = None,\n                             icon: str = None) -> Tuple[bool, str]:\n        """\n        修改插件文件中的类名和相关信息\n        :param plugin_dir: 插件目录\n        :param original_id: 原插件ID\n        :param suffix: 分身后缀\n        :param name: 分身名称\n        :param description: 分身描述\n        :param version: 自定义版本号\n        :param icon: 自定义图标URL\n        :return: (是否成功, 错误信息)\n        """\n        try:\n            # 获取原插件类\n            original_plugin_class = self._plugins.get(original_id)\n            if not original_plugin_class:\n                return False, f"无法获取原插件类 {original_id}"\n\n            # 获取原类名\n            original_class_name = original_plugin_class.__name__\n            clone_class_name = f"{original_class_name}{suffix}"\n\n            # 修改 __init__.py 文件\n            init_file = plugin_dir / "__init__.py"\n            if init_file.exists():\n                success, msg = self._modify_python_file(\n                    file_path=init_file,\n                    original_class_name=original_class_name,\n                    clone_class_name=clone_class_name,\n                    name=name,\n                    description=description,\n                    version=version,\n                    icon=icon\n                )\n                if not success:\n                    return False, msg\n\n            # 检查是否为联邦插件（存在dist目录）\n            dist_dir = plugin_dir / "dist"\n            if dist_dir.exists():\n                success, msg = self._modify_federation_files(\n                    dist_dir=dist_dir,\n                    original_class_name=original_class_name,\n                    clone_class_name=clone_class_name\n                )\n                if not success:\n                    return False, msg\n\n            return True, "文件修改成功"\n\n        except Exception as e:\n            logger.error(f"修改插件文件失败：{str(e)}")\n            return False, f"修改插件文件失败：{str(e)}"\n\n    @staticmethod\n    def _modify_python_file(file_path: Path, original_class_name: str,\n                            clone_class_name: str, name: str, description: str,\n                            version: str = None, icon: str = None) -> Tuple[bool, str]:\n        """\n        修改Python文件中的类名和插件信息\n        """\n        try:\n            with open(file_path, \'r\', encoding=\'utf-8\', errors=\'replace\') as f:\n                content = f.read()\n\n            # 替换类名\n            content = content.replace(f"class {original_class_name}", f"class {clone_class_name}")\n\n            # 替换插件名称和描述\n            import re\n\n            # 替换 plugin_name\n            if name:\n                content = re.sub(\n                    r\'plugin_name\\s*=\\s*["\\\'][^"\\\']*["\\\']\',\n                    f\'plugin_name = "{name}"\',\n                    content\n                )\n\n            # 替换 plugin_desc\n            if description:\n                content = re.sub(\n                    r\'plugin_desc\\s*=\\s*["\\\'][^"\\\']*["\\\']\',\n                    f\'plugin_desc = "{description}"\',\n                    content\n                )\n\n            # 替换 plugin_config_prefix（如果存在）\n            content = re.sub(\n                r\'plugin_config_prefix\\s*=\\s*["\\\'][^"\\\']*["\\\']\',\n                f\'plugin_config_prefix = "{clone_class_name.lower()}_"\',\n                content\n            )\n\n            # 替换 plugin_version（如果提供了自定义版本）\n            if version:\n                content = re.sub(\n                    r\'plugin_version\\s*=\\s*["\\\'][^"\\\']*["\\\']\',\n                    f\'plugin_version = "{version}"\',\n                    content\n                )\n\n            # 替换 plugin_icon（如果提供了自定义图标）\n            if icon and icon.strip():\n                old_content = content\n                content = re.sub(\n                    r\'plugin_icon\\s*=\\s*["\\\'][^"\\\']*["\\\']\',\n                    f\'plugin_icon = "{icon}"\',\n                    content\n                )\n                if old_content != content:\n                    logger.info(f"已替换插件图标为: {icon}")\n                else:\n                    logger.warning(f"插件图标替换失败，未找到匹配的图标设置")\n            else:\n                logger.info("未提供自定义图标，保持原插件图标")\n\n            # 添加分身标志\n            if "def init_plugin(self" in content:\n                init_index = content.index("def init_plugin(self")\n                # 在 def init_plugin(self 前添加 is_clone = True\n                content = content[:init_index] + "is_clone = True\\n\\n    " + content[init_index:]\n\n            with open(file_path, \'w\', encoding=\'utf-8\') as f:\n                f.write(content)\n\n            logger.debug(f"已修改Python文件：{file_path}")\n            return True, "Python文件修改成功"\n\n        except Exception as e:\n            logger.error(f"修改Python文件失败：{str(e)}")\n            return False, f"修改Python文件失败：{str(e)}"\n\n    def _modify_federation_files(self, dist_dir: Path, original_class_name: str,\n                                 clone_class_name: str) -> Tuple[bool, str]:\n        """\n        修改联邦插件的前端文件\n        """\n        try:\n            # 获取原始插件名（从类名推导）\n            original_plugin_name = original_class_name\n            clone_plugin_name = clone_class_name\n\n            # 遍历dist目录下的所有文件\n            for file_path in dist_dir.rglob("*"):\n                if not file_path.is_file():\n                    continue\n\n                # 处理JS文件\n                if file_path.suffix == \'.js\':\n                    try:\n                        with open(file_path, \'r\', encoding=\'utf-8\', errors=\'replace\') as f:\n                            content = f.read()\n\n                        # 替换类名引用（精确匹配）\n                        content = content.replace(original_class_name, clone_class_name)\n                        # 替换插件名引用（如果存在）\n                        content = content.replace(f\'"{original_plugin_name}"\', f\'"{clone_plugin_name}"\')\n                        content = content.replace(f"\'{original_plugin_name}\'", f"\'{clone_plugin_name}\'")\n                        # 替换CSS key中的类名（联邦插件特有）\n                        content = content.replace(f\'css__{original_class_name}__\', f\'css__{clone_class_name}__\')\n                        # 替换可能的小写类名引用\n                        content = content.replace(original_class_name.lower(), clone_class_name.lower())\n\n                        with open(file_path, \'w\', encoding=\'utf-8\') as f:\n                            f.write(content)\n\n                        logger.debug(f"已修改联邦插件JS文件：{file_path}")\n\n                    except Exception as e:\n                        logger.warning(f"修改联邦插件文件 {file_path} 失败：{str(e)}")\n                        continue\n\n                # 处理CSS文件\n                elif file_path.suffix == \'.css\':\n                    try:\n                        with open(file_path, \'r\', encoding=\'utf-8\', errors=\'replace\') as f:\n                            content = f.read()\n\n                        # 替换CSS中可能的类名引用\n                        content = content.replace(original_class_name.lower(),\n                                                  clone_class_name.lower()).replace(original_class_name,\n                                                                                    clone_class_name)\n\n                        with open(file_path, \'w\', encoding=\'utf-8\') as f:\n                            f.write(content)\n\n                        logger.debug(f"已修改联邦插件CSS文件：{file_path}")\n\n                    except Exception as e:\n                        logger.warning(f"修改联邦插件CSS文件 {file_path} 失败：{str(e)}")\n                        continue\n\n            # 重命名构建文件（如果需要）\n            self._rename_federation_assets(dist_dir, original_class_name, clone_class_name)\n\n            return True, "联邦插件文件修改完成"\n\n        except Exception as e:\n            logger.error(f"修改联邦插件文件失败：{str(e)}")\n            return False, f"修改联邦插件文件失败：{str(e)}"\n\n    @staticmethod\n    def _rename_federation_assets(dist_dir: Path, original_class_name: str, clone_class_name: str):\n        """\n        重命名联邦插件的资源文件，避免文件名冲突\n        """\n        try:\n            # 查找包含原类名的文件并重命名\n            for file_path in dist_dir.glob("*"):\n                if not file_path.is_file():\n                    continue\n\n                file_name = file_path.name\n                # 如果文件名包含原类名，则重命名\n                if original_class_name.lower() in file_name.lower():\n                    new_name = file_name.replace(\n                        original_class_name.lower(),\n                        clone_class_name.lower()\n                    )\n                    new_path = file_path.parent / new_name\n\n                    # 避免重命名冲突\n                    if not new_path.exists():\n                        file_path.rename(new_path)\n                        logger.debug(f"重命名联邦插件文件：{file_name} -> {new_name}")\n\n        except Exception as e:\n            # 重命名失败不影响整体流程\n            logger.warning(f"重命名联邦插件资源文件失败：{str(e)}")\n', 'base': 'from abc import ABCMeta, abstractmethod\nfrom pathlib import Path\nfrom typing import Any, List, Dict, Tuple, Optional, Type\n\nfrom app.chain import ChainBase\nfrom app.core.config import settings\nfrom app.core.event import EventManager\nfrom app.db.plugindata_oper import PluginDataOper\nfrom app.db.systemconfig_oper import SystemConfigOper\nfrom app.helper.message import MessageHelper\nfrom app.schemas import Notification, NotificationType, MessageChannel\n\n\nclass PluginChian(ChainBase):\n    """\n    插件处理链\n    """\n    pass\n\n\nclass _PluginBase(metaclass=ABCMeta):\n    """\n    插件模块基类，通过继续该类实现插件功能\n    除内置属性外，还有以下方法可以扩展或调用：\n    - stop_service() 停止插件服务\n    - get_config() 获取配置信息\n    - update_config() 更新配置信息\n    - init_plugin() 生效配置信息\n    - get_data_path() 获取插件数据保存目录\n    """\n    # 插件名称\n    plugin_name: Optional[str] = ""\n    # 插件描述\n    plugin_desc: Optional[str] = ""\n    # 插件顺序\n    plugin_order: Optional[int] = 9999\n    # 是否为插件分身\n    is_clone: bool = False\n\n    def __init__(self):\n        # 插件数据\n        self.plugindata = PluginDataOper()\n        # 处理链\n        self.chain = PluginChian()\n        # 系统配置\n        self.systemconfig = SystemConfigOper()\n        # 系统消息\n        self.systemmessage = MessageHelper()\n        # 事件管理器\n        self.eventmanager = EventManager()\n\n    @abstractmethod\n    def init_plugin(self, config: dict = None):\n        """\n        生效配置信息\n        :param config: 配置信息字典\n        """\n        pass\n\n    def get_name(self) -> str:\n        """\n        获取插件名称\n        :return: 插件名称\n        """\n        return self.plugin_name\n\n    @abstractmethod\n    def get_state(self) -> bool:\n        """\n        获取插件运行状态\n        """\n        pass\n\n    @staticmethod\n    def get_command() -> List[Dict[str, Any]]:\n        """\n        注册插件远程命令\n        [{\n            "cmd": "/xx",\n            "event": EventType.xx,\n            "desc": "名称",\n            "category": "分类，需要注册到Wechat时必须有分类",\n            "data": {}\n        }]\n        """\n        pass\n\n    @staticmethod\n    def get_render_mode() -> Tuple[str, Optional[str]]:\n        """\n        获取插件渲染模式\n        :return: 1、渲染模式，支持：vue/vuetify，默认vuetify；2、vue模式下编译后文件的相对路径，默认为`dist/asserts`，vuetify模式下为None\n        """\n        return "vuetify", None\n\n    @abstractmethod\n    def get_api(self) -> List[Dict[str, Any]]:\n        """\n        注册插件API\n        [{\n            "path": "/xx",\n            "endpoint": self.xxx,\n            "methods": ["GET", "POST"],\n            "auth: "apikey",  # 鉴权类型：apikey/bear\n            "summary": "API名称",\n            "description": "API说明"\n        }]\n        """\n        pass\n\n    @abstractmethod\n    def get_form(self) -> Tuple[Optional[List[dict]], Dict[str, Any]]:\n        """\n        拼装插件配置页面，插件配置页面使用Vuetify组件拼装，参考：https://vuetifyjs.com/\n        :return: 1、页面配置（vuetify模式）或 None（vue模式）；2、默认数据结构\n        """\n        pass\n\n    @abstractmethod\n    def get_page(self) -> Optional[List[dict]]:\n        """\n        拼装插件详情页面，需要返回页面配置，同时附带数据\n        插件详情页面使用Vuetify组件拼装，参考：https://vuetifyjs.com/\n        :return: 页面配置（vuetify模式）或 None（vue模式）\n        """\n        pass\n\n    def get_service(self) -> List[Dict[str, Any]]:\n        """\n        注册插件公共服务\n        [{\n            "id": "服务ID",\n            "name": "服务名称",\n            "trigger": "触发器：cron/interval/date/CronTrigger.from_crontab()",\n            "func": self.xxx,\n            "kwargs": {} # 定时器参数\n        }]\n        """\n        pass\n\n    def get_dashboard(self, key: str, **kwargs) -> Optional[Tuple[Dict[str, Any], Dict[str, Any], Optional[List[dict]]]]:\n        """\n        获取插件仪表盘页面，需要返回：1、仪表板col配置字典；2、全局配置（布局、自动刷新等）；3、仪表板页面元素配置含数据json（vuetify）或 None（vue模式）\n        1、col配置参考：\n        {\n            "cols": 12, "md": 6\n        }\n        2、全局配置参考：\n        {\n            "refresh": 10, // 自动刷新时间，单位秒\n            "border": True, // 是否显示边框，默认True，为False时取消组件边框和边距，由插件自行控制\n            "title": "组件标题", // 组件标题，如有将显示该标题，否则显示插件名称\n            "subtitle": "组件子标题", // 组件子标题，缺省时不展示子标题\n        }\n        3、vuetify模式页面配置使用Vuetify组件拼装，参考：https://vuetifyjs.com/；vue模式为None\n\n        kwargs参数可获取的值：1、user_agent：浏览器UA\n\n        :param key: 仪表盘key，根据指定的key返回相应的仪表盘数据，缺省时返回一个固定的仪表盘数据（兼容旧版）\n        """\n        pass\n\n    def get_dashboard_meta(self) -> Optional[List[Dict[str, str]]]:\n        """\n        获取插件仪表盘元信息\n        返回示例：\n            [{\n                "key": "dashboard1", // 仪表盘的key，在当前插件范围唯一\n                "name": "仪表盘1" // 仪表盘的名称\n            }, {\n                "key": "dashboard2",\n                "name": "仪表盘2"\n            }]\n        """\n        pass\n\n    def get_auth_providers(self) -> List[Dict[str, Any]]:\n        """\n        声明插件提供的登录认证入口。\n\n        返回示例：\n        [{\n            "id": "oidc",\n            "name": "OIDC 登录",\n            "icon": "mdi-openid",\n            "component": "AuthPage",\n            "enabled": True\n        }]\n        """\n        pass\n\n    def get_module(self) -> Dict[str, Any]:\n        """\n        获取插件模块声明，用于胁持系统模块实现（方法名：方法实现）\n        {\n            "id1": self.xxx1,\n            "id2": self.xxx2,\n        }\n        """\n        pass\n\n    def get_actions(self) -> List[Dict[str, Any]]:\n        """\n        获取插件工作流动作\n        [{\n            "id": "动作ID",\n            "name": "动作名称",\n            "func": self.xxx,\n            "kwargs": {} # 需要附加传递的参数\n        }]\n\n        对实现函数的要求：\n        1、函数的第一个参数固定为 ActionContent 实例，如需要传递额外参数，在kwargs中定义\n        2、函数的返回：执行状态 True / False，更新后的 ActionContent 实例\n        """\n        pass\n\n    def get_agent_tools(self) -> List[Type]:\n        """\n        获取插件智能体工具\n        返回工具类列表，每个工具类必须继承自 MoviePilotTool\n        [ToolClass1, ToolClass2, ...]\n\n        对工具类的要求：\n        1、工具类必须继承自 app.agent.tools.base.MoviePilotTool\n        2、工具类需要实现 run 方法（异步方法）\n        3、工具类需要定义 name 和 description 属性\n        4、工具类可以定义 args_schema 来指定输入参数模型\n        """\n        pass\n\n    @abstractmethod\n    def stop_service(self):\n        """\n        停止插件\n        """\n        pass\n\n    def update_config(self, config: dict, plugin_id: Optional[str] = None) -> bool:\n        """\n        更新配置信息\n        :param config: 配置信息字典\n        :param plugin_id: 插件ID\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        return self.systemconfig.set(f"plugin.{plugin_id}", config)\n\n    def get_config(self, plugin_id: Optional[str] = None) -> Any:\n        """\n        获取配置信息\n        :param plugin_id: 插件ID\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        return self.systemconfig.get(f"plugin.{plugin_id}")\n\n    def get_data_path(self, plugin_id: Optional[str] = None) -> Path:\n        """\n        获取插件数据保存目录\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        data_path = settings.PLUGIN_DATA_PATH / f"{plugin_id}"\n        if not data_path.exists():\n            data_path.mkdir(parents=True)\n        return data_path\n\n    def save_data(self, key: str, value: Any, plugin_id: Optional[str] = None):\n        """\n        保存插件数据\n        :param key: 数据key\n        :param value: 数据值\n        :param plugin_id: 插件ID\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        self.plugindata.save(plugin_id, key, value)\n\n    async def async_save_data(\n        self, key: str, value: Any, plugin_id: Optional[str] = None\n    ) -> None:\n        """\n        异步保存插件数据\n\n        :param key: 数据键\n        :param value: 数据值\n        :param plugin_id: 插件ID\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        await self.plugindata.async_save(plugin_id, key, value)\n\n    def get_data(self, key: Optional[str] = None, plugin_id: Optional[str] = None) -> Any:\n        """\n        获取插件数据\n        :param key: 数据key\n        :param plugin_id: plugin_id\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        return self.plugindata.get_data(plugin_id, key)\n\n    async def async_get_data(\n        self, key: Optional[str] = None, plugin_id: Optional[str] = None\n    ) -> Any:\n        """\n        异步获取插件数据\n\n        :param key: 数据键\n        :param plugin_id: 插件ID\n        :return: 指定键的数据值或插件的全部数据\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        return await self.plugindata.async_get_data(plugin_id, key)\n\n    def del_data(self, key: str, plugin_id: Optional[str] = None) -> Any:\n        """\n        删除插件数据\n        :param key: 数据key\n        :param plugin_id: plugin_id\n        """\n        if not plugin_id:\n            plugin_id = self.__class__.__name__\n        return self.plugindata.del_data(plugin_id, key)\n\n    def post_message(self, channel: MessageChannel = None, mtype: NotificationType = None, title: Optional[str] = None,\n                     text: Optional[str] = None, image: Optional[str] = None, link: Optional[str] = None,\n                     userid: Optional[str] = None, username: Optional[str] = None,\n                     **kwargs):\n        """\n        发送消息\n        """\n        if not link:\n            link = settings.MP_DOMAIN(f"#/plugins?tab=installed&id={self.__class__.__name__}")\n        self.chain.post_message(Notification(\n            channel=channel, mtype=mtype, title=title, text=text,\n            image=image, link=link, userid=userid, username=username, **kwargs\n        ))\n\n    def close(self):\n        pass\n', 'scheduler': 'import asyncio\nimport gc\nimport hashlib\nimport inspect\nimport json\nimport multiprocessing\nimport threading\nimport traceback\nfrom datetime import datetime, timedelta\nfrom typing import Callable, Optional, Dict, Any\nfrom typing import List\n\nimport pytz\nfrom apscheduler.executors.pool import ThreadPoolExecutor\nfrom apscheduler.jobstores.base import JobLookupError\nfrom apscheduler.schedulers.background import BackgroundScheduler\nfrom apscheduler.triggers.cron import CronTrigger\nfrom sqlalchemy.orm import Session\n\nfrom app import schemas\nfrom app.chain import ChainBase\nfrom app.chain.mediaserver import MediaServerChain\nfrom app.chain.recommend import RecommendChain\nfrom app.chain.site import SiteChain\nfrom app.chain.subscribe import SubscribeChain\nfrom app.chain.transfer import TransferChain\nfrom app.chain.workflow import WorkflowChain\nfrom app.core.config import settings, global_vars\nfrom app.core.event import Event, eventmanager\nfrom app.core.plugin import PluginManager\nfrom app.db import SessionFactory\nfrom app.db.agenttask_oper import AgentTaskOper\nfrom app.db.models.downloadhistory import DownloadHistory, DownloadFiles\nfrom app.db.models.message import Message\nfrom app.db.models.siteuserdata import SiteUserData\nfrom app.db.models.transferhistory import TransferHistory\nfrom app.db.systemconfig_oper import SystemConfigOper\nfrom app.helper.image import WallpaperHelper\nfrom app.helper.message import MessageHelper\nfrom app.helper.progress import ProgressHelper\nfrom app.helper.server import MoviePilotServerHelper\nfrom app.helper.service import ServiceConfigHelper\nfrom app.helper.sites import SitesHelper  # noqa\nfrom app.log import logger\nfrom app.schemas import Notification, NotificationType, Workflow\nfrom app.schemas.types import EventType, SystemConfigKey\nfrom app.utils.gc import get_memory_usage\nfrom app.utils.mixins import ConfigReloadMixin\nfrom app.utils.singleton import SingletonClass\nfrom app.utils.timer import TimerUtils\n\nlock = threading.Lock()\nSCHEDULER_PROGRESS_PREFIX = "scheduler"\nAGENT_TASK_JOB_PREFIX = "agent-task"\n\n\nclass SchedulerChain(ChainBase):\n    """\n    定时任务链，负责执行各类定时任务，包括数据清理等\n    """\n    # 每批处理的记录数，避免一次性删除过多数据导致性能问题\n    DEFAULT_BATCH_SIZE = 500\n\n    def cleanup(\n            self,\n            batch_size: Optional[int] = None,\n            progress_callback: Optional[Callable[..., None]] = None,\n    ) -> Dict[str, Any]:\n        """\n        按配置保留期执行分批清理。\n        """\n        started_at = datetime.now()\n        batch_size = batch_size or self.DEFAULT_BATCH_SIZE\n        if batch_size <= 0:\n            batch_size = self.DEFAULT_BATCH_SIZE\n\n        report: Dict[str, Any] = {\n            "started_at": started_at.strftime("%Y-%m-%d %H:%M:%S"),\n            "batch_size": batch_size,\n            "enabled": bool(settings.DATA_CLEANUP_ENABLE),\n            "tables": {},\n            "total_deleted": 0,\n        }\n\n        if not settings.DATA_CLEANUP_ENABLE:\n            report["skipped_reason"] = "disabled"\n            logger.info("数据表清理总开关未开启，跳过执行")\n            return report\n\n        errors = []\n\n        plans = self._build_cleanup_plans(started_at=started_at, batch_size=batch_size)\n        total_plans = len(plans)\n        if progress_callback:\n            progress_callback(value=0, text="开始清理数据表 ...")\n\n        with SessionFactory() as db:\n            for plan_index, plan in enumerate(plans):\n                name = plan["name"]\n                retention_days = plan["retention_days"]\n                if retention_days <= 0:\n                    report["tables"][name] = {\n                        "deleted": 0,\n                        "batches": 0,\n                        "cutoff": None,\n                        "retention_days": retention_days,\n                        "skipped": True,\n                        "reason": "retention_days<=0",\n                    }\n                    if progress_callback:\n                        progress_callback(\n                            value=(plan_index + 1) / total_plans * 100,\n                            text=f"数据表 {name} 跳过清理",\n                        )\n                    continue\n\n                try:\n                    if progress_callback:\n                        progress_callback(\n                            value=plan_index / total_plans * 100,\n                            text=f"正在清理数据表 {name} ...",\n                        )\n                    table_report = self._cleanup_in_batches(\n                        db=db,\n                        table_name=name,\n                        delete_batch=plan["handler"],\n                    )\n                    table_report["cutoff"] = plan["cutoff"]\n                    table_report["retention_days"] = retention_days\n                    report["tables"][name] = table_report\n                    report["total_deleted"] += table_report["deleted"]\n                except Exception as err:\n                    errors.append(f"{name}: {str(err)}")\n                    logger.error(f"数据表 {name} 清理失败：{str(err)}")\n                    report["tables"][name] = {\n                        "deleted": 0,\n                        "batches": 0,\n                        "cutoff": plan["cutoff"],\n                        "retention_days": retention_days,\n                        "error": str(err),\n                    }\n                finally:\n                    if progress_callback:\n                        progress_callback(\n                            value=(plan_index + 1) / total_plans * 100,\n                            text=f"数据表 {name} 清理处理完成",\n                        )\n\n        if errors:\n            report["errors"] = errors\n            logger.error(\n                f"数据表清理部分失败：{json.dumps(report, ensure_ascii=False)}"\n            )\n            raise RuntimeError("；".join(errors))\n\n        logger.info(f"数据表清理完成：{json.dumps(report, ensure_ascii=False)}")\n        return report\n\n    @staticmethod\n    def _normalize_retention_days(retention_days: Any) -> int:\n        try:\n            normalized_days = int(retention_days or 0)\n        except (TypeError, ValueError):\n            return 0\n        return max(normalized_days, 0)\n\n    def _build_cleanup_plans(\n            self,\n            started_at: datetime,\n            batch_size: int,\n    ) -> List[Dict[str, Any]]:\n        message_days = self._normalize_retention_days(settings.DATA_CLEANUP_MESSAGE_DAYS)\n        download_history_days = self._normalize_retention_days(\n            settings.DATA_CLEANUP_DOWNLOAD_HISTORY_DAYS\n        )\n        site_userdata_days = self._normalize_retention_days(\n            settings.DATA_CLEANUP_SITE_USERDATA_DAYS\n        )\n        transfer_history_days = self._normalize_retention_days(\n            settings.DATA_CLEANUP_TRANSFER_HISTORY_DAYS\n        )\n\n        message_cutoff = (\n                started_at - timedelta(days=message_days)\n        ).strftime("%Y-%m-%d")\n        download_history_cutoff = (\n                started_at - timedelta(days=download_history_days)\n        ).strftime("%Y-%m-%d")\n        site_userdata_cutoff = (\n                started_at - timedelta(days=site_userdata_days)\n        ).strftime("%Y-%m-%d")\n        transfer_history_cutoff = (\n                started_at - timedelta(days=transfer_history_days)\n        ).strftime("%Y-%m-%d")\n\n        return [\n            {\n                "name": "message",\n                "retention_days": message_days,\n                "cutoff": message_cutoff,\n                "handler": lambda db: Message.delete_before(\n                    db=db,\n                    before_time=message_cutoff,\n                    limit=batch_size,\n                ),\n            },\n            {\n                "name": "downloadhistory",\n                "retention_days": download_history_days,\n                "cutoff": download_history_cutoff,\n                "handler": lambda db: DownloadHistory.delete_before(\n                    db=db,\n                    before_time=download_history_cutoff,\n                    limit=batch_size,\n                ),\n            },\n            {\n                "name": "downloadfiles",\n                "retention_days": download_history_days,\n                "cutoff": "follow-parent-history",\n                "handler": lambda db: DownloadFiles.delete_orphans(\n                    db=db,\n                    limit=batch_size,\n                ),\n            },\n            {\n                "name": "siteuserdata",\n                "retention_days": site_userdata_days,\n                "cutoff": site_userdata_cutoff,\n                "handler": lambda db: SiteUserData.delete_before(\n                    db=db,\n                    before_day=site_userdata_cutoff,\n                    limit=batch_size,\n                ),\n            },\n            {\n                "name": "transferhistory",\n                "retention_days": transfer_history_days,\n                "cutoff": transfer_history_cutoff,\n                "handler": lambda db: TransferHistory.delete_before(\n                    db=db,\n                    before_time=transfer_history_cutoff,\n                    limit=batch_size,\n                ),\n            },\n        ]\n\n    @staticmethod\n    def _cleanup_in_batches(\n            db: Session,\n            table_name: str,\n            delete_batch: Callable[[Session], int],\n    ) -> Dict[str, int]:\n        """\n        循环执行单表分批删除，直到没有可删除数据。\n        """\n        total_deleted = 0\n        batches = 0\n\n        while True:\n            deleted = delete_batch(db) or 0\n            if deleted <= 0:\n                break\n            batches += 1\n            total_deleted += deleted\n            logger.info(\n                f"数据表 {table_name} 清理第 {batches} 批完成，删除 {deleted} 条记录"\n            )\n\n        return {\n            "deleted": total_deleted,\n            "batches": batches,\n        }\n\n\nclass Scheduler(ConfigReloadMixin, metaclass=SingletonClass):\n    """\n    定时任务管理\n    """\n\n    CONFIG_WATCH = {\n        "DEV",\n        "COOKIECLOUD_INTERVAL",\n        "MEDIASERVER_SYNC_INTERVAL",\n        SystemConfigKey.MediaServers.value,\n        "SUBSCRIBE_SEARCH",\n        "SUBSCRIBE_SEARCH_INTERVAL",\n        "SUBSCRIBE_MODE",\n        "SUBSCRIBE_RSS_INTERVAL",\n        "SITEDATA_REFRESH_INTERVAL",\n        "AI_AGENT_ENABLE",\n        "AI_AGENT_JOB_INTERVAL",\n        "DATA_CLEANUP_ENABLE",\n        "DATA_CLEANUP_MESSAGE_DAYS",\n        "DATA_CLEANUP_DOWNLOAD_HISTORY_DAYS",\n        "DATA_CLEANUP_SITE_USERDATA_DAYS",\n        "DATA_CLEANUP_TRANSFER_HISTORY_DAYS",\n        "USAGE_STATISTIC_SHARE",\n    }\n\n    def __init__(self):\n        # 定时服务\n        self._scheduler = None\n        # 退出事件\n        self._event = threading.Event()\n        # 锁\n        self._lock = threading.RLock()\n        # 各服务的运行状态\n        self._jobs = {}\n        # 用户认证失败次数\n        self._auth_count = 0\n        # 用户认证失败消息发送\n        self._auth_message = False\n        # 初始化\n        self.init()\n\n    def on_config_changed(self) -> None:\n        """\n        配置变更后重新初始化定时服务。\n        """\n        self.init()\n\n    def get_reload_name(self) -> str:\n        """\n        获取配置重载日志中的服务名称。\n        """\n        return "定时服务"\n\n    @staticmethod\n    def _get_mediaserver_sync_interval(\n            mediaserver: schemas.MediaServerConf,\n            default_interval: Optional[int],\n    ) -> Optional[int]:\n        """\n        获取媒体服务器的有效同步间隔，未设置时回退旧全局配置。\n        """\n        interval = mediaserver.sync_interval\n        if interval is None:\n            interval = default_interval\n        try:\n            interval = int(interval)\n        except (TypeError, ValueError):\n            return None\n        return interval if interval > 0 else None\n\n    @classmethod\n    def _build_mediaserver_sync_schedules(\n            cls,\n            mediaservers: List[schemas.MediaServerConf],\n            default_interval: Optional[int],\n    ) -> List[dict]:\n        """\n        构建已启用媒体服务器的独立自动同步任务描述。\n        """\n        schedules = []\n        job_ids = set()\n        for mediaserver in mediaservers:\n            if not mediaserver or not mediaserver.enabled or not mediaserver.name:\n                continue\n            interval = cls._get_mediaserver_sync_interval(\n                mediaserver=mediaserver,\n                default_interval=default_interval,\n            )\n            if not interval:\n                continue\n            digest = hashlib.sha256(mediaserver.name.encode("utf-8")).hexdigest()[:12]\n            job_id = f"mediaserver_sync_{digest}"\n            if job_id in job_ids:\n                continue\n            job_ids.add(job_id)\n            schedules.append(\n                {\n                    "id": job_id,\n                    "name": f"同步媒体服务器 - {mediaserver.name}",\n                    "server": mediaserver.name,\n                    "interval": interval,\n                }\n            )\n        return schedules\n\n    @staticmethod\n    def _get_progress_key(job_id: str) -> str:\n        """\n        获取定时服务进度缓存键。\n        """\n        return f"{SCHEDULER_PROGRESS_PREFIX}:{job_id}"\n\n    @staticmethod\n    def _format_time(value: Optional[datetime] = None) -> str:\n        """\n        格式化进度事件时间。\n        """\n        return (value or datetime.now()).strftime("%Y-%m-%d %H:%M:%S")\n\n    def init(self) -> None:\n        """\n        初始化定时服务\n        """\n\n        # 停止定时服务\n        self.stop()\n\n        # 调试模式不启动定时服务\n        if settings.DEV:\n            return\n\n        with lock:\n            # 各服务的运行状态\n            mediaserver_chain = MediaServerChain()\n            self._jobs = {\n                "cookiecloud": {\n                    "name": "同步CookieCloud站点",\n                    "func": SiteChain().sync_cookies,\n                    "running": False,\n                },\n                "mediaserver_sync": {\n                    "name": "同步媒体服务器",\n                    "func": mediaserver_chain.sync,\n                    "running": False,\n                },\n                "subscribe_tmdb": {\n                    "name": "订阅元数据更新",\n                    "func": SubscribeChain().check,\n                    "running": False,\n                },\n                "subscribe_search": {\n                    "name": "订阅搜索补全",\n                    "func": SubscribeChain().search,\n                    "running": False,\n                    "kwargs": {"state": "R"},\n                },\n                "new_subscribe_search": {\n                    "name": "新增订阅搜索",\n                    "func": SubscribeChain().search,\n                    "running": False,\n                    "kwargs": {"state": "N"},\n                },\n                "subscribe_refresh": {\n                    "name": "订阅刷新",\n                    "func": SubscribeChain().refresh,\n                    "running": False,\n                },\n                "subscribe_follow": {\n                    "name": "关注的订阅分享",\n                    "func": SubscribeChain().follow,\n                    "running": False,\n                },\n                "transfer": {\n                    "name": "下载文件整理",\n                    "func": TransferChain().process,\n                    "running": False,\n                },\n                "clear_cache": {\n                    "name": "缓存清理",\n                    "func": self.clear_cache,\n                    "running": False,\n                },\n                "data_cleanup": {\n                    "name": "数据表清理",\n                    "func": SchedulerChain().cleanup,\n                    "running": False,\n                },\n                "user_auth": {\n                    "name": "用户认证检查",\n                    "func": self.user_auth,\n                    "running": False,\n                },\n                "scheduler_job": {\n                    "name": "公共定时服务",\n                    "func": SchedulerChain().scheduler_job,\n                    "running": False,\n                },\n                "random_wallpager": {\n                    "name": "壁纸缓存",\n                    "func": WallpaperHelper().get_wallpapers,\n                    "running": False,\n                },\n                "sitedata_refresh": {\n                    "name": "站点数据刷新",\n                    "func": SiteChain().refresh_userdatas,\n                    "running": False,\n                },\n                "recommend_refresh": {\n                    "name": "推荐缓存",\n                    "func": RecommendChain().refresh_recommend,\n                    "running": False,\n                },\n                "plugin_market_refresh": {\n                    "name": "插件市场缓存",\n                    "func": PluginManager().async_get_online_plugins,\n                    "running": False,\n                    "kwargs": {"force": True},\n                },\n                "subscribe_calendar_cache": {\n                    "name": "订阅日历缓存",\n                    "func": SubscribeChain().cache_calendar,\n                    "running": False,\n                },\n                "full_gc": {\n                    "name": "主动内存回收",\n                    "func": self.full_gc,\n                    "running": False,\n                },\n                "agent_heartbeat": {\n                    "name": "智能体定时任务",\n                    "func": self.agent_heartbeat,\n                    "running": False,\n                },\n                "usage_report": {\n                    "name": "安装版本统计上报",\n                    "func": MoviePilotServerHelper.report_usage,\n                    "running": False,\n                },\n            }\n\n            # 创建定时服务\n            self._scheduler = BackgroundScheduler(\n                timezone=settings.TZ,\n                executors={"default": ThreadPoolExecutor(settings.CONF.scheduler)},\n            )\n\n            # CookieCloud定时同步\n            if (\n                    settings.COOKIECLOUD_INTERVAL\n                    and str(settings.COOKIECLOUD_INTERVAL).isdigit()\n            ):\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id="cookiecloud",\n                    name="同步CookieCloud站点",\n                    minutes=int(settings.COOKIECLOUD_INTERVAL),\n                    next_run_time=datetime.now(pytz.timezone(settings.TZ)) + timedelta(minutes=5),\n                    kwargs={"job_id": "cookiecloud"},\n                )\n\n            # 按媒体服务器分别注册自动同步任务\n            mediaserver_schedules = self._build_mediaserver_sync_schedules(\n                mediaservers=ServiceConfigHelper.get_mediaserver_configs(),\n                default_interval=settings.MEDIASERVER_SYNC_INTERVAL,\n            )\n            for mediaserver_schedule in mediaserver_schedules:\n                job_id = mediaserver_schedule["id"]\n                self._jobs[job_id] = {\n                    "name": mediaserver_schedule["name"],\n                    "func": mediaserver_chain.sync,\n                    "running": False,\n                    "kwargs": {"server": mediaserver_schedule["server"]},\n                }\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id=job_id,\n                    name=mediaserver_schedule["name"],\n                    hours=mediaserver_schedule["interval"],\n                    next_run_time=datetime.now(pytz.timezone(settings.TZ)) + timedelta(minutes=10),\n                    kwargs={"job_id": job_id},\n                )\n\n            # 新增订阅时搜索（5分钟检查一次）\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="new_subscribe_search",\n                name="新增订阅搜索",\n                minutes=5,\n                kwargs={"job_id": "new_subscribe_search"},\n            )\n\n            # 检查更新订阅TMDB数据（每隔6小时）\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="subscribe_tmdb",\n                name="订阅元数据更新",\n                hours=6,\n                kwargs={"job_id": "subscribe_tmdb"},\n            )\n\n            # 订阅状态每隔24小时搜索一次\n            if settings.SUBSCRIBE_SEARCH:\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id="subscribe_search",\n                    name="订阅搜索补全",\n                    hours=settings.SUBSCRIBE_SEARCH_INTERVAL,\n                    kwargs={"job_id": "subscribe_search"},\n                )\n\n            if settings.SUBSCRIBE_MODE == "spider":\n                # 站点首页种子定时刷新模式\n                triggers = TimerUtils.random_scheduler(num_executions=32)\n                for trigger in triggers:\n                    self._scheduler.add_job(\n                        self.start,\n                        "cron",\n                        id=f"subscribe_refresh|{trigger.hour}:{trigger.minute}",\n                        name="订阅刷新",\n                        hour=trigger.hour,\n                        minute=trigger.minute,\n                        kwargs={"job_id": "subscribe_refresh"},\n                    )\n            else:\n                # RSS订阅模式\n                if (\n                        not settings.SUBSCRIBE_RSS_INTERVAL\n                        or not str(settings.SUBSCRIBE_RSS_INTERVAL).isdigit()\n                ):\n                    settings.SUBSCRIBE_RSS_INTERVAL = 30\n                elif int(settings.SUBSCRIBE_RSS_INTERVAL) < 5:\n                    settings.SUBSCRIBE_RSS_INTERVAL = 5\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id="subscribe_refresh",\n                    name="RSS订阅刷新",\n                    minutes=int(settings.SUBSCRIBE_RSS_INTERVAL),\n                    kwargs={"job_id": "subscribe_refresh"},\n                )\n\n            # 关注订阅分享（每1小时）\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="subscribe_follow",\n                name="关注的订阅分享",\n                hours=1,\n                kwargs={"job_id": "subscribe_follow"},\n            )\n\n            # 下载器文件转移（每5分钟）\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="transfer",\n                name="下载文件整理",\n                minutes=5,\n                kwargs={"job_id": "transfer"},\n            )\n\n            # 后台刷新TMDB壁纸\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="random_wallpager",\n                name="壁纸缓存",\n                minutes=30,\n                next_run_time=datetime.now(pytz.timezone(settings.TZ)) + timedelta(seconds=1),\n                kwargs={"job_id": "random_wallpager"},\n            )\n\n            # 公共定时服务\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="scheduler_job",\n                name="公共定时服务",\n                minutes=10,\n                kwargs={"job_id": "scheduler_job"},\n            )\n\n            # 数据表清理服务，每天凌晨执行一次\n            if settings.DATA_CLEANUP_ENABLE:\n                self._scheduler.add_job(\n                    self.start,\n                    "cron",\n                    id="data_cleanup",\n                    name="数据表清理",\n                    hour=3,\n                    minute=30,\n                    kwargs={"job_id": "data_cleanup"},\n                )\n\n            # 定时检查用户认证，每隔10分钟\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="user_auth",\n                name="用户认证检查",\n                minutes=10,\n                kwargs={"job_id": "user_auth"},\n            )\n\n            # 站点数据刷新\n            if settings.SITEDATA_REFRESH_INTERVAL:\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id="sitedata_refresh",\n                    name="站点数据刷新",\n                    minutes=settings.SITEDATA_REFRESH_INTERVAL * 60,\n                    kwargs={"job_id": "sitedata_refresh"},\n                )\n\n            # 推荐缓存\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="recommend_refresh",\n                name="推荐缓存",\n                hours=24,\n                next_run_time=datetime.now(pytz.timezone(settings.TZ)) + timedelta(seconds=5),\n                kwargs={"job_id": "recommend_refresh"},\n            )\n\n            # 插件市场缓存\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="plugin_market_refresh",\n                name="插件市场缓存",\n                minutes=30,\n                kwargs={"job_id": "plugin_market_refresh"},\n            )\n\n            # 订阅日历缓存\n            self._scheduler.add_job(\n                self.start,\n                "interval",\n                id="subscribe_calendar_cache",\n                name="订阅日历缓存",\n                hours=6,\n                next_run_time=datetime.now(pytz.timezone(settings.TZ)) + timedelta(minutes=2),\n                kwargs={"job_id": "subscribe_calendar_cache"},\n            )\n\n            # 主动内存回收\n            if settings.MEMORY_GC_INTERVAL:\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id="full_gc",\n                    name="主动内存回收",\n                    minutes=settings.MEMORY_GC_INTERVAL,\n                    kwargs={"job_id": "full_gc"},\n                )\n\n            # 智能体定时任务检查\n            if settings.AI_AGENT_ENABLE and settings.AI_AGENT_JOB_INTERVAL:\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id="agent_heartbeat",\n                    name="智能体定时任务",\n                    hours=settings.AI_AGENT_JOB_INTERVAL,\n                    kwargs={"job_id": "agent_heartbeat"},\n                )\n\n            # 安装版本统计上报\n            if settings.USAGE_STATISTIC_SHARE:\n                self._scheduler.add_job(\n                    self.start,\n                    "interval",\n                    id="usage_report",\n                    name="安装版本统计上报",\n                    hours=12,\n                    kwargs={"job_id": "usage_report"},\n                )\n\n            # 初始化工作流服务\n            self.init_workflow_jobs()\n\n            # 恢复 Agent 自主定时任务\n            if settings.AI_AGENT_ENABLE:\n                self.init_agent_task_jobs()\n\n            # 初始化插件服务\n            self.init_plugin_jobs()\n\n            # 启动定时服务\n            self._scheduler.start()\n\n    def __prepare_job(self, job_id: str) -> Optional[dict]:\n        """\n        准备定时任务\n        """\n        started_at = self._format_time()\n        with self._lock:\n            job = self._jobs.get(job_id)\n            if not job:\n                return None\n            if job.get("running"):\n                logger.warning(f"定时任务 {job_id} - {job.get(\'name\')} 正在运行 ...")\n                return None\n            self._jobs[job_id]["running"] = True\n            self._jobs[job_id]["last_started_at"] = started_at\n            self._jobs[job_id]["last_finished_at"] = None\n            self._jobs[job_id]["last_error"] = None\n        progress = ProgressHelper(self._get_progress_key(job_id))\n        progress.start()\n        progress.update(\n            value=0,\n            text=f"{job.get(\'name\') or job_id} 开始执行 ...",\n            data={\n                "id": job_id,\n                "name": job.get("name"),\n                "provider": job.get("provider_name", "[系统]"),\n                "status": "running",\n                "success": None,\n                "started_at": started_at,\n                "finished_at": None,\n                "error": None,\n            },\n        )\n        return job\n\n    def __finish_job(\n            self,\n            job_id: str,\n            success: bool = True,\n            error: Optional[str] = None,\n    ) -> None:\n        """\n        完成定时任务\n        """\n        finished_at = self._format_time()\n        job = None\n        with self._lock:\n            job = self._jobs.get(job_id)\n            if job:\n                job["running"] = False\n                job["last_finished_at"] = finished_at\n                job["last_error"] = error\n        job_name = job.get("name") if job else job_id\n        progress = ProgressHelper(self._get_progress_key(job_id))\n        current_progress = progress.get() or {}\n        progress_value = 100 if success else current_progress.get("value", 0)\n        progress.end(\n            text=f"{job_name} {\'执行完成\' if success else \'执行失败\'}",\n            data={\n                "id": job_id,\n                "name": job_name,\n                "provider": job.get("provider_name", "[系统]") if job else None,\n                "status": "success" if success else "failed",\n                "success": success,\n                "finished_at": finished_at,\n                "error": error,\n            },\n            value=progress_value,\n        )\n\n    def get_progress(self, job_id: str) -> Optional[schemas.ScheduleProgress]:\n        """\n        查询指定定时服务的执行进度。\n        """\n        if not job_id:\n            return None\n        with self._lock:\n            job = self._jobs.get(job_id)\n            job_name = job.get("name") if job else job_id\n            provider_name = job.get("provider_name", "[系统]") if job else None\n            running = bool(job.get("running")) if job else False\n            last_started_at = job.get("last_started_at") if job else None\n            last_finished_at = job.get("last_finished_at") if job else None\n            last_error = job.get("last_error") if job else None\n        detail = ProgressHelper(self._get_progress_key(job_id)).get() or {}\n        if not job and not detail:\n            return None\n        data = detail.get("data") or {}\n        value = detail.get("value", 0)\n        try:\n            value = float(value)\n        except (TypeError, ValueError):\n            value = 0.0\n        return schemas.ScheduleProgress(\n            id=job_id,\n            name=data.get("name") or job_name,\n            provider=data.get("provider") or provider_name,\n            enable=bool(detail.get("enable", running)),\n            value=max(min(value, 100), 0),\n            text=detail.get("text"),\n            status=data.get("status") or ("running" if running else "waiting"),\n            success=data.get("success"),\n            started_at=data.get("started_at") or last_started_at,\n            finished_at=data.get("finished_at") or last_finished_at,\n            error=data.get("error") or last_error,\n            data=data,\n        )\n\n    @staticmethod\n    def __handle_job_error(job_id: str, job: dict, error: Exception) -> None:\n        """\n        记录定时任务执行异常并发送系统错误事件。\n        """\n        logger.error(\n            f"定时任务 {job.get(\'name\')} 执行失败：{str(error)} - {traceback.format_exc()}"\n        )\n        MessageHelper().put(\n            title=f"{job.get(\'name\')} 执行失败", message=str(error), role="system"\n        )\n        eventmanager.send_event(\n            EventType.SystemError,\n            {\n                "type": "scheduler",\n                "scheduler_id": job_id,\n                "scheduler_name": job.get("name"),\n                "error": str(error),\n                "traceback": traceback.format_exc(),\n            },\n        )\n\n    def __build_progress_callback(self, job_id: str, job: dict) -> Callable[..., None]:\n        """\n        构建传递给定时任务内部的进度更新回调。\n        """\n\n        def update_progress(\n                value: Optional[float] = None,\n                text: Optional[str] = None,\n                data: Optional[dict] = None,\n        ) -> None:\n            """\n            更新当前定时任务进度。\n            """\n            progress_data = {\n                "id": job_id,\n                "name": job.get("name"),\n                "provider": job.get("provider_name", "[系统]"),\n                "status": "running",\n                "success": None,\n            }\n            if data:\n                progress_data.update(data)\n            ProgressHelper(self._get_progress_key(job_id)).update(\n                value=value,\n                text=text,\n                data=progress_data,\n            )\n\n        return update_progress\n\n    @staticmethod\n    def __supports_progress_callback(func: Callable[..., Any]) -> bool:\n        """\n        判断定时任务函数是否显式支持进度回调参数。\n        """\n        try:\n            parameters = inspect.signature(func).parameters\n        except (TypeError, ValueError):\n            return False\n        return "progress_callback" in parameters\n\n    @staticmethod\n    def __get_result_error(result: Any) -> Optional[str]:\n        """\n        从定时任务标准失败返回值中提取错误信息。\n        """\n        if (\n                isinstance(result, tuple)\n                and result\n                and isinstance(result[0], bool)\n                and result[0] is False\n        ):\n            return str(result[1]) if len(result) > 1 and result[1] else "定时任务返回失败"\n        return None\n\n    async def __run_coro_job(self, coro, job_id: str, job: dict) -> None:\n        """\n        在当前事件循环内执行协程定时任务并在真实完成后收敛状态。\n        """\n        success = True\n        error = None\n        try:\n            result = await coro\n            error = self.__get_result_error(result)\n            success = error is None\n        except Exception as err:\n            success = False\n            error = str(err)\n            self.__handle_job_error(job_id=job_id, job=job, error=err)\n        finally:\n            self.__finish_job(job_id=job_id, success=success, error=error)\n\n    def start(self, job_id: str, *args, **kwargs) -> None:\n        """\n        启动定时服务\n        """\n\n        def __start_coro(coro) -> bool:\n            """\n            启动协程，返回是否由异步回调自行收敛任务状态。\n            """\n            try:\n                running_loop = asyncio.get_running_loop()\n            except RuntimeError:\n                running_loop = None\n            target_loop = global_vars.loop\n            if running_loop:\n                asyncio.create_task(self.__run_coro_job(coro=coro, job_id=job_id, job=job))\n                return True\n            if target_loop and target_loop.is_running():\n                asyncio.run_coroutine_threadsafe(\n                    self.__run_coro_job(coro=coro, job_id=job_id, job=job),\n                    target_loop,\n                )\n                return True\n            asyncio.run(coro)\n            return False\n\n        # 获取定时任务\n        job = self.__prepare_job(job_id)\n        if not job:\n            return\n        success = True\n        error = None\n        deferred_finish = False\n        # 开始运行\n        try:\n            if not kwargs:\n                kwargs = dict(job.get("kwargs") or {})\n            func = job.get("func")\n            if not func:\n                return\n            if self.__supports_progress_callback(func) and "progress_callback" not in kwargs:\n                kwargs["progress_callback"] = self.__build_progress_callback(\n                    job_id=job_id, job=job\n                )\n            # 是否多进程运行\n            run_in_process = job.get("run_in_process", False)\n            if inspect.iscoroutinefunction(func):\n                # 协程函数\n                deferred_finish = __start_coro(func(*args, **kwargs))\n            elif run_in_process:\n                # 多进程运行\n                p = multiprocessing.Process(target=func, args=args, kwargs=kwargs)\n                p.start()\n                p.join()\n            else:\n                # 普通函数\n                result = func(*args, **kwargs)\n                error = self.__get_result_error(result)\n                success = error is None\n        except Exception as e:\n            success = False\n            error = str(e)\n            self.__handle_job_error(job_id=job_id, job=job, error=e)\n        finally:\n            if not deferred_finish:\n                # 运行结束\n                self.__finish_job(job_id=job_id, success=success, error=error)\n\n    @staticmethod\n    def _get_agent_task_job_id(task_id: int) -> str:\n        """生成 Agent 自主定时任务的调度器 Job ID。"""\n        return f"{AGENT_TASK_JOB_PREFIX}-{task_id}"\n\n    def start_agent_task(self, task_id: int) -> bool:\n        """\n        将指定 Agent 自主定时任务提交到运行时调度器立即执行。\n\n        :param task_id: Agent 自主定时任务 ID\n        :return: 任务存在且未运行时返回 True，否则返回 False\n        """\n        job_id = self._get_agent_task_job_id(task_id)\n        with self._lock:\n            job = self._jobs.get(job_id)\n            if not job or job.get("running"):\n                return False\n        self.start(job_id)\n        return True\n\n    def init_agent_task_jobs(self) -> None:\n        """\n        从数据库恢复所有启用的 Agent 自主定时任务。\n        """\n        oper = AgentTaskOper()\n        for task in oper.list(enabled=True):\n            if task.last_status == "running":\n                oper.update(\n                    task_id=task.id,\n                    payload={\n                        "last_status": "waiting",\n                        "last_result": "服务重启后恢复调度",\n                    },\n                )\n            self.update_agent_task_job(task.id)\n\n    def update_agent_task_job(self, task_id: int) -> Optional[str]:\n        """\n        按数据库中的最新配置新增或替换 Agent 自主定时任务。\n\n        :param task_id: Agent 定时任务 ID\n        :return: 下一次执行时间，不可调度时返回 None\n        """\n        self.remove_agent_task_job(task_id)\n        task = AgentTaskOper().get(task_id)\n        if (\n                not settings.AI_AGENT_ENABLE\n                or not task\n                or not task.enabled\n                or not self._scheduler\n        ):\n            return None\n\n        trigger_value = (\n            task.cron_expression if task.trigger_type == "cron" else task.run_at\n        )\n        try:\n            trigger = TimerUtils.build_schedule_trigger(\n                trigger_type=task.trigger_type,\n                trigger_value=trigger_value,\n                timezone_name=settings.TZ,\n            )\n        except (TypeError, ValueError) as err:\n            logger.error(f"Agent 定时任务 {task_id} 的触发配置无效：{str(err)}")\n            return None\n\n        job_id = self._get_agent_task_job_id(task_id)\n        with self._lock:\n            self._jobs[job_id] = {\n                "name": task.name,\n                "provider_name": "[Agent]",\n                "func": self.execute_agent_task,\n                "running": False,\n                "kwargs": {"task_id": task_id},\n            }\n            self._scheduler.add_job(\n                self.start,\n                trigger=trigger,\n                id=job_id,\n                name=task.name,\n                kwargs={"job_id": job_id, "task_id": task_id},\n                coalesce=True,\n                max_instances=1,\n                misfire_grace_time=None,\n                replace_existing=True,\n            )\n        return self.get_agent_task_next_run(task_id)\n\n    def remove_agent_task_job(self, task_id: int) -> None:\n        """\n        从运行时调度器移除 Agent 自主定时任务。\n\n        :param task_id: Agent 定时任务 ID\n        """\n        job_id = self._get_agent_task_job_id(task_id)\n        with self._lock:\n            self._jobs.pop(job_id, None)\n            if not self._scheduler:\n                return\n            try:\n                self._scheduler.remove_job(job_id)\n            except JobLookupError:\n                pass\n\n    def get_agent_task_next_run(self, task_id: int) -> Optional[str]:\n        """\n        查询 Agent 自主定时任务的下一次执行时间。\n\n        :param task_id: Agent 定时任务 ID\n        :return: 带时区的 ISO 8601 时间，不再执行时返回 None\n        """\n        job_id = self._get_agent_task_job_id(task_id)\n        if self._scheduler:\n            job = self._scheduler.get_job(job_id)\n            next_run_time = getattr(job, "next_run_time", None) if job else None\n            if next_run_time:\n                return next_run_time.isoformat(timespec="seconds")\n\n        task = AgentTaskOper().get(task_id)\n        if not task or not task.enabled:\n            return None\n        trigger_value = (\n            task.cron_expression if task.trigger_type == "cron" else task.run_at\n        )\n        try:\n            next_run_time = TimerUtils.get_schedule_next_run_time(\n                trigger_type=task.trigger_type,\n                trigger_value=trigger_value,\n                timezone_name=settings.TZ,\n            )\n        except (TypeError, ValueError):\n            return None\n        return (\n            next_run_time.isoformat(timespec="seconds")\n            if next_run_time\n            else None\n        )\n\n    async def execute_agent_task(self, task_id: int) -> tuple[bool, str]:\n        """\n        唤醒 Agent 执行指定自主定时任务。\n\n        :param task_id: Agent 定时任务 ID\n        :return: 执行是否成功及结果摘要\n        """\n        from app.agent import agent_manager\n\n        try:\n            return await agent_manager.execute_scheduled_task(task_id)\n        finally:\n            task = AgentTaskOper().get(task_id)\n            if task and task.trigger_type == "date" and not task.enabled:\n                self.remove_agent_task_job(task_id)\n\n    def init_plugin_jobs(self):\n        """\n        初始化插件定时服务\n        """\n        for pid in PluginManager().get_running_plugin_ids():\n            self.update_plugin_job(pid)\n\n    @eventmanager.register(EventType.PluginReload)\n    def on_plugin_reload(self, event: Event) -> None:\n        """插件重载后按当前实例重新注册全部定时服务"""\n        plugin_id = event.event_data.get("plugin_id")\n        if not plugin_id:\n            return\n        self.update_plugin_job(plugin_id)\n\n    def init_workflow_jobs(self):\n        """\n        初始化工作流定时服务\n        """\n        for workflow in WorkflowChain().get_timer_workflows() or []:\n            self.update_workflow_job(workflow)\n\n    def remove_workflow_job(self, workflow: Workflow):\n        """\n        移除工作流服务\n        """\n        if not self._scheduler:\n            return\n        with self._lock:\n            job_id = f"workflow-{workflow.id}"\n            service = self._jobs.pop(job_id, {})\n            if not service:\n                return\n            try:\n                # 在调度器中查找并移除对应的 job\n                job_removed = False\n                for job in list(self._scheduler.get_jobs()):\n                    if job_id == job.id:\n                        try:\n                            self._scheduler.remove_job(job.id)\n                            job_removed = True\n                        except JobLookupError:\n                            pass\n                        break\n                if job_removed:\n                    logger.info(f"移除工作流服务：{service.get(\'name\')}")\n            except Exception as e:\n                logger.error(f"移除工作流服务失败：{str(e)} - {job_id}: {service}")\n                SchedulerChain().messagehelper.put(\n                    title=f"工作流 {workflow.name} 服务移除失败",\n                    message=str(e),\n                    role="system",\n                )\n\n    def remove_plugin_job(self, pid: str, job_id: Optional[str] = None):\n        """\n        移除定时服务，可以是单个服务（包括默认服务）或整个插件的所有服务\n        :param pid: 插件 ID\n        :param job_id: 可选，指定要移除的单个服务的 job_id。如果不提供，则移除该插件的所有服务，当移除单个服务时，默认服务也包含在内\n        """\n        if not self._scheduler:\n            return\n        with self._lock:\n            if job_id:\n                # 移除单个服务\n                service = self._jobs.pop(job_id, None)\n                if not service:\n                    return\n                jobs_to_remove = [(job_id, service)]\n            else:\n                # 移除插件的所有服务\n                jobs_to_remove = [\n                    (job_id, service)\n                    for job_id, service in self._jobs.items()\n                    if service.get("pid") == pid\n                ]\n                for job_id, _ in jobs_to_remove:\n                    self._jobs.pop(job_id, None)\n            if not jobs_to_remove:\n                return\n            plugin_name = PluginManager().get_plugin_attr(pid, "plugin_name")\n            # 遍历移除任务\n            for job_id, service in jobs_to_remove:\n                try:\n                    # 在调度器中查找并移除对应的 job\n                    job_removed = False\n                    for job in list(self._scheduler.get_jobs()):\n                        job_id_from_service = job.id.split("|")[0]\n                        if job_id == job_id_from_service:\n                            try:\n                                self._scheduler.remove_job(job.id)\n                                job_removed = True\n                            except JobLookupError:\n                                pass\n                    if job_removed:\n                        logger.info(\n                            f"移除插件服务({plugin_name})：{service.get(\'name\')}"\n                        )  # noqa\n                except Exception as e:\n                    logger.error(f"移除插件服务失败：{str(e)} - {job_id}: {service}")\n                    SchedulerChain().messagehelper.put(\n                        title=f"插件 {plugin_name} 服务移除失败",\n                        message=str(e),\n                        role="system",\n                    )\n\n    def update_workflow_job(self, workflow: Workflow):\n        """\n        更新工作流定时服务\n        """\n        if not self._scheduler:\n            return\n        # 移除该工作流的全部服务\n        self.remove_workflow_job(workflow)\n        # 添加工作流服务\n        with self._lock:\n            try:\n                job_id = f"workflow-{workflow.id}"\n                self._jobs[job_id] = {\n                    "func": WorkflowChain().process,\n                    "name": workflow.name,\n                    "provider_name": "工作流",\n                    "running": False,\n                }\n                self._scheduler.add_job(\n                    self.start,\n                    trigger=CronTrigger.from_crontab(workflow.timer),\n                    id=job_id,\n                    name=workflow.name,\n                    kwargs={"job_id": job_id, "workflow_id": workflow.id},\n                    replace_existing=True,\n                )\n                logger.info(f"注册工作流服务：{workflow.name} - {workflow.timer}")\n            except Exception as e:\n                logger.error(f"注册工作流服务失败：{workflow.name} - {str(e)}")\n                SchedulerChain().messagehelper.put(\n                    title=f"工作流 {workflow.name} 服务注册失败",\n                    message=str(e),\n                    role="system",\n                )\n\n    def update_plugin_job(self, pid: str):\n        """\n        更新插件定时服务\n        """\n        if not self._scheduler or not pid:\n            return\n        # 移除该插件的全部服务\n        self.remove_plugin_job(pid)\n        # 获取插件服务列表\n        with self._lock:\n            plugin_manager = PluginManager()\n            try:\n                plugin_services = plugin_manager.get_plugin_services(pid=pid)\n            except Exception as e:\n                logger.error(\n                    f"运行插件 {pid} 服务失败：{str(e)} - {traceback.format_exc()}"\n                )\n                return\n            # 获取插件名称\n            plugin_name = plugin_manager.get_plugin_attr(pid, "plugin_name")\n            # 开始注册插件服务\n            for service in plugin_services:\n                try:\n                    sid = f"{pid}_{service[\'id\']}"\n                    job_id = sid.split("|")[0]\n                    self.remove_plugin_job(pid, job_id)\n                    self._jobs[job_id] = {\n                        "func": service["func"],\n                        "name": service["name"],\n                        "pid": pid,\n                        "provider_name": plugin_name,\n                        "kwargs": service.get("func_kwargs") or {},\n                        "running": False,\n                    }\n                    self._scheduler.add_job(\n                        self.start,\n                        service["trigger"],\n                        id=sid,\n                        name=service["name"],\n                        **(service.get("kwargs") or {}),\n                        kwargs={"job_id": job_id},\n                        replace_existing=True,\n                    )\n                    logger.info(\n                        f"注册插件{plugin_name}服务：{service[\'name\']} - {service[\'trigger\']}"\n                    )\n                except Exception as e:\n                    logger.error(f"注册插件{plugin_name}服务失败：{str(e)} - {service}")\n                    SchedulerChain().messagehelper.put(\n                        title=f"插件 {plugin_name} 服务注册失败",\n                        message=str(e),\n                        role="system",\n                    )\n\n    def list(self) -> List[schemas.ScheduleInfo]:\n        """\n        当前所有任务\n        """\n        if not self._scheduler:\n            return []\n        with self._lock:\n            # 返回计时任务\n            schedulers = []\n            # 去重\n            added = []\n            # 避免_scheduler.shutdown()处于阻塞状态导致的死锁\n            if not self._scheduler or not self._scheduler.running:\n                return []\n            jobs = self._scheduler.get_jobs()\n            # 按照下次运行时间排序\n            jobs.sort(key=lambda x: x.next_run_time)\n            # 将正在运行的任务提取出来 (保障一次性任务正常显示)\n            for job_id, service in self._jobs.items():\n                name = service.get("name")\n                provider_name = service.get("provider_name")\n                if service.get("running") and name and provider_name:\n                    if job_id not in added:\n                        added.append(job_id)\n                    progress = self.get_progress(job_id)\n                    schedulers.append(\n                        schemas.ScheduleInfo(\n                            id=job_id,\n                            name=name,\n                            provider=provider_name,\n                            status="正在运行",\n                            progress=progress.value if progress else 0,\n                            progress_text=progress.text if progress else None,\n                            progress_enable=progress.enable if progress else False,\n                            progress_detail=progress,\n                        )\n                    )\n            # 获取其他待执行任务\n            for job in jobs:\n                job_id = job.id.split("|")[0]\n                if job_id not in added:\n                    added.append(job_id)\n                else:\n                    continue\n                service = self._jobs.get(job_id)\n                if not service:\n                    continue\n                # 任务状态\n                status = "正在运行" if service.get("running") else "等待"\n                # 下次运行时间\n                next_run = TimerUtils.time_difference(job.next_run_time)\n                progress = self.get_progress(job_id)\n                schedulers.append(\n                    schemas.ScheduleInfo(\n                        id=job_id,\n                        name=job.name,\n                        provider=service.get("provider_name", "[系统]"),\n                        status=status,\n                        next_run=next_run,\n                        progress=progress.value if progress else 0,\n                        progress_text=progress.text if progress else None,\n                        progress_enable=progress.enable if progress else False,\n                        progress_detail=progress,\n                    )\n                )\n            return schedulers\n\n    def stop(self):\n        """\n        关闭定时服务\n        """\n        with lock:\n            try:\n                if self._scheduler:\n                    logger.info("正在停止定时任务...")\n                    self._event.set()\n                    self._scheduler.remove_all_jobs()\n                    if self._scheduler.running:\n                        self._scheduler.shutdown()\n                    self._scheduler = None\n                    logger.info("定时任务停止完成")\n            except Exception as e:\n                logger.error(f"停止定时任务失败：：{str(e)} - {traceback.format_exc()}")\n\n    @staticmethod\n    def clear_cache():\n        """\n        清理缓存\n        """\n        SchedulerChain().clear_cache()\n\n    @staticmethod\n    def full_gc():\n        """\n        主动内存回收\n        """\n        memory_before = get_memory_usage()\n        collected = gc.collect()\n        memory_after = get_memory_usage()\n        memory_freed = memory_before - memory_after\n        logger.info(\n            f"主动内存回收完成，回收对象数: {collected}，释放内存: {memory_freed:.2f} MB"\n        )\n\n    @staticmethod\n    async def agent_heartbeat():\n        """\n        智能体心跳唤醒：检查并执行待处理的定时任务\n        """\n        from app.agent import agent_manager\n\n        await agent_manager.heartbeat_check_jobs()\n\n    def user_auth(self):\n        """\n        用户认证检查\n        """\n        if SitesHelper().auth_level >= 2:\n            return\n        # 最大重试次数\n        __max_try__ = 30\n        if self._auth_count > __max_try__:\n            if not self._auth_message:\n                SchedulerChain().messagehelper.put(\n                    title=f"用户认证失败",\n                    message="用户认证失败次数过多，将不再尝试认证！",\n                    role="system",\n                )\n                self._auth_message = True\n            return\n        logger.info("用户未认证，正在尝试认证...")\n        auth_conf = SystemConfigOper().get(SystemConfigKey.UserSiteAuthParams)\n        if auth_conf:\n            status, msg = SitesHelper().check_user(**auth_conf)\n        else:\n            status, msg = SitesHelper().check_user()\n        if status:\n            self._auth_count = 0\n            logger.info(f"{msg} 用户认证成功")\n            SchedulerChain().post_message(\n                Notification(\n                    mtype=NotificationType.Manual,\n                    title="MoviePilot用户认证成功",\n                    text=f"使用站点：{msg}，如有插件使用异常，请重启MoviePilot。",\n                    link=settings.MP_DOMAIN("#/site"),\n                )\n            )\n            # 认证通过后重新初始化插件\n            PluginManager().init_config()\n            self.init_plugin_jobs()\n\n        else:\n            self._auth_count += 1\n            logger.error(f"用户认证失败，{msg}，共失败 {self._auth_count} 次")\n            if self._auth_count >= __max_try__:\n                logger.error("用户认证失败次数过多，将不再尝试认证！")\n', 'systemconfig': 'import asyncio\nimport copy\nimport threading\nfrom typing import Any, Optional, Union\n\nfrom app.db import DbOper\nfrom app.db.models.systemconfig import SystemConfig\nfrom app.schemas.types import SystemConfigKey\nfrom app.utils.singleton import Singleton\n\n\nclass SystemConfigOper(DbOper, metaclass=Singleton):\n    """\n    系统配置管理\n    """\n    def __init__(self):\n        """\n        加载配置到内存\n        """\n        super().__init__()\n        self.__SYSTEMCONF = {}\n        self._rlock = threading.RLock()\n        self._alock = asyncio.Lock()\n        for item in SystemConfig.list(self._db):\n            self.__SYSTEMCONF[item.key] = item.value\n\n    def set(self, key: Union[str, SystemConfigKey], value: Any) -> Optional[bool]:\n        """\n        设置系统设置\n        :param key: 配置键\n        :param value: 配置值\n        :return: 是否设置成功（True 成功/False 失败/None 无需更新）\n        """\n        if isinstance(key, SystemConfigKey):\n            key = key.value\n        with self._rlock:\n            # 旧值\n            old_value = self.__SYSTEMCONF.get(key)\n            # 更新内存(deepcopy避免内存共享)\n            self.__SYSTEMCONF[key] = copy.deepcopy(value)\n            conf = SystemConfig.get_by_key(self._db, key)\n            if conf:\n                if old_value != value:\n                    if value:\n                        conf.update(self._db, {"value": value})\n                    else:\n                        conf.delete(self._db, conf.id)\n                    return True\n                return None\n            else:\n                conf = SystemConfig(key=key, value=value)\n                conf.create(self._db)\n                return True\n\n    async def async_set(self, key: Union[str, SystemConfigKey], value: Any) -> Optional[bool]:\n        """\n        异步设置系统设置\n        :param key: 配置键\n        :param value: 配置值\n        :return: 是否设置成功（True 成功/False 失败/None 无需更新）\n        """\n        if isinstance(key, SystemConfigKey):\n            key = key.value\n        async with self._alock:\n            conf = await SystemConfig.async_get_by_key(self._db, key)\n            # 确定是否需要更新数据库\n            needs_db_update = False\n            if conf:\n                if conf.value != value:\n                    needs_db_update = True\n            else:  # 记录不存在，总是需要创建/更新\n                needs_db_update = True\n            if not needs_db_update:\n                # 即使数据库值相同，也要确保缓存同步\n                with self._rlock:\n                    self.__SYSTEMCONF[key] = copy.deepcopy(value)\n                return None\n            # 执行数据库更新\n            if conf:\n                if value:\n                    await conf.async_update(self._db, {"value": value})\n                else:\n                    await conf.async_delete(self._db, conf.id)\n            else:\n                conf = SystemConfig(key=key, value=value)\n                await conf.async_create(self._db)\n            # 数据库更新成功后，再更新缓存\n            with self._rlock:\n                self.__SYSTEMCONF[key] = copy.deepcopy(value)\n            return True\n\n    def get(self, key: Union[str, SystemConfigKey] = None) -> Any:\n        """\n        获取系统设置\n        """\n        if isinstance(key, SystemConfigKey):\n            key = key.value\n        if not key:\n            return self.all()\n        with self._rlock:\n            # 避免将__SYSTEMCONF内的值引用出去，会导致set时误判没有变动\n            return copy.deepcopy(self.__SYSTEMCONF.get(key))\n\n    def increment(self, key: SystemConfigKey, step: int = 1) -> int:\n        """\n        原子递增整数系统设置\n\n        :param key: 配置键\n        :param step: 递增步长\n        :return: 递增后的整数值\n        """\n        with self._rlock:\n            value = int(self.get(key) or 0) + step\n            self.set(key, value)\n            return value\n\n    def all(self):\n        """\n        获取所有系统设置\n        """\n        with self._rlock:\n            # 避免将__SYSTEMCONF内的值引用出去，会导致set时误判没有变动\n            return copy.deepcopy(self.__SYSTEMCONF)\n\n    def delete(self, key: Union[str, SystemConfigKey]) -> bool:\n        """\n        删除系统设置\n        """\n        if isinstance(key, SystemConfigKey):\n            key = key.value\n        with self._rlock:\n            # 更新内存\n            self.__SYSTEMCONF.pop(key, None)\n            # 写入数据库\n            conf = SystemConfig.get_by_key(self._db, key)\n            if conf:\n                conf.delete(self._db, conf.id)\n            return True\n', 'schema': 'from typing import Optional, List, Dict, Any\n\nfrom pydantic import BaseModel, Field\n\n\nclass Plugin(BaseModel):\n    """\n    插件信息\n    """\n    id: str = None\n    # 插件名称\n    plugin_name: Optional[str] = None\n    # 插件描述\n    plugin_desc: Optional[str] = None\n    # 插件图标\n    plugin_icon: Optional[str] = None\n    # 插件版本\n    plugin_version: Optional[str] = None\n    # 插件标签\n    plugin_label: Optional[str] = None\n    # 插件作者\n    plugin_author: Optional[str] = None\n    # 作者主页\n    author_url: Optional[str] = None\n    # 插件配置项ID前缀\n    plugin_config_prefix: Optional[str] = None\n    # 加载顺序\n    plugin_order: Optional[int] = 0\n    # 可使用的用户级别\n    auth_level: Optional[int] = 0\n    # 是否已安装\n    installed: Optional[bool] = False\n    # 运行状态\n    state: Optional[bool] = False\n    # 是否有详情页面\n    has_page: Optional[bool] = False\n    # 是否有新版本\n    has_update: Optional[bool] = False\n    # 主系统版本是否兼容\n    system_version_compatible: Optional[bool] = True\n    # 主系统版本兼容提示\n    system_version_message: Optional[str] = None\n    # 主系统版本限定范围\n    system_version: Optional[str] = None\n    # 是否声明支持通过 GitHub Release 资产安装\n    release: Optional[bool] = False\n    # 是否本地\n    is_local: Optional[bool] = False\n    # 仓库地址\n    repo_url: Optional[str] = None\n    # 安装次数\n    install_count: Optional[int] = 0\n    # 更新记录\n    history: Optional[dict] = Field(default_factory=dict)\n    # 添加时间，值越小表示越靠后发布\n    add_time: Optional[int] = 0\n    # 插件公钥\n    plugin_public_key: Optional[str] = None\n\n\nclass PluginDashboard(Plugin):\n    """\n    插件仪表盘\n    """\n    id: Optional[str] = None\n    # 名称\n    name: Optional[str] = None\n    # 仪表板key\n    key: Optional[str] = None\n    # 演染模式\n    render_mode: Optional[str] = Field(default="vuetify")\n    # 全局配置\n    attrs: Optional[dict] = Field(default_factory=dict)\n    # col列数\n    cols: Optional[dict] = Field(default_factory=dict)\n    # 页面元素\n    elements: Optional[List[dict]] = Field(default_factory=list)\n\n\nclass PluginSidebarNavItem(BaseModel):\n    """\n    插件侧栏导航项（前端全页路由）\n    """\n    plugin_id: str = Field(description="插件 ID")\n    nav_key: str = Field(description="导航键，对应 URL 段")\n    title: str = Field(description="侧栏标题")\n    icon: str = Field(default="mdi-puzzle", description="MDI 图标名")\n    section: str = Field(\n        description="分组：start / discovery / subscribe / organize / system",\n    )\n    permission: Optional[str] = Field(\n        default=None,\n        description="权限：subscribe / discovery / search / manage / admin",\n    )\n    order: int = Field(default=0, description="同组内排序，越小越靠前")\n\n\nclass PluginRatingRequest(BaseModel):\n    """插件评分请求"""\n\n    rating: float = Field(\n        ge=0.1,\n        le=5.0,\n        multiple_of=0.1,\n        description="评分，范围 0.1 至 5.0，精确到 0.1",\n    )\n\n\nclass PluginRating(BaseModel):\n    """插件评分结果"""\n\n    plugin_id: str = Field(description="插件 ID")\n    average_rating: float = Field(default=0.0, description="平均评分")\n    rating_count: int = Field(default=0, description="评分人数")\n    user_rating: Optional[float] = Field(default=None, description="当前安装实例评分")\n\n\nclass PluginMemoryInfo(BaseModel):\n    """插件内存信息"""\n    plugin_id: str = Field(description="插件ID")\n    plugin_name: str = Field(description="插件名称")\n    plugin_version: str = Field(description="插件版本")\n    total_memory_bytes: int = Field(description="总内存使用量(字节)")\n    total_memory_mb: float = Field(description="总内存使用量(MB)")\n    object_count: int = Field(description="对象数量")\n    calculation_time_ms: float = Field(description="计算耗时(毫秒)")\n    timestamp: float = Field(description="统计时间戳")\n    error: Optional[str] = Field(default=None, description="错误信息")\n    object_details: Optional[List[Dict[str, Any]]] = Field(default=None, description="大对象详情")\n', 'types': 'from enum import Enum\nfrom typing import Optional\n\n\n# 媒体类型\nclass MediaType(Enum):\n    MOVIE = \'电影\'\n    TV = \'电视剧\'\n    COLLECTION = \'系列\'\n    UNKNOWN = \'未知\'\n\n    @staticmethod\n    def from_agent(key: str) -> Optional["MediaType"]:\n        """\'movie\' -> MediaType.MOVIE, \'tv\' -> MediaType.TV, 否则 None"""\n        _map = {"movie": MediaType.MOVIE, "tv": MediaType.TV}\n        return _map.get(key.strip().lower() if key else "")\n\n    def to_agent(self) -> str:\n        """MediaType.MOVIE -> \'movie\', MediaType.TV -> \'tv\', 其他返回 .value"""\n        return {MediaType.MOVIE: "movie", MediaType.TV: "tv"}.get(self, self.value)\n\n\ndef media_type_to_agent(value) -> Optional[str]:\n    """将 MediaType 枚举或中文字符串统一转为 \'movie\'/\'tv\'"""\n    if isinstance(value, MediaType):\n        return value.to_agent()\n    if isinstance(value, str):\n        mt = MediaType.from_agent(value)\n        return mt.to_agent() if mt else value\n    return None\n\n\n# 排序类型枚举\nclass SortType(Enum):\n    TIME = "time"  # 按时间排序\n    COUNT = "count"  # 按人数排序\n    RATING = "rating"  # 按评分排序\n\n\n# 种子状态\nclass TorrentStatus(Enum):\n    TRANSFER = "可转移"\n    DOWNLOADING = "下载中"\n\n\n# 下载器任务查询状态\nclass TorrentQueryStatus(Enum):\n    ALL = "all"\n    TRANSFER = "transfer"\n    DOWNLOADING = "downloading"\n    COMPLETED = "completed"\n    PAUSED = "paused"\n\n\n# 下载器任务归一状态\nclass DownloadTaskState(Enum):\n    DOWNLOADING = "downloading"\n    PAUSED = "paused"\n    COMPLETED = "completed"\n\n\n# 异步广播事件\nclass EventType(Enum):\n    # 插件需要重载\n    PluginReload = "plugin.reload"\n    # 触发插件动作\n    PluginAction = "plugin.action"\n    # 插件触发事件\n    PluginTriggered = "plugin.triggered"\n    # 执行命令\n    CommandExcute = "command.excute"\n    # 站点已删除\n    SiteDeleted = "site.deleted"\n    # 站点已更新\n    SiteUpdated = "site.updated"\n    # 站点已刷新\n    SiteRefreshed = "site.refreshed"\n    # 媒体文件整理完成\n    TransferComplete = "transfer.complete"\n    # 媒体文件整理失败\n    TransferFailed = "transfer.failed"\n    # 字幕整理完成\n    SubtitleTransferComplete = "transfer.subtitle.complete"\n    # 字幕整理失败\n    SubtitleTransferFailed = "transfer.subtitle.failed"\n    # 音频文件整理完成\n    AudioTransferComplete = "transfer.audio.complete"\n    # 音频文件整理失败\n    AudioTransferFailed = "transfer.audio.failed"\n    # 下载已添加\n    DownloadAdded = "download.added"\n    # 删除历史记录\n    HistoryDeleted = "history.deleted"\n    # 删除下载源文件\n    DownloadFileDeleted = "downloadfile.deleted"\n    # 删除下载任务\n    DownloadDeleted = "download.deleted"\n    # 收到用户外来消息\n    UserMessage = "user.message"\n    # 收到Webhook消息\n    WebhookMessage = "webhook.message"\n    # 发送消息通知\n    NoticeMessage = "notice.message"\n    # 订阅已添加\n    SubscribeAdded = "subscribe.added"\n    # 订阅已调整\n    SubscribeModified = "subscribe.modified"\n    # 订阅已删除\n    SubscribeDeleted = "subscribe.deleted"\n    # 订阅已完成\n    SubscribeComplete = "subscribe.complete"\n    # 系统错误\n    SystemError = "system.error"\n    # 刮削元数据\n    MetadataScrape = "metadata.scrape"\n    # 模块需要重载\n    ModuleReload = "module.reload"\n    # 配置项更新\n    ConfigChanged = "config.updated"\n    # 消息交互动作\n    MessageAction = "message.action"\n    # 执行工作流\n    WorkflowExecute = "workflow.execute"\n    # Agent Tokens 用量\n    AgentTokensUsage = "agent.tokens.usage"\n\n\n# EventType中文名称翻译字典\nEVENT_TYPE_NAMES = {\n    EventType.PluginReload: "插件重载",\n    EventType.PluginAction: "触发插件动作",\n    EventType.PluginTriggered: "触发插件事件",\n    EventType.CommandExcute: "执行命令",\n    EventType.SiteDeleted: "站点已删除",\n    EventType.SiteUpdated: "站点已更新",\n    EventType.SiteRefreshed: "站点已刷新",\n    EventType.TransferComplete: "整理完成",\n    EventType.TransferFailed: "整理失败",\n    EventType.SubtitleTransferComplete: "字幕整理完成",\n    EventType.SubtitleTransferFailed: "字幕整理失败",\n    EventType.AudioTransferComplete: "音频整理完成",\n    EventType.AudioTransferFailed: "音频整理失败",\n    EventType.DownloadAdded: "添加下载",\n    EventType.HistoryDeleted: "删除历史记录",\n    EventType.DownloadFileDeleted: "删除下载源文件",\n    EventType.DownloadDeleted: "删除下载任务",\n    EventType.UserMessage: "收到用户消息",\n    EventType.WebhookMessage: "收到Webhook消息",\n    EventType.NoticeMessage: "发送消息通知",\n    EventType.SubscribeAdded: "添加订阅",\n    EventType.SubscribeModified: "订阅已调整",\n    EventType.SubscribeDeleted: "订阅已删除",\n    EventType.SubscribeComplete: "订阅已完成",\n    EventType.SystemError: "系统错误",\n    EventType.MetadataScrape: "刮削元数据",\n    EventType.ModuleReload: "模块重载",\n    EventType.ConfigChanged: "配置项更新",\n    EventType.MessageAction: "消息交互动作",\n    EventType.WorkflowExecute: "执行工作流",\n    EventType.AgentTokensUsage: "Agent Tokens 用量",\n}\n\n\n# 同步链式事件\nclass ChainEventType(Enum):\n    # 插件数据重置前\n    PluginDataReset = "plugin.data.reset"\n    # 名称识别\n    NameRecognize = "name.recognize"\n    # 认证验证\n    AuthVerification = "auth.verification"\n    # 认证拦截\n    AuthIntercept = "auth.intercept"\n    # 命令注册\n    CommandRegister = "command.register"\n    # 整理重命名\n    TransferRename = "transfer.rename"\n    # 整理重命名上下文构建\n    TransferRenameBuild = "transfer.rename.build"\n    # 整理拦截\n    TransferIntercept = "transfer.intercept"\n    # 整理覆盖检查\n    TransferOverwriteCheck = "transfer.overwrite.check"\n    # 资源选择\n    ResourceSelection = "resource.selection"\n    # 资源下载\n    ResourceDownload = "resource.download"\n    # 探索数据源\n    DiscoverSource = "discover.source"\n    # 媒体识别转换\n    MediaRecognizeConvert = "media.recognize.convert"\n    # 推荐数据源\n    RecommendSource = "recommend.source"\n    # 工作流执行\n    WorkflowExecution = "workflow.execution"\n    # 存储操作选择\n    StorageOperSelection = "storage.operation"\n    # Agent LLM 供应商选择\n    AgentLLMProvider = "agent.llm.provider"\n    # 订阅总集数刷新\n    SubscribeEpisodesRefresh = "subscribe.episodes.refresh"\n    # 订阅完成检查\n    SubscribeCompletionCheck = "subscribe.completion.check"\n\n\n# 系统配置Key字典\nclass SystemConfigKey(Enum):\n    # 下载器配置\n    Downloaders = "Downloaders"\n    # 媒体服务器配置\n    MediaServers = "MediaServers"\n    # 消息通知配置\n    Notifications = "Notifications"\n    # 通知场景开关设置\n    NotificationSwitchs = "NotificationSwitchs"\n    # 目录配置\n    Directories = "Directories"\n    # 挂载型本地盘是否删除空目录\n    MountedLocalDiskDeleteEmptyDirs = "MountedLocalDiskDeleteEmptyDirs"\n    # 存储配置\n    Storages = "Storages"\n    # 搜索站点范围\n    IndexerSites = "IndexerSites"\n    # 订阅站点范围\n    RssSites = "RssSites"\n    # 自定义制作组/字幕组\n    CustomReleaseGroups = "CustomReleaseGroups"\n    # 自定义占位符\n    Customization = "Customization"\n    # 自定义识别词\n    CustomIdentifiers = "CustomIdentifiers"\n    # 集数定位规则词表\n    EpisodeFormatRuleTable = "EpisodeFormatRuleTable"\n    # 转移屏蔽词\n    TransferExcludeWords = "TransferExcludeWords"\n    # 种子优先级规则\n    TorrentsPriority = "TorrentsPriority"\n    # 用户自定义规则\n    CustomFilterRules = "CustomFilterRules"\n    # 用户规则组\n    UserFilterRuleGroups = "UserFilterRuleGroups"\n    # 搜索默认过滤规则组\n    SearchFilterRuleGroups = "SearchFilterRuleGroups"\n    # 订阅默认过滤规则组\n    SubscribeFilterRuleGroups = "SubscribeFilterRuleGroups"\n    # 订阅默认参数\n    SubscribeDefaultParams = "SubscribeDefaultParams"\n    # 洗版默认过滤规则组\n    BestVersionFilterRuleGroups = "BestVersionFilterRuleGroups"\n    # 订阅统计\n    SubscribeReport = "SubscribeReport"\n    # 用户自定义CSS\n    UserCustomCSS = "UserCustomCSS"\n    # 用户已安装的插件\n    UserInstalledPlugins = "UserInstalledPlugins"\n    # 插件文件夹分组配置\n    PluginFolders = "PluginFolders"\n    # 默认电影订阅规则\n    DefaultMovieSubscribeConfig = "DefaultMovieSubscribeConfig"\n    # 默认电视剧订阅规则\n    DefaultTvSubscribeConfig = "DefaultTvSubscribeConfig"\n    # 用户站点认证参数\n    UserSiteAuthParams = "UserSiteAuthParams"\n    # Follow订阅分享者\n    FollowSubscribers = "FollowSubscribers"\n    # 通知发送时间\n    NotificationSendTime = "NotificationSendTime"\n    # AI智能体配置\n    AIAgentConfig = "AIAgentConfig"\n    # AI智能体外部MCP服务器配置\n    AIAgentMcpServers = "AIAgentMcpServers"\n    # 通知消息格式模板\n    NotificationTemplates = "NotificationTemplates"\n    # 通知中心清理时间\n    NotificationClearBefore = "NotificationClearBefore"\n    # 刮削开关设置\n    ScrapingSwitchs = "ScrapingSwitchs"\n    # 插件安装统计\n    PluginInstallReport = "PluginInstallReport"\n    # 配置向导状态\n    SetupWizardState = "SetupWizardState"\n    # 绿联影视登录会话缓存\n    UgreenSessionCache = "UgreenSessionCache"\n    # 共享媒体识别成功次数\n    MediaRecognizeShareCount = "MediaRecognizeShareCount"\n\n\n# 处理进度Key字典\nclass ProgressKey(Enum):\n    # 搜索\n    Search = "search"\n    # 整理\n    FileTransfer = "filetransfer"\n    # 批量重命名\n    BatchRename = "batchrename"\n\n\n# 媒体图片类型\nclass MediaImageType(Enum):\n    Poster = "poster_path"\n    Backdrop = "backdrop_path"\n\n\n# 消息类型\nclass NotificationType(Enum):\n    # 资源下载\n    Download = "资源下载"\n    # 整理入库\n    Organize = "整理入库"\n    # 订阅\n    Subscribe = "订阅"\n    # 站点消息\n    SiteMessage = "站点"\n    # 媒体服务器通知\n    MediaServer = "媒体服务器"\n    # 处理失败需要人工干预\n    Manual = "手动处理"\n    # 插件消息\n    Plugin = "插件"\n    # 智能体消息\n    Agent = "智能体"\n    # 其它消息\n    Other = "其它"\n\n\nclass ContentType(str, Enum):\n    """\n    消息内容类型\n    操作状态的通知消息类型标识\n    """\n    # 订阅添加成功\n    SubscribeAdded = "subscribeAdded"\n    # 订阅完成\n    SubscribeComplete = "subscribeComplete"\n    # 入库成功\n    OrganizeSuccess = "organizeSuccess"\n    # 下载开始(添加下载任务成功)\n    DownloadAdded = "downloadAdded"\n\n\n# 消息渠道\nclass MessageChannel(Enum):\n    """\n    消息渠道\n    """\n    Wechat = "微信"\n    Feishu = "飞书"\n    WechatClawBot = "微信ClawBot"\n    Telegram = "Telegram"\n    Slack = "Slack"\n    Discord = "Discord"\n    SynologyChat = "SynologyChat"\n    VoceChat = "VoceChat"\n    Web = "Web"\n    WebAgent = "WebAgent"\n    WebPush = "WebPush"\n    QQ = "QQ"\n\n\n# 下载器类型\nclass DownloaderType(Enum):\n    # Qbittorrent\n    Qbittorrent = "Qbittorrent"\n    # Transmission\n    Transmission = "Transmission"\n    # Rtorrent\n    Rtorrent = "Rtorrent"\n    # Aria2\n    # Aria2 = "Aria2"\n\n\n# 媒体服务器类型\nclass MediaServerType(Enum):\n    # Emby\n    Emby = "Emby"\n    # 极影视\n    ZSpace = "ZSpace"\n    # Jellyfin\n    Jellyfin = "Jellyfin"\n    # Plex\n    Plex = "Plex"\n    # 飞牛影视\n    TrimeMedia = "TrimeMedia"\n    # 绿联影视\n    Ugreen = "Ugreen"\n\n\n# 识别器类型\nclass MediaRecognizeType(Enum):\n    # 豆瓣\n    Douban = "豆瓣"\n    # TMDB\n    TMDB = "TheMovieDb"\n    # TVDB\n    TVDB = "TheTvDb"\n    # bangumi\n    Bangumi = "Bangumi"\n    # AniList\n    AniList = "AniList"\n\n\n# 用户配置Key字典\nclass UserConfigKey(Enum):\n    # 监控面板\n    Dashboard = "Dashboard"\n\n\n# 支持的存储类型\nclass StorageSchema(Enum):\n    # 存储类型\n    Local = "local"\n    Alipan = "alipan"\n    U115 = "u115"\n    Rclone = "rclone"\n    Alist = "alist"\n    AlistGo = "alistgo"\n    SMB = "smb"\n\n\n# 模块类型\nclass ModuleType(Enum):\n    # 下载器\n    Downloader = "downloader"\n    # 媒体服务器\n    MediaServer = "mediaserver"\n    # 消息服务\n    Notification = "notification"\n    # 媒体识别\n    MediaRecognize = "mediarecognize"\n    # 站点索引\n    Indexer = "indexer"\n    # 其它\n    Other = "other"\n\n\n# 其他杂项模块类型\nclass OtherModulesType(Enum):\n    # 字幕\n    Subtitle = "站点字幕"\n    # Fanart\n    Fanart = "Fanart"\n    # 文件整理\n    FileManager = "文件整理"\n    # 过滤器\n    Filter = "过滤器"\n    # 站点索引\n    Indexer = "站点索引"\n    # PostgreSQL\n    PostgreSQL = "PostgreSQL"\n    # Redis\n    Redis = "Redis"\n\n\nclass NameValueEnum(Enum):\n    """支持通过 name 或 value 实例化的枚举基类"""\n\n    @classmethod\n    def _missing_(cls, value):\n        if isinstance(value, str):\n            for member in cls:\n                if member.name.lower() == value.lower() or member.value == value:\n                    return member\n        return None\n\n\n# 刮削策略\nclass ScrapingPolicy(NameValueEnum):\n    MISSINGONLY = "仅缺失"\n    SKIP = "跳过"\n    OVERWRITE = "覆盖"\n\n\n# 刮削目标类型\nclass ScrapingTarget(NameValueEnum):\n    MOVIE = "电影"\n    TV = "电视剧"\n    SEASON = "季"\n    EPISODE = "集"\n\n\n# 刮削元数据类型\nclass ScrapingMetadata(NameValueEnum):\n    NFO = "NFO"\n    POSTER = "海报"\n    BACKDROP = "背景图"\n    LOGO = "Logo"\n    BANNER = "横幅图"\n    THUMB = "缩略图"\n    DISC = "光盘图"\n    CLEARART = "透明艺术图"\n    LANDSCAPE = "横版缩略图"\n', 'mps': 'import re\nimport socket\nimport ssl\nimport time\nfrom datetime import datetime, timezone\nfrom email.utils import parsedate_to_datetime\nfrom typing import List, Tuple, Dict, Any, Optional\nfrom urllib.parse import urlparse\n\nfrom app.log import logger\nfrom app.plugins import _PluginBase\nfrom app.utils.http import RequestUtils\n\n\nclass MPServerStatus(_PluginBase):\n    # 插件名称\n    plugin_name = "MoviePilot服务监控"\n    # 插件描述\n    plugin_desc = "在仪表板中实时显示MoviePilot公共服务器状态。"\n    # 插件图标\n    plugin_icon = "Duplicati_A.png"\n    # 插件版本\n    plugin_version = "1.4"\n    # 插件作者\n    plugin_author = "jxxghp"\n    # 作者主页\n    author_url = "https://github.com/jxxghp"\n    # 插件配置项ID前缀\n    plugin_config_prefix = "MPServer_"\n    # 加载顺序\n    plugin_order = 99\n    # 可使用的用户级别\n    auth_level = 1\n\n    _enable: bool = False\n    _server_base = "https://movie-pilot.org/status"\n    _status_timeout = 20\n    _network_timeout = 5\n    _dns_cache_seconds = 60\n    _tls_cache_seconds = 3600\n    _last_sample: Optional[Dict[str, Any]] = None\n    _dns_cache: Optional[Tuple[float, Dict[str, Any]]] = None\n    _tls_cache: Optional[Tuple[float, Dict[str, Any]]] = None\n\n    def init_plugin(self, config: dict = None):\n        """\n        初始化插件配置和运行时缓存。\n        """\n        config = config or {}\n        self._enable = bool(config.get("enable"))\n        self._last_sample: Optional[Dict[str, Any]] = None\n        self._dns_cache: Optional[Tuple[float, Dict[str, Any]]] = None\n        self._tls_cache: Optional[Tuple[float, Dict[str, Any]]] = None\n\n    @staticmethod\n    def get_command() -> List[Dict[str, Any]]:\n        """\n        返回插件远程命令定义。\n        """\n        return []\n\n    def get_api(self) -> List[Dict[str, Any]]:\n        """\n        返回插件开放 API 定义。\n        """\n        return []\n\n    def get_form(self) -> Tuple[List[dict], Dict[str, Any]]:\n        """\n        拼装插件配置表单。\n        """\n        return [\n            {\n                \'component\': \'VForm\',\n                \'content\': [\n                    {\n                        \'component\': \'VRow\',\n                        \'content\': [\n                            {\n                                \'component\': \'VCol\',\n                                \'props\': {\n                                    \'cols\': 12,\n                                    \'md\': 6\n                                },\n                                \'content\': [\n                                    {\n                                        \'component\': \'VSwitch\',\n                                        \'props\': {\n                                            \'model\': \'enable\',\n                                            \'label\': \'启用插件\',\n                                        }\n                                    }\n                                ]\n                            }\n                        ]\n                    }\n                ]\n            }\n        ], {\n            "enable": self._enable,\n        }\n\n    def get_page(self) -> List[dict]:\n        """\n        获取插件详情页面。\n        """\n        if not self._enable:\n            return [\n                {\n                    \'component\': \'div\',\n                    \'text\': \'插件未启用\',\n                    \'props\': {\n                        \'class\': \'text-center\',\n                    }\n                }\n            ]\n        metrics, probe, dns_info, tls_info, error_message = self._load_status_snapshot()\n        if error_message or not metrics:\n            return self._build_unavailable_elements(\n                probe=probe,\n                dns_info=dns_info,\n                tls_info=tls_info,\n                message=error_message or "无法连接服务器"\n            )\n        return self._build_status_elements(\n            metrics=metrics,\n            probe=probe,\n            dns_info=dns_info,\n            tls_info=tls_info\n        )\n\n    def get_dashboard(self) -> Optional[Tuple[Dict[str, Any], Dict[str, Any], List[dict]]]:\n        """\n        获取插件仪表盘页面。\n        """\n        cols = {\n            "cols": 12,\n            "md": 8\n        }\n        attrs = {\n            "refresh": 10\n        }\n\n        metrics, probe, _, _, error_message = self._load_status_snapshot(include_network_details=False)\n        if error_message or not metrics:\n            elements = self._build_dashboard_unavailable_elements(\n                probe=probe,\n                message=error_message or "无法连接服务器"\n            )\n        else:\n            elements = self._build_dashboard_elements(metrics=metrics, probe=probe)\n        return cols, attrs, elements\n\n    def get_state(self) -> bool:\n        """\n        返回插件启用状态。\n        """\n        return self._enable\n\n    def stop_service(self):\n        """\n        停止插件服务。\n        """\n        pass\n\n    def _load_status_snapshot(\n            self,\n            include_network_details: bool = True\n    ) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any], Dict[str, Any], Dict[str, Any], Optional[str]]:\n        """\n        拉取服务状态并按页面需要整理为统一快照。\n        """\n        response, seconds, request_error = self._request_server_status()\n        probe = self._build_http_probe(response=response, seconds=seconds, request_error=request_error)\n        dns_info = self._get_dns_info() if include_network_details else {}\n        tls_info = self._get_tls_info() if include_network_details else {}\n\n        if request_error or not response:\n            return None, probe, dns_info, tls_info, request_error or "无法连接服务器"\n\n        try:\n            status = self._parse_status_text(response.text)\n            metrics = self._build_metrics(status=status, seconds=seconds)\n            return metrics, probe, dns_info, tls_info, None\n        except Exception as err:\n            logger.warn(f"解析服务器状态失败：{err}")\n            return None, probe, dns_info, tls_info, f"服务器状态格式异常：{err}"\n\n    def _request_server_status(self) -> Tuple[Optional[Any], float, Optional[str]]:\n        """\n        请求 MoviePilot 公开状态接口并返回响应、耗时和错误信息。\n        """\n        start_time = time.time()\n        logger.info(f"请求服务器状态 {self._server_base}...")\n        try:\n            try:\n                response = RequestUtils(timeout=self._status_timeout).get_res(self._server_base)\n            except TypeError:\n                response = RequestUtils().get_res(self._server_base)\n        except Exception as err:\n            seconds = time.time() - start_time\n            logger.warn(f"请求服务器状态异常：{err}")\n            return None, seconds, str(err)\n\n        seconds = time.time() - start_time\n        logger.info(f"请求耗时：{seconds:.3f}秒")\n        if response is None:\n            logger.warn("请求服务器状态失败：网络错误")\n            return None, seconds, "网络错误"\n        return response, seconds, None\n\n    @staticmethod\n    def _parse_status_text(text: str) -> Dict[str, int]:\n        """\n        解析 Nginx stub_status 文本。\n        """\n        lines = [line.strip() for line in (text or "").strip().splitlines() if line.strip()]\n        active_match = re.search(r"Active connections:\\s*(\\d+)", "\\n".join(lines), re.IGNORECASE)\n        rw_match = re.search(\n            r"Reading:\\s*(\\d+)\\s+Writing:\\s*(\\d+)\\s+Waiting:\\s*(\\d+)",\n            "\\n".join(lines),\n            re.IGNORECASE\n        )\n        counter_values = None\n        for index, line in enumerate(lines):\n            if "server accepts" in line.lower() and index + 1 < len(lines):\n                numbers = re.findall(r"\\d+", lines[index + 1])\n                if len(numbers) >= 3:\n                    counter_values = [int(numbers[0]), int(numbers[1]), int(numbers[2])]\n                    break\n        if counter_values is None:\n            for line in lines:\n                numbers = re.findall(r"\\d+", line)\n                if len(numbers) == 3 and "Reading" not in line and "Writing" not in line:\n                    counter_values = [int(numbers[0]), int(numbers[1]), int(numbers[2])]\n                    break\n\n        if not active_match:\n            raise ValueError("缺少活跃连接数据")\n        if not counter_values:\n            raise ValueError("缺少连接计数数据")\n        if not rw_match:\n            raise ValueError("缺少读写等待数据")\n\n        return {\n            "active_connections": int(active_match.group(1)),\n            "accepts": counter_values[0],\n            "handled": counter_values[1],\n            "requests": counter_values[2],\n            "reading": int(rw_match.group(1)),\n            "writing": int(rw_match.group(2)),\n            "waiting": int(rw_match.group(3)),\n        }\n\n    def _build_metrics(self, status: Dict[str, int], seconds: float) -> Dict[str, Any]:\n        """\n        基于当前状态和上次采样值计算派生监控指标。\n        """\n        now = time.time()\n        active_connections = status.get("active_connections", 0)\n        accepts = status.get("accepts", 0)\n        handled = status.get("handled", 0)\n        total_requests = status.get("requests", 0)\n        reading = status.get("reading", 0)\n        writing = status.get("writing", 0)\n        waiting = status.get("waiting", 0)\n        busy = reading + writing\n        dropped = max(accepts - handled, 0)\n\n        metrics = {\n            **status,\n            "seconds": seconds,\n            "busy": busy,\n            "dropped": dropped,\n            "busy_percent": self._safe_percent(busy, active_connections),\n            "reading_percent": self._safe_percent(reading, active_connections),\n            "writing_percent": self._safe_percent(writing, active_connections),\n            "waiting_percent": self._safe_percent(waiting, active_connections),\n            "dropped_percent": self._safe_percent(dropped, accepts),\n            "requests_per_connection": self._safe_ratio(total_requests, handled),\n            "requests_rate": None,\n            "accepts_rate": None,\n            "handled_rate": None,\n            "sample_seconds": None,\n        }\n\n        if self._last_sample:\n            sample_seconds = now - self._last_sample.get("timestamp", now)\n            if sample_seconds > 0:\n                metrics["sample_seconds"] = sample_seconds\n                metrics["requests_rate"] = self._safe_delta_rate(\n                    total_requests,\n                    self._last_sample.get("requests", total_requests),\n                    sample_seconds\n                )\n                metrics["accepts_rate"] = self._safe_delta_rate(\n                    accepts,\n                    self._last_sample.get("accepts", accepts),\n                    sample_seconds\n                )\n                metrics["handled_rate"] = self._safe_delta_rate(\n                    handled,\n                    self._last_sample.get("handled", handled),\n                    sample_seconds\n                )\n\n        self._last_sample = {\n            "timestamp": now,\n            "accepts": accepts,\n            "handled": handled,\n            "requests": total_requests,\n        }\n        return metrics\n\n    def _build_http_probe(self, response: Optional[Any], seconds: float, request_error: Optional[str]) -> Dict[str, Any]:\n        """\n        从 HTTP 响应中提取可展示的服务探测信息。\n        """\n        headers = getattr(response, "headers", {}) or {}\n        content = getattr(response, "content", b"") or b""\n        text = getattr(response, "text", "") or ""\n        status_code = getattr(response, "status_code", None)\n        protocol = self._format_http_version(getattr(getattr(response, "raw", None), "version", None))\n        content_bytes = len(content) if content else len(text.encode("utf-8"))\n\n        return {\n            "url": self._server_base,\n            "host": urlparse(self._server_base).hostname or "-",\n            "status_code": status_code,\n            "ok": bool(status_code and 200 <= int(status_code) < 400 and not request_error),\n            "seconds": seconds,\n            "protocol": protocol,\n            "server": headers.get("Server") or "-",\n            "date": self._format_response_date(headers.get("Date")),\n            "content_type": headers.get("Content-Type") or "-",\n            "content_bytes": content_bytes,\n            "error": request_error or "",\n        }\n\n    def _get_dns_info(self) -> Dict[str, Any]:\n        """\n        解析服务器域名并缓存短时间内的 DNS 探测结果。\n        """\n        now = time.time()\n        if self._dns_cache and now - self._dns_cache[0] < self._dns_cache_seconds:\n            return self._dns_cache[1]\n\n        parsed = urlparse(self._server_base)\n        host = parsed.hostname or ""\n        port = parsed.port or (443 if parsed.scheme == "https" else 80)\n        start_time = time.time()\n        try:\n            address_info = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)\n            ips = []\n            for address in address_info:\n                ip = address[4][0]\n                if ip not in ips:\n                    ips.append(ip)\n            info = {\n                "host": host,\n                "port": port,\n                "ips": ips,\n                "seconds": time.time() - start_time,\n                "error": "",\n            }\n        except Exception as err:\n            info = {\n                "host": host,\n                "port": port,\n                "ips": [],\n                "seconds": time.time() - start_time,\n                "error": str(err),\n            }\n\n        self._dns_cache = (now, info)\n        return info\n\n    def _get_tls_info(self) -> Dict[str, Any]:\n        """\n        探测 HTTPS 证书信息并缓存较长时间的 TLS 结果。\n        """\n        parsed = urlparse(self._server_base)\n        if parsed.scheme != "https":\n            return {\n                "enabled": False,\n                "error": "",\n            }\n\n        now = time.time()\n        if self._tls_cache and now - self._tls_cache[0] < self._tls_cache_seconds:\n            return self._tls_cache[1]\n\n        host = parsed.hostname or ""\n        port = parsed.port or 443\n        start_time = time.time()\n        try:\n            context = ssl.create_default_context()\n            with socket.create_connection((host, port), timeout=self._network_timeout) as sock:\n                with context.wrap_socket(sock, server_hostname=host) as tls_sock:\n                    cert = tls_sock.getpeercert()\n                    not_after = cert.get("notAfter")\n                    expires_at = datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z").replace(tzinfo=timezone.utc)\n                    days_left = int((expires_at - datetime.now(timezone.utc)).total_seconds() // 86400)\n                    info = {\n                        "enabled": True,\n                        "version": tls_sock.version() or "-",\n                        "issuer": self._extract_certificate_name(cert.get("issuer")),\n                        "subject": self._extract_certificate_name(cert.get("subject")),\n                        "expires_at": expires_at.strftime("%Y-%m-%d %H:%M UTC"),\n                        "days_left": days_left,\n                        "seconds": time.time() - start_time,\n                        "error": "",\n                    }\n        except Exception as err:\n            info = {\n                "enabled": True,\n                "version": "-",\n                "issuer": "-",\n                "subject": "-",\n                "expires_at": "-",\n                "days_left": None,\n                "seconds": time.time() - start_time,\n                "error": str(err),\n            }\n\n        self._tls_cache = (now, info)\n        return info\n\n    @staticmethod\n    def _extract_certificate_name(items: Any) -> str:\n        """\n        从证书 subject 或 issuer 元组中提取可读名称。\n        """\n        if not items:\n            return "-"\n        for group in items:\n            for key, value in group:\n                if key == "commonName":\n                    return value\n        for group in items:\n            for _, value in group:\n                if value:\n                    return value\n        return "-"\n\n    def _build_dashboard_elements(self, metrics: Dict[str, Any], probe: Dict[str, Any]) -> List[dict]:\n        """\n        拼装状态正常时的轻量仪表板元素。\n        """\n        return [\n            self._build_summary_alert(probe=probe, message="服务状态正常", alert_type="success"),\n            {\n                \'component\': \'VRow\',\n                \'content\': self._build_dashboard_cards(metrics=metrics, probe=probe)\n            }\n        ]\n\n    def _build_dashboard_unavailable_elements(self, probe: Dict[str, Any], message: str) -> List[dict]:\n        """\n        拼装状态不可用时的轻量仪表板元素。\n        """\n        return [\n            self._build_summary_alert(probe=probe, message=message, alert_type="error"),\n            {\n                \'component\': \'VRow\',\n                \'content\': self._build_dashboard_cards(metrics=None, probe=probe)\n            }\n        ]\n\n    def _build_dashboard_cards(self, metrics: Optional[Dict[str, Any]], probe: Dict[str, Any]) -> List[dict]:\n        """\n        构建仪表板需要展示的核心监控卡片。\n        """\n        sample_caption = self._format_sample_caption(metrics.get("sample_seconds")) if metrics else "暂无采样"\n        return [\n            self._build_stat_card(\n                "响应延迟",\n                self._format_seconds(probe.get("seconds")),\n                "mdi-speedometer",\n                self._latency_color(probe.get("seconds"), probe.get("ok")),\n                f"HTTP {probe.get(\'status_code\') or \'-\'}",\n                cols=12,\n                sm=6,\n                md=4\n            ),\n            self._build_stat_card(\n                "活跃连接",\n                self._format_integer(metrics.get("active_connections")) if metrics else "-",\n                "mdi-lan-connect",\n                "primary",\n                f"忙碌 {self._format_percent(metrics.get(\'busy_percent\'))}" if metrics else "暂无连接数据",\n                cols=12,\n                sm=6,\n                md=4\n            ),\n            self._build_stat_card(\n                "等待连接",\n                self._format_integer(metrics.get("waiting")) if metrics else "-",\n                "mdi-timer-sand",\n                "warning",\n                f"{self._format_percent(metrics.get(\'waiting_percent\'))} 空闲" if metrics else "暂无连接数据",\n                cols=12,\n                sm=6,\n                md=4\n            ),\n            self._build_stat_card(\n                "处理中连接",\n                self._format_integer(metrics.get("busy")) if metrics else "-",\n                "mdi-swap-horizontal",\n                "warning",\n                f"读 {metrics.get(\'reading\', 0)} / 写 {metrics.get(\'writing\', 0)}" if metrics else "暂无连接数据",\n                cols=12,\n                sm=6,\n                md=4\n            ),\n            self._build_stat_card(\n                "请求速率",\n                self._format_rate(metrics.get("requests_rate"), "次/秒") if metrics else "-",\n                "mdi-chart-timeline-variant",\n                "primary",\n                sample_caption,\n                cols=12,\n                sm=6,\n                md=4\n            ),\n            self._build_stat_card(\n                "连接速度",\n                self._format_rate(metrics.get("accepts_rate"), "个/秒") if metrics else "-",\n                "mdi-connection",\n                "info",\n                sample_caption,\n                cols=12,\n                sm=6,\n                md=4\n            ),\n        ]\n\n    def _build_status_elements(\n            self,\n            metrics: Dict[str, Any],\n            probe: Dict[str, Any],\n            dns_info: Dict[str, Any],\n            tls_info: Dict[str, Any]\n    ) -> List[dict]:\n        """\n        拼装状态正常时的详情页元素。\n        """\n        cards = [\n            self._build_stat_card("HTTP状态", str(probe.get("status_code") or "-"), "mdi-web-check", "success",\n                                  probe.get("protocol") or "-"),\n            self._build_stat_card("响应延迟", self._format_seconds(probe.get("seconds")), "mdi-speedometer", "info",\n                                  f"{self._format_size(probe.get(\'content_bytes\', 0))} 响应"),\n            self._build_stat_card("活跃连接", self._format_integer(metrics.get("active_connections")), "mdi-lan-connect",\n                                  "primary", f"忙碌 {self._format_percent(metrics.get(\'busy_percent\'))}"),\n            self._build_stat_card("请求速率", self._format_rate(metrics.get("requests_rate"), "次/秒"),\n                                  "mdi-chart-timeline-variant", "primary",\n                                  self._format_sample_caption(metrics.get("sample_seconds"))),\n            self._build_stat_card("连接速率", self._format_rate(metrics.get("accepts_rate"), "个/秒"),\n                                  "mdi-connection", "info",\n                                  self._format_sample_caption(metrics.get("sample_seconds"))),\n            self._build_stat_card("等待连接", self._format_integer(metrics.get("waiting")), "mdi-timer-sand", "warning",\n                                  f"{self._format_percent(metrics.get(\'waiting_percent\'))} 空闲"),\n            self._build_stat_card("处理中连接", self._format_integer(metrics.get("busy")), "mdi-swap-horizontal",\n                                  "warning",\n                                  f"读 {metrics.get(\'reading\', 0)} / 写 {metrics.get(\'writing\', 0)}"),\n            self._build_stat_card("请求/连接", self._format_float(metrics.get("requests_per_connection")),\n                                  "mdi-counter", "secondary", "累计均值"),\n            self._build_stat_card("总请求数", self._format_integer(metrics.get("requests")),\n                                  "mdi-format-list-numbered", "primary", "Nginx 累计"),\n            self._build_stat_card("总连接数", self._format_integer(metrics.get("accepts")), "mdi-server-network",\n                                  "primary", "Nginx 累计"),\n            self._build_stat_card("丢弃连接", self._format_integer(metrics.get("dropped")), "mdi-alert-circle-outline",\n                                  self._severity_color(metrics.get("dropped", 0), warning=1, error=10),\n                                  self._format_percent(metrics.get("dropped_percent"))),\n            self._build_stat_card("TLS证书", self._format_tls_days(tls_info), "mdi-shield-lock-outline",\n                                  self._tls_color(tls_info), tls_info.get("expires_at") or "-"),\n        ]\n\n        return [\n            self._build_summary_alert(probe=probe, message="服务状态正常", alert_type="success"),\n            {\n                \'component\': \'VRow\',\n                \'content\': cards + [\n                    self._build_info_table(\n                        title="连接明细",\n                        rows=[\n                            ("Reading", self._format_connection_detail(metrics.get("reading"),\n                                                                      metrics.get("reading_percent"))),\n                            ("Writing", self._format_connection_detail(metrics.get("writing"),\n                                                                      metrics.get("writing_percent"))),\n                            ("Waiting", self._format_connection_detail(metrics.get("waiting"),\n                                                                      metrics.get("waiting_percent"))),\n                            ("Handled", self._format_integer(metrics.get("handled"))),\n                            ("Dropped", f"{self._format_integer(metrics.get(\'dropped\'))} / "\n                                        f"{self._format_percent(metrics.get(\'dropped_percent\'))}"),\n                        ]\n                    ),\n                    self._build_info_table(\n                        title="服务探测",\n                        rows=[\n                            ("域名", f"{dns_info.get(\'host\')}:{dns_info.get(\'port\')}"),\n                            ("解析IP", self._format_ips(dns_info.get("ips", []), dns_info.get("error"))),\n                            ("DNS耗时", self._format_seconds(dns_info.get("seconds"))),\n                            ("TLS版本", tls_info.get("version") or "-"),\n                            ("证书签发", tls_info.get("issuer") or "-"),\n                            ("服务时间", probe.get("date") or "-"),\n                            ("Server", probe.get("server") or "-"),\n                            ("Content-Type", probe.get("content_type") or "-"),\n                        ]\n                    )\n                ]\n            }\n        ]\n\n    def _build_unavailable_elements(\n            self,\n            probe: Dict[str, Any],\n            dns_info: Dict[str, Any],\n            tls_info: Dict[str, Any],\n            message: str\n    ) -> List[dict]:\n        """\n        拼装状态不可用或解析失败时的详情页元素。\n        """\n        return [\n            self._build_summary_alert(probe=probe, message=message, alert_type="error"),\n            {\n                \'component\': \'VRow\',\n                \'content\': [\n                    self._build_stat_card("HTTP状态", str(probe.get("status_code") or "-"), "mdi-web-cancel", "error",\n                                          probe.get("error") or probe.get("protocol") or "-"),\n                    self._build_stat_card("响应延迟", self._format_seconds(probe.get("seconds")),\n                                          "mdi-speedometer-slow", "warning", "本次探测"),\n                    self._build_stat_card("DNS解析", str(len(dns_info.get("ips", []))), "mdi-dns-outline",\n                                          self._severity_color(len(dns_info.get("ips", [])), warning=1, error=0),\n                                          self._format_ips(dns_info.get("ips", []), dns_info.get("error"))),\n                    self._build_stat_card("TLS证书", self._format_tls_days(tls_info), "mdi-shield-lock-outline",\n                                          self._tls_color(tls_info), tls_info.get("expires_at") or "-"),\n                    self._build_info_table(\n                        title="服务探测",\n                        rows=[\n                            ("地址", probe.get("url") or "-"),\n                            ("域名", f"{dns_info.get(\'host\')}:{dns_info.get(\'port\')}"),\n                            ("解析IP", self._format_ips(dns_info.get("ips", []), dns_info.get("error"))),\n                            ("DNS耗时", self._format_seconds(dns_info.get("seconds"))),\n                            ("TLS版本", tls_info.get("version") or "-"),\n                            ("TLS错误", tls_info.get("error") or "-"),\n                            ("Server", probe.get("server") or "-"),\n                            ("Content-Type", probe.get("content_type") or "-"),\n                        ],\n                        md=12\n                    )\n                ]\n            }\n        ]\n\n    @staticmethod\n    def _build_summary_alert(probe: Dict[str, Any], message: str, alert_type: str) -> dict:\n        """\n        构建仪表盘顶部状态提示。\n        """\n        status_code = probe.get("status_code") or "-"\n        return {\n            \'component\': \'VAlert\',\n            \'props\': {\n                \'type\': alert_type,\n                \'variant\': \'tonal\',\n                \'density\': \'compact\',\n                \'class\': \'mb-3\'\n            },\n            \'text\': f"{message} · HTTP {status_code} · {probe.get(\'host\') or \'-\'}"\n        }\n\n    @staticmethod\n    def _build_stat_card(\n            label: str,\n            value: str,\n            icon: str,\n            color: str,\n            subtitle: str = "",\n            cols: int = 6,\n            sm: Optional[int] = None,\n            md: int = 3\n    ) -> dict:\n        """\n        构建单个统计指标卡片。\n        """\n        col_props = {\n            \'cols\': cols,\n            \'md\': md\n        }\n        if sm:\n            col_props[\'sm\'] = sm\n        return {\n            \'component\': \'VCol\',\n            \'props\': col_props,\n            \'content\': [\n                {\n                    \'component\': \'VCard\',\n                    \'props\': {\n                        \'variant\': \'tonal\',\n                        \'class\': \'h-100\',\n                    },\n                    \'content\': [\n                        {\n                            \'component\': \'VCardText\',\n                            \'props\': {\n                                \'class\': \'d-flex align-center ga-3\'\n                            },\n                            \'content\': [\n                                {\n                                    \'component\': \'div\',\n                                    \'props\': {\n                                        \'class\': \'flex-grow-1\',\n                                        \'style\': \'min-width: 0;\'\n                                    },\n                                    \'content\': [\n                                        {\n                                            \'component\': \'span\',\n                                            \'props\': {\n                                                \'class\': \'text-caption text-medium-emphasis text-truncate d-block\'\n                                            },\n                                            \'text\': label\n                                        },\n                                        {\n                                            \'component\': \'div\',\n                                            \'props\': {\n                                                \'class\': \'text-h6 text-truncate\'\n                                            },\n                                            \'text\': value\n                                        },\n                                        {\n                                            \'component\': \'div\',\n                                            \'props\': {\n                                                \'class\': \'text-caption text-medium-emphasis text-truncate\'\n                                            },\n                                            \'text\': subtitle or "-"\n                                        }\n                                    ]\n                                },\n                                {\n                                    \'component\': \'VIcon\',\n                                    \'props\': {\n                                        \'color\': color,\n                                        \'size\': \'28\',\n                                        \'class\': \'flex-shrink-0\'\n                                    },\n                                    \'text\': icon\n                                }\n                            ]\n                        }\n                    ]\n                }\n            ]\n        }\n\n    @staticmethod\n    def _build_info_table(title: str, rows: List[Tuple[str, str]], md: int = 6) -> dict:\n        """\n        构建键值详情表格。\n        """\n        return {\n            \'component\': \'VCol\',\n            \'props\': {\n                \'cols\': 12,\n                \'md\': md\n            },\n            \'content\': [\n                {\n                    \'component\': \'VCard\',\n                    \'props\': {\n                        \'variant\': \'tonal\',\n                    },\n                    \'content\': [\n                        {\n                            \'component\': \'VCardTitle\',\n                            \'props\': {\n                                \'class\': \'text-subtitle-1\'\n                            },\n                            \'text\': title\n                        },\n                        {\n                            \'component\': \'VTable\',\n                            \'props\': {\n                                \'hover\': True,\n                                \'density\': \'compact\'\n                            },\n                            \'content\': [\n                                {\n                                    \'component\': \'tbody\',\n                                    \'content\': [\n                                        {\n                                            \'component\': \'tr\',\n                                            \'content\': [\n                                                {\n                                                    \'component\': \'td\',\n                                                    \'props\': {\n                                                        \'class\': \'text-medium-emphasis text-no-wrap\'\n                                                    },\n                                                    \'text\': label\n                                                },\n                                                {\n                                                    \'component\': \'td\',\n                                                    \'props\': {\n                                                        \'class\': \'text-end\'\n                                                    },\n                                                    \'text\': value\n                                                }\n                                            ]\n                                        } for label, value in rows\n                                    ]\n                                }\n                            ]\n                        }\n                    ]\n                }\n            ]\n        }\n\n    @staticmethod\n    def _safe_percent(value: float, total: float) -> Optional[float]:\n        """\n        安全计算百分比。\n        """\n        if not total:\n            return None\n        return value / total * 100\n\n    @staticmethod\n    def _safe_ratio(value: float, total: float) -> Optional[float]:\n        """\n        安全计算比值。\n        """\n        if not total:\n            return None\n        return value / total\n\n    @staticmethod\n    def _safe_delta_rate(current: float, previous: float, seconds: float) -> Optional[float]:\n        """\n        安全计算两次采样之间的增长速率。\n        """\n        if seconds <= 0 or current < previous:\n            return None\n        return (current - previous) / seconds\n\n    @staticmethod\n    def _format_http_version(version: Optional[int]) -> str:\n        """\n        格式化 requests 原始 HTTP 协议版本。\n        """\n        if version == 10:\n            return "HTTP/1.0"\n        if version == 11:\n            return "HTTP/1.1"\n        if version == 20:\n            return "HTTP/2"\n        return "-"\n\n    @staticmethod\n    def _format_response_date(value: Optional[str]) -> str:\n        """\n        格式化 HTTP Date 响应头。\n        """\n        if not value:\n            return "-"\n        try:\n            return parsedate_to_datetime(value).strftime("%Y-%m-%d %H:%M:%S %Z")\n        except Exception:\n            return value\n\n    @staticmethod\n    def _format_integer(value: Optional[float]) -> str:\n        """\n        格式化整数显示。\n        """\n        if value is None:\n            return "-"\n        return f"{int(value):,}"\n\n    @staticmethod\n    def _format_float(value: Optional[float], precision: int = 2) -> str:\n        """\n        格式化小数显示。\n        """\n        if value is None:\n            return "-"\n        return f"{value:.{precision}f}"\n\n    @staticmethod\n    def _format_percent(value: Optional[float]) -> str:\n        """\n        格式化百分比显示。\n        """\n        if value is None:\n            return "-"\n        return f"{value:.1f}%"\n\n    @staticmethod\n    def _format_seconds(value: Optional[float]) -> str:\n        """\n        格式化秒级耗时显示。\n        """\n        if value is None:\n            return "-"\n        if value < 1:\n            return f"{value * 1000:.0f} ms"\n        return f"{value:.2f} 秒"\n\n    @staticmethod\n    def _format_rate(value: Optional[float], unit: str) -> str:\n        """\n        格式化速率显示。\n        """\n        if value is None:\n            return "待刷新"\n        return f"{value:.2f} {unit}"\n\n    @staticmethod\n    def _format_sample_caption(value: Optional[float]) -> str:\n        """\n        格式化采样窗口说明。\n        """\n        if value is None:\n            return "等待下一次采样"\n        return f"{value:.1f} 秒窗口"\n\n    @staticmethod\n    def _format_size(value: int) -> str:\n        """\n        格式化字节大小显示。\n        """\n        if value < 1024:\n            return f"{value} B"\n        if value < 1024 * 1024:\n            return f"{value / 1024:.1f} KB"\n        return f"{value / 1024 / 1024:.1f} MB"\n\n    @staticmethod\n    def _format_ips(ips: List[str], error: Optional[str] = None) -> str:\n        """\n        格式化 DNS 解析 IP 列表。\n        """\n        if error:\n            return error\n        if not ips:\n            return "-"\n        suffix = " ..." if len(ips) > 3 else ""\n        return f"{\', \'.join(ips[:3])}{suffix}"\n\n    def _format_connection_detail(self, value: Optional[int], percent: Optional[float]) -> str:\n        """\n        格式化连接数量和占比详情。\n        """\n        return f"{self._format_integer(value)} / {self._format_percent(percent)}"\n\n    @staticmethod\n    def _format_tls_days(tls_info: Dict[str, Any]) -> str:\n        """\n        格式化 TLS 证书剩余天数。\n        """\n        if not tls_info.get("enabled"):\n            return "未启用"\n        if tls_info.get("error"):\n            return "异常"\n        days_left = tls_info.get("days_left")\n        if days_left is None:\n            return "-"\n        return f"{days_left} 天"\n\n    @staticmethod\n    def _severity_color(value: float, warning: float, error: float) -> str:\n        """\n        根据阈值返回 Vuetify 颜色名称。\n        """\n        if error >= warning:\n            if value >= error:\n                return "error"\n            if value >= warning:\n                return "warning"\n            return "success"\n        if value <= error:\n            return "error"\n        if value <= warning:\n            return "warning"\n        return "success"\n\n    @staticmethod\n    def _latency_color(value: Optional[float], ok: bool) -> str:\n        """\n        根据 HTTP 探测耗时返回响应延迟卡片颜色。\n        """\n        if not ok:\n            return "error"\n        if value is None:\n            return "secondary"\n        if value < 1:\n            return "success"\n        if value < 3:\n            return "warning"\n        return "error"\n\n    @staticmethod\n    def _tls_color(tls_info: Dict[str, Any]) -> str:\n        """\n        根据 TLS 证书状态返回 Vuetify 颜色名称。\n        """\n        if not tls_info.get("enabled"):\n            return "secondary"\n        if tls_info.get("error"):\n            return "error"\n        days_left = tls_info.get("days_left")\n        if days_left is None or days_left < 7:\n            return "error"\n        if days_left < 30:\n            return "warning"\n        return "success"\n'}
import ast, copy, json, sys, typing, threading, hashlib, __future__
from enum import Enum
from pathlib import PurePosixPath
from types import SimpleNamespace
from pydantic import BaseModel, Field
trace = []
fail = None
db = {}
data = {}
existing = set()
residual = False

class Logger:

    def __getattr__(self, name):
        return lambda s: trace.append(['log', name, s])

class Row:

    def __init__(self, key, value):
        self.key = key
        self.value = copy.deepcopy(value)
        self.id = key

    def update(self, db_, values):
        trace.append(['db.update', self.key, copy.deepcopy(values['value'])])
